    layout: LayoutType.RIGHT_CORNER,
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Layout Cycling Logic
  const layouts = [
    { id: LayoutType.RIGHT_CORNER, label: 'Corner R' },
    { id: LayoutType.LEFT_CORNER, label: 'Corner L' },
    { id: LayoutType.BOTTOM_MIDDLE, label: 'Bottom' },
    { id: LayoutType.CINEMATIC, label: 'Cinematic' },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    updateData({ layout: layouts[nextIndex].id });
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    updateData({ layout: layouts[prevIndex].id });
