            {/* Poster Container */}
            <div className="bg-white p-3 rounded-3xl shadow-2xl border border-slate-100 relative">
                <div className="absolute inset-0 bg-blue-500/5 blur-2xl rounded-full transform scale-90 z-0"></div>
                <div className="relative z-10">
                    <PosterPreview data={data} ref={posterRef} onTriggerUpload={triggerUpload} />
                </div>
            </div>

            {/* Right Arrow */}
            <button 
                onClick={nextLayout}
                className="absolute -right-4 md:-right-12 top-1/2 -translate-y-1/2 z-20 bg-white/80 hover:bg-white text-slate-800 p-3 rounded-full shadow-lg backdrop-blur-sm transition-all hover:scale-110 border border-slate-200"
                title="Next Layout"
            >
                <ChevronRight size={24} />
            </button>

            {/* Layout Indicator */}
            <div className="absolute -bottom-8 left-0 right-0 flex justify-center items-center gap-2">
                 <span className="bg-slate-800 text-white text-[10px] uppercase font-bold px-3 py-1 rounded-full shadow-sm">
                    {layouts[currentLayoutIndex].label} Layout
                 </span>
                 <div className="flex gap-1">
                    {layouts.map((l, i) => (
                        <div key={l.id} className={`w-1.5 h-1.5 rounded-full transition-colors ${i === currentLayoutIndex ? 'bg-slate-800' : 'bg-slate-300'}`} />
                    ))}
                 </div>
            </div>
        </div>

        {/* Spacer for layout indicator */}
        <div className="h-4"></div>

        {/* 2. Action Buttons (Download & Share) */}
        <div className="flex gap-3 w-full">
            <button 
            onClick={handleDownload}
            className="flex-1 bg-slate-900 text-white py-3 rounded-xl font-bold shadow-lg shadow-slate-200 hover:bg-black transition-all flex justify-center items-center gap-2"
            >
            <Download size={18} /> Download
            </button>
            <button 
            onClick={handleShare}
