            </button>
          ))}
        </div>
      </div>

      {/* Background Generator */}
      <div className="p-4 bg-gradient-to-br from-indigo-600 to-blue-600 rounded-2xl shadow-lg text-white">
         <div className="flex justify-between items-center mb-1">
           <label className="text-sm font-bold flex items-center gap-2">
             <ImageIcon size={16} /> AI Background
           </label>
           <button 
