             disabled={isGeneratingBg}
             className="text-xs bg-white/20 hover:bg-white/30 border border-white/40 text-white px-3 py-1.5 rounded-lg disabled:opacity-50 flex items-center gap-1 transition-all backdrop-blur-sm"
           >
             {isGeneratingBg ? t('generating') : <><Sparkles size={12} /> {t('generate')}</>}
           </button>
         </div>
         <p className="text-xs text-blue-100 opacity-80">{t('ai_bg_desc')}</p>
      </div>

    </div>
  );
};

