import React, { forwardRef } from 'react';
import { PosterData, AppMode, TemplateStyle, LayoutType, TextEffect } from '../types';
import { Upload, Camera, Image as ImageIcon } from 'lucide-react';

interface Props {
  data: PosterData;
  scale?: number;
  onTriggerUpload?: (field: keyof PosterData) => void;
}

const PosterPreview = forwardRef<HTMLDivElement, Props>(({ data, scale = 1, onTriggerUpload }, ref) => {
  // Styles based on template
  const getTemplateStyles = () => {
    switch (data.template) {
      case TemplateStyle.MINIMAL:
        return { overlay: "bg-white/90", textBase: "text-slate-900" };
      case TemplateStyle.NATURE:
        return { overlay: "bg-black/20", textBase: "text-white" };
      case TemplateStyle.ABSTRACT:
        return { overlay: "bg-purple-900/40", textBase: "text-white" };
      case TemplateStyle.GOLDEN:
        return { overlay: "bg-black/60", textBase: "text-amber-100" };
      case TemplateStyle.GRADIENT:
        return { overlay: "bg-gradient-to-t from-blue-900/80 via-transparent to-transparent", textBase: "text-white" };
      default:
        return { overlay: "bg-black/40", textBase: "text-white" };
    }
  };

  const styles = getTemplateStyles();

  // Helper to generate text styles based on Effect
  const getTextEffectStyles = (effect: TextEffect, color: string): React.CSSProperties => {
    const base: React.CSSProperties = {
      fontFamily: data.fontFamily,
      color: color,
    };

    if (color.startsWith('linear-gradient')) {
        base.backgroundImage = color;
        base.backgroundClip = 'text';
        base.WebkitBackgroundClip = 'text';
        base.WebkitTextFillColor = 'transparent';
        base.color = 'transparent'; 
    }

    switch (effect) {
      case TextEffect.SHADOW_SOFT:
        return { ...base, textShadow: '0 4px 8px rgba(0,0,0,0.5)' };
      case TextEffect.SHADOW_HARD:
        return { ...base, textShadow: '3px 3px 0px rgba(0,0,0,1)' };
      case TextEffect.OUTLINE:
        return { 
          ...base, 
          WebkitTextStroke: `1px ${color === '#000000' ? '#ffffff' : '#000000'}`, 
          textShadow: 'none' 
        };
      case TextEffect.NEON:
        return { 
          ...base, 
          textShadow: `0 0 5px #fff, 0 0 10px ${color}, 0 0 20px ${color}` 
        };
      case TextEffect.RETRO:
        return { ...base, textShadow: '2px 2px 0px #d1d5db, 4px 4px 0px #9ca3af' };
      case TextEffect.ELEGANT:
        return { ...base, textShadow: '0px 1px 0px rgba(255,255,255,0.4), 0px -1px 0px rgba(0,0,0,0.4)' };
      case TextEffect.GLITCH:
        return { ...base, textShadow: '2px 0 rgba(255,0,0,0.5), -2px 0 rgba(0,0,255,0.5)' };
      case TextEffect.NONE:
      default:
        return base;
    }
  };

  const textStyle = getTextEffectStyles(data.textEffect, data.textColor);
  const accentStyle: React.CSSProperties = {
    fontFamily: data.fontFamily,
    color: data.textColor.startsWith('linear-gradient') ? '#ffffff' : data.textColor,
    opacity: 0.9,
    textShadow: '0px 1px 2px rgba(0,0,0,0.5)',
  };

  const baseWidth = 400;
  const baseHeight = 500;

  // Interactive Upload Wrapper
  const UploadTrigger = ({ field, children, className = "" }: { field: keyof PosterData, children?: React.ReactNode, className?: string }) => (
    <div 
      className={`relative group cursor-pointer ${className}`}
      onClick={(e) => { e.stopPropagation(); onTriggerUpload?.(field); }}
      title={`Click to upload ${field === 'backgroundImageUrl' ? 'Background' : field === 'uploadedPhotoUrl' ? 'Photo' : 'Logo'}`}
    >
      {children}
      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-inherit z-50 pointer-events-none">
        <Upload size={16} className="text-white" />
      </div>
    </div>
  );

  // Common Elements
  const LogoElement = () => (
    <UploadTrigger field="logoUrl" className="inline-block rounded-full overflow-hidden">
      {data.logoUrl ? (
        <img src={data.logoUrl} alt="Logo" className="h-16 w-16 object-cover rounded-full drop-shadow-md" crossOrigin="anonymous"/>
      ) : (
        <div className="h-16 w-16 bg-white/20 border-2 border-dashed border-white/50 rounded-full flex items-center justify-center backdrop-blur-sm">
            <span className="text-[10px] text-white font-bold uppercase">Logo</span>
        </div>
      )}
    </UploadTrigger>
  );

  const PhotoElement = ({ className = "" }: { className?: string }) => (
     <UploadTrigger field="uploadedPhotoUrl" className={className}>
        {data.uploadedPhotoUrl ? (
            // Changed to rounded-[2.5rem] for squircle shape
            <div className="w-full h-full rounded-[2.5rem] border-4 border-white/30 overflow-hidden shadow-2xl">
                <img src={data.uploadedPhotoUrl} alt="User" className="w-full h-full object-cover" crossOrigin="anonymous"/>
            </div>
        ) : (
            <div className="w-full h-full rounded-[2.5rem] border-4 border-dashed border-white/40 bg-white/10 flex flex-col items-center justify-center text-white/80 backdrop-blur-sm">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1 uppercase">Photo</span>
            </div>
        )}
     </UploadTrigger>
  );

  const TextContent = ({ align = "center" }: { align?: "left" | "center" | "right" }) => (
    <div className={`flex flex-col gap-4 ${align === 'center' ? 'items-center text-center' : align === 'left' ? 'items-start text-left' : 'items-end text-right'}`}>
         {data.mode === AppMode.VERSE ? (
            <>
              <p className="text-3xl md:text-3xl leading-snug italic" style={textStyle}>
                "{data.verseText}"
              </p>
              <div className="h-1 w-12 bg-current opacity-50 rounded-full" style={{ color: data.textColor }}></div>
              <p className="text-lg font-bold uppercase tracking-widest" style={accentStyle}>
                {data.verseReference}
              </p>
            </>
          ) : (
            <>
              <h1 className="text-4xl font-bold leading-tight" style={textStyle}>
                {data.eventTitle || "Event Title"}
              </h1>
              <p className="text-lg whitespace-pre-wrap font-light opacity-90" style={textStyle}>
                {data.eventDetails || "Date • Time • Venue"}
              </p>
            </>
          )}
    </div>
  );

  const renderLayoutContent = () => {
    switch (data.layout) {
      // 1) Right Corner: Photo Top-Right, Logo Top-Left
      case LayoutType.RIGHT_CORNER:
        return (
          <div className="w-full h-full p-6 flex flex-col">
             <div className="flex justify-between items-start mb-4">
                {/* Logo Top Left */}
                <div className="flex flex-col items-start gap-1">
                    <LogoElement />
                    {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                </div>
                {/* Photo Top Right (INCREASED SIZE) */}
                <div className="w-60 h-60">
                    <PhotoElement />
                </div>
             </div>

             {/* Text Area */}
             <div className="flex-1 flex items-center justify-center">
                <TextContent align="center" />
             </div>
          </div>
        );

      // 2) Left Corner: Photo Top-Left, Logo Top-Right
      case LayoutType.LEFT_CORNER:
        return (
            <div className="w-full h-full p-6 flex flex-col">
               <div className="flex justify-between items-start mb-4">
                  {/* Photo Top Left (INCREASED SIZE) */}
                  <div className="w-60 h-60">
                      <PhotoElement />
                  </div>
                  {/* Logo Top Right */}
                  <div className="flex flex-col items-end gap-1">
                      <LogoElement />
                      {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                  </div>
               </div>

               {/* Text Area */}
               <div className="flex-1 flex items-center justify-center">
                  <TextContent align="center" />
               </div>
            </div>
          );

      // 3) Bottom Middle: Content Top, Photo Bottom Center, Logo Bottom Left
      case LayoutType.BOTTOM_MIDDLE:
        return (
            <div className="w-full h-full p-6 flex flex-col">
               {/* Text Area Top */}
               <div className="flex-1 flex items-center justify-center mb-8">
                  <TextContent align="center" />
               </div>

               {/* Bottom Section */}
               <div className="relative h-64 w-full mt-4">
                   {/* Logo Bottom Left */}
                   <div className="absolute bottom-0 left-0 flex flex-col items-start gap-1">
                      <LogoElement />
                      {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                   </div>

                   {/* Photo Bottom Center (INCREASED SIZE) */}
                   <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-60 h-60">
                       <PhotoElement />
                   </div>
               </div>
            </div>
        );

      // 4) Cinematic / Custom (Direct Upload Focused)
      case LayoutType.CINEMATIC:
      default:
        return (
          <div className="w-full h-full flex flex-col justify-end relative">
            <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/30 z-0 pointer-events-none"></div>

            {/* Interactive Areas */}
            <div className="absolute top-6 left-6 z-10">
               <LogoElement />
            </div>

            <div className="absolute top-6 right-6 z-10 w-24 h-24 opacity-80 hover:opacity-100 transition-opacity">
                {/* Cinematic keeps circle for small avatar feel, or we can make it match. Let's make it match. */}
                <PhotoElement className="w-full h-full" />
            </div>

            <div className="relative z-20 p-8 text-center pb-16">
               <div className="w-px h-12 bg-white/50 mx-auto mb-4"></div>
               <TextContent align="center" />
               {data.customName && <p className="mt-4 text-xs font-bold uppercase tracking-[0.2em] text-white/70">{data.customName}</p>}
            </div>
          </div>
        );
    }
  };

  return (
    <div className="w-full flex justify-center py-4 select-none" style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }}>
      <div 
        ref={ref}
        id="poster-canvas"
        className={`relative bg-slate-200 overflow-hidden shadow-[0_20px_50px_-12px_rgba(0,0,0,0.5)] flex flex-col group/poster`}
        style={{ width: baseWidth, height: baseHeight }}
      >
        {/* Background Image (Click to Upload) */}
        <div 
            className="absolute inset-0 z-0 cursor-pointer"
            onClick={(e) => { e.stopPropagation(); onTriggerUpload?.('backgroundImageUrl'); }}
            title="Click background to change image"
        >
            {data.backgroundImageUrl ? (
            <img 
                src={data.backgroundImageUrl} 
                alt="Background" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                crossOrigin="anonymous"
            />
            ) : (
            <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                <ImageIcon className="text-slate-600" size={48} />
            </div>
            )}
            {/* Hover hint for background */}
            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover/poster:opacity-100 flex items-center justify-center transition-opacity pointer-events-none">
                <span className="bg-black/60 text-white px-3 py-1 rounded-full text-xs font-bold backdrop-blur-sm border border-white/20">
                    Click elements to edit
                </span>
            </div>
        </div>

        {/* Overlay for non-cinematic modes */}
        {data.layout !== LayoutType.CINEMATIC && (
          <div className={`absolute inset-0 z-0 pointer-events-none ${styles.overlay}`}></div>
        )}

        {/* Content Layer */}
        <div className="relative z-10 w-full h-full pointer-events-auto">
           {renderLayoutContent()}
        </div>

      </div>
    </div>
  );
});

