import React, { forwardRef, useMemo } from 'react';
import { PosterData, AppMode, TemplateStyle, LayoutType, TextEffect } from '../types';
import { Upload, Camera, Image as ImageIcon } from 'lucide-react';

interface Props {
  data: PosterData;
  scale?: number;
  onTriggerUpload?: (field: keyof PosterData) => void;
}

const PosterPreview = forwardRef<HTMLDivElement, Props>(({ data, scale = 1, onTriggerUpload }, ref) => {
  // Styles based on template
  const getTemplateStyles = () => {
    switch (data.template) {
      case TemplateStyle.MINIMAL:
        return { overlay: "bg-white/90", textBase: "text-slate-900" };
      case TemplateStyle.NATURE:
        return { overlay: "bg-black/20", textBase: "text-white" };
      case TemplateStyle.ABSTRACT:
        return { overlay: "bg-purple-900/40", textBase: "text-white" };
      case TemplateStyle.GOLDEN:
        return { overlay: "bg-black/60", textBase: "text-amber-100" };
      case TemplateStyle.GRADIENT:
        return { overlay: "bg-gradient-to-t from-blue-900/80 via-transparent to-transparent", textBase: "text-white" };
      default:
        return { overlay: "bg-black/40", textBase: "text-white" };
    }
  };

  const styles = getTemplateStyles();

  // Helper to generate text styles based on Effect
  const getTextEffectStyles = (effect: TextEffect, color: string): React.CSSProperties => {
    const base: React.CSSProperties = {
      fontFamily: data.fontFamily,
      color: color,
    };

    if (color.startsWith('linear-gradient')) {
        base.backgroundImage = color;
        base.backgroundClip = 'text';
        base.WebkitBackgroundClip = 'text';
        base.WebkitTextFillColor = 'transparent';
        base.color = 'transparent'; 
    }

    switch (effect) {
      case TextEffect.SHADOW_SOFT:
        return { ...base, textShadow: '0 4px 8px rgba(0,0,0,0.5)' };
      case TextEffect.SHADOW_HARD:
        return { ...base, textShadow: '3px 3px 0px rgba(0,0,0,1)' };
      case TextEffect.OUTLINE:
        return { 
          ...base, 
          WebkitTextStroke: `1px ${color === '#000000' ? '#ffffff' : '#000000'}`, 
          textShadow: 'none' 
        };
      case TextEffect.NEON:
        return { 
          ...base, 
          textShadow: `0 0 5px #fff, 0 0 10px ${color}, 0 0 20px ${color}` 
        };
      case TextEffect.RETRO:
        return { ...base, textShadow: '2px 2px 0px #d1d5db, 4px 4px 0px #9ca3af' };
      case TextEffect.ELEGANT:
        return { ...base, textShadow: '0px 1px 0px rgba(255,255,255,0.4), 0px -1px 0px rgba(0,0,0,0.4)' };
      case TextEffect.GLITCH:
        return { ...base, textShadow: '2px 0 rgba(255,0,0,0.5), -2px 0 rgba(0,0,255,0.5)' };
      case TextEffect.NONE:
      default:
        return base;
    }
  };

  const textStyle = getTextEffectStyles(data.textEffect, data.textColor);
  const accentStyle: React.CSSProperties = {
    fontFamily: data.fontFamily,
    color: data.textColor.startsWith('linear-gradient') ? '#ffffff' : data.textColor,
    opacity: 0.9,
    textShadow: '0px 1px 2px rgba(0,0,0,0.5)',
  };

  const baseWidth = 400;
  const baseHeight = 500;

  // --- Intelligent Highlighting Logic ---

  // 1. Determine which words to highlight
  const highlightedKeywords = useMemo(() => {
    if (data.mode !== AppMode.VERSE || !data.verseText) return new Set<string>();

    const text = data.verseText;
    const commonStopWords = new Set(['the', 'and', 'that', 'have', 'for', 'not', 'with', 'you', 'this', 'but', 'his', 'from', 'they', 'we', 'say', 'her', 'she', 'will', 'an', 'one', 'would', 'there', 'their', 'what', 'so', 'up', 'out', 'if', 'about', 'who', 'get', 'which', 'go', 'me', 'when', 'make', 'can', 'like', 'time', 'no', 'just', 'him', 'know', 'take', 'people', 'into', 'year', 'your', 'good', 'some', 'could', 'them', 'see', 'other', 'than', 'then', 'now', 'look', 'only', 'come', 'its', 'over', 'think', 'also', 'back', 'after', 'use', 'two', 'how', 'our', 'work', 'first', 'well', 'way', 'even', 'new', 'want', 'because', 'any', 'these', 'give', 'day', 'most', 'us', 'are', 'is', 'was', 'be', 'been', 'being']);

    const christianKeywords = new Set(['god', 'jesus', 'lord', 'christ', 'holy', 'spirit', 'father', 'faith', 'love', 'grace', 'mercy', 'peace', 'joy', 'hope', 'life', 'light', 'truth', 'heart', 'soul', 'pray', 'bless', 'glory', 'saved', 'world', 'son', 'heaven', 'believe', 'eternal', 'word', 'king', 'cross', 'blood', 'lamb', 'shepherd']);

    const words = text.split(/[\s,.!?;:"'-]+/); // Split by punctuation to score clean words

    const candidates = words.map((w, i) => {
        const clean = w.toLowerCase();
        let score = 0;
        if (clean.length < 3) return { word: clean, score: 0 }; // Ignore tiny words

        if (christianKeywords.has(clean)) score += 20;
        if (!commonStopWords.has(clean)) score += clean.length; // Length bonus
        if (w.length > 0 && w[0] === w[0].toUpperCase() && /^[A-Z]/.test(w)) score += 5; // Capitalization bonus

        return { word: clean, score };
    });

    // Sort by score
    const sorted = candidates.filter(c => c.score > 0).sort((a, b) => b.score - a.score);

    // Pick top 3 unique
    const topWords = new Set<string>();
    for (const c of sorted) {
        if (topWords.size >= 3) break;
        topWords.add(c.word);
    }
    return topWords;
  }, [data.verseText, data.mode]);

  // 2. Define Highlight Style (Complementary Font & Color)
  const highlightStyle = useMemo(() => {
    const isBaseScript = data.fontFamily.includes('cursive') || data.fontFamily.includes('Vibes') || data.fontFamily.includes('Script') || data.fontFamily.includes('Pacifico');

    // If base is script, use a strong Serif for highlights. If base is Sans/Serif, use a nice Script.
    const font = isBaseScript ? "'Cinzel', serif" : "'Great Vibes', cursive";

    // Determine Highlight Color based on background brightness estimate (using textColor as proxy)
    // If text is whiteish -> Accent is Gold/Amber
    // If text is blackish -> Accent is Deep Red/Blue or Gold
    const isDarkText = data.textColor === '#000000' || data.textColor.startsWith('#0') || data.textColor.startsWith('#1') || data.textColor.startsWith('#3');
    const color = isDarkText ? '#B45309' : '#FCD34D'; // Amber-700 vs Amber-300

    return {
        fontFamily: font,
        color: color,
        fontWeight: isBaseScript ? 'bold' : 'normal', // Serif highlights need bold, Script usually doesn't
        fontSize: '1.25em',
        textShadow: isDarkText ? 'none' : '0 0 10px rgba(252, 211, 77, 0.5)', // Glow for light mode
    };
  }, [data.fontFamily, data.textColor]);

  // 3. Render Component
  const HighlightedVerseText = () => {
    if (!data.verseText) return null;

    // Split text but keep delimiters/punctuation for reconstruction
    const parts = data.verseText.split(/(\s+|[.,!?;:"'-]+)/g);

    return (
        <p className="text-3xl md:text-3xl leading-snug italic px-4" style={textStyle}>
            "
            {parts.map((part, i) => {
                const clean = part.toLowerCase().replace(/[^a-z0-9]/g, '');
                const isHighlight = clean.length > 2 && highlightedKeywords.has(clean);

                if (isHighlight) {
                    return (
                        <span key={i} style={{ ...highlightStyle, display: 'inline-block', transform: 'scale(1.1)' }}>
                            {part}
                        </span>
                    );
                }
                return <span key={i}>{part}</span>;
            })}
            "
        </p>
    );
  };

  // Interactive Upload Wrapper
  const UploadTrigger = ({ field, children, className = "" }: { field: keyof PosterData, children?: React.ReactNode, className?: string }) => (
    <div 
      className={`relative group cursor-pointer ${className}`}
      onClick={(e) => { e.stopPropagation(); onTriggerUpload?.(field); }}
      title={`Click to upload ${field === 'backgroundImageUrl' ? 'Background' : field === 'uploadedPhotoUrl' ? 'Photo' : 'Logo'}`}
    >
      {children}
      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-inherit z-50 pointer-events-none">
        <Upload size={16} className="text-white" />
      </div>
    </div>
  );

  // Common Elements
  const LogoElement = () => (
    <UploadTrigger field="logoUrl" className="inline-block rounded-full overflow-hidden">
      {data.logoUrl ? (
        <img src={data.logoUrl} alt="Logo" className="h-16 w-16 object-cover rounded-full drop-shadow-md" crossOrigin="anonymous"/>
      ) : (
        <div className="h-16 w-16 bg-white/20 border-2 border-dashed border-white/50 rounded-full flex items-center justify-center backdrop-blur-sm">
            <span className="text-[10px] text-white font-bold uppercase">Logo</span>
        </div>
      )}
    </UploadTrigger>
  );

  const PhotoElement = ({ className = "" }: { className?: string }) => (
     <UploadTrigger field="uploadedPhotoUrl" className={className}>
        {data.uploadedPhotoUrl ? (
            <div className="w-full h-full rounded-[2.5rem] border-4 border-white/30 overflow-hidden shadow-2xl">
                <img src={data.uploadedPhotoUrl} alt="User" className="w-full h-full object-cover" crossOrigin="anonymous"/>
            </div>
        ) : (
            <div className="w-full h-full rounded-[2.5rem] border-4 border-dashed border-white/40 bg-white/10 flex flex-col items-center justify-center text-white/80 backdrop-blur-sm">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1 uppercase">Photo</span>
            </div>
        )}
     </UploadTrigger>
  );

  const TextContent = ({ align = "center" }: { align?: "left" | "center" | "right" }) => (
    <div className={`flex flex-col gap-4 ${align === 'center' ? 'items-center text-center' : align === 'left' ? 'items-start text-left' : 'items-end text-right'}`}>
         {data.mode === AppMode.VERSE ? (
            <>
              {/* Highlighted Verse Component */}
              <HighlightedVerseText />

              <div className="h-1 w-12 bg-current opacity-50 rounded-full" style={{ color: data.textColor }}></div>
              <p className="text-lg font-bold uppercase tracking-widest" style={accentStyle}>
                {data.verseReference}
              </p>
            </>
          ) : (
            <>
              <h1 className="text-4xl font-bold leading-tight" style={textStyle}>
                {data.eventTitle || "Event Title"}
              </h1>
              <p className="text-lg whitespace-pre-wrap font-light opacity-90" style={textStyle}>
                {data.eventDetails || "Date • Time • Venue"}
              </p>
            </>
          )}
    </div>
  );

  const renderLayoutContent = () => {
    switch (data.layout) {
      // 1) Right Corner: Photo Top-Right, Logo Top-Left
      case LayoutType.RIGHT_CORNER:
        return (
          <div className="w-full h-full p-6 flex flex-col">
             <div className="flex justify-between items-start mb-4">
                {/* Logo Top Left */}
                <div className="flex flex-col items-start gap-1">
                    <LogoElement />
                    {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                </div>
                {/* Photo Top Right */}
                <div className="w-60 h-60">
                    <PhotoElement />
                </div>
             </div>

             {/* Text Area */}
             <div className="flex-1 flex items-center justify-center">
                <TextContent align="center" />
             </div>
          </div>
        );

      // 2) Left Corner: Photo Top-Left, Logo Top-Right
      case LayoutType.LEFT_CORNER:
        return (
            <div className="w-full h-full p-6 flex flex-col">
               <div className="flex justify-between items-start mb-4">
                  {/* Photo Top Left */}
                  <div className="w-60 h-60">
                      <PhotoElement />
                  </div>
                  {/* Logo Top Right */}
                  <div className="flex flex-col items-end gap-1">
                      <LogoElement />
                      {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                  </div>
               </div>

               {/* Text Area */}
               <div className="flex-1 flex items-center justify-center">
                  <TextContent align="center" />
               </div>
            </div>
          );

      // 3) Bottom Middle: Content Top, Photo Bottom Center, Logo Bottom Left
      case LayoutType.BOTTOM_MIDDLE:
        return (
            <div className="w-full h-full p-6 flex flex-col">
               {/* Text Area Top */}
               <div className="flex-1 flex items-center justify-center mb-8">
                  <TextContent align="center" />
               </div>

               {/* Bottom Section */}
               <div className="relative h-64 w-full mt-4">
                   {/* Logo Bottom Left */}
                   <div className="absolute bottom-0 left-0 flex flex-col items-start gap-1">
                      <LogoElement />
                      {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                   </div>

                   {/* Photo Bottom Center */}
                   <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-60 h-60">
                       <PhotoElement />
                   </div>
               </div>
            </div>
        );

      // 4) Cinematic
      case LayoutType.CINEMATIC:
      default:
        return (
          <div className="w-full h-full flex flex-col justify-end relative">
            <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/30 z-0 pointer-events-none"></div>

            {/* Interactive Areas */}
            <div className="absolute top-6 left-6 z-10">
               <LogoElement />
            </div>

            <div className="absolute top-6 right-6 z-10 w-24 h-24 opacity-80 hover:opacity-100 transition-opacity">
                <PhotoElement className="w-full h-full" />
            </div>

            <div className="relative z-20 p-8 text-center pb-16">
               <div className="w-px h-12 bg-white/50 mx-auto mb-4"></div>
               <TextContent align="center" />
               {data.customName && <p className="mt-4 text-xs font-bold uppercase tracking-[0.2em] text-white/70">{data.customName}</p>}
            </div>
          </div>
        );
    }
  };

  return (
    <div className="w-full flex justify-center py-4 select-none" style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }}>
      <div 
        ref={ref}
        id="poster-canvas"
        className={`relative bg-slate-200 overflow-hidden shadow-[0_20px_50px_-12px_rgba(0,0,0,0.5)] flex flex-col group/poster`}
        style={{ width: baseWidth, height: baseHeight }}
      >
        {/* Background Image (Click to Upload) */}
        <div 
            className="absolute inset-0 z-0 cursor-pointer"
            onClick={(e) => { e.stopPropagation(); onTriggerUpload?.('backgroundImageUrl'); }}
            title="Click background to change image"
        >
            {data.backgroundImageUrl ? (
            <img 
                src={data.backgroundImageUrl} 
                alt="Background" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                crossOrigin="anonymous"
            />
            ) : (
            <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                <ImageIcon className="text-slate-600" size={48} />
            </div>
            )}
            {/* Hover hint for background */}
            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover/poster:opacity-100 flex items-center justify-center transition-opacity pointer-events-none">
                <span className="bg-black/60 text-white px-3 py-1 rounded-full text-xs font-bold backdrop-blur-sm border border-white/20">
                    Click elements to edit
                </span>
            </div>
        </div>

        {/* Overlay for non-cinematic modes */}
        {data.layout !== LayoutType.CINEMATIC && (
          <div className={`absolute inset-0 z-0 pointer-events-none ${styles.overlay}`}></div>
        )}

        {/* Content Layer */}
        <div className="relative z-10 w-full h-full pointer-events-auto">
           {renderLayoutContent()}
        </div>

      </div>
    </div>
  );
});

PosterPreview.displayName = 'PosterPreview';

export default PosterPreview;

export enum AppMode {
  VERSE = 'VERSE',
  EVENT = 'EVENT'
}

export enum TemplateStyle {
  MINIMAL = 'Minimal',
  NATURE = 'Nature',
  ABSTRACT = 'Abstract',
  GOLDEN = 'Golden',
  GRADIENT = 'Gradient'
}

export enum LayoutType {
  RIGHT_CORNER = 'Right Corner',
  LEFT_CORNER = 'Left Corner',
  BOTTOM_MIDDLE = 'Bottom Middle',
  CINEMATIC = 'Cinematic'
}

export enum TextEffect {
  NONE = 'none',
  SHADOW_SOFT = 'shadow-soft',
  SHADOW_HARD = 'shadow-hard',
  OUTLINE = 'outline',
  NEON = 'neon',
  RETRO = 'retro',
  ELEGANT = 'elegant',
  GLITCH = 'glitch'
}

export interface PosterData {
  mode: AppMode;
  // Verse Mode
  verseReference: string; // The Localized/Target Language Reference
  verseReferenceEnglish: string; // The English Reference
  verseText: string;
  // Event Mode
  eventTitle: string;
  eventDetails: string; // Date, Time, Venue
  // Shared
  language: string; // Target language for translation
  interfaceLanguage: string; // UI Language
  template: TemplateStyle;
  layout: LayoutType;
  backgroundImageUrl: string | null;
  uploadedPhotoUrl: string | null;
  logoUrl: string | null;
  customName: string; // Family name / Church name

  // Customization
  fontFamily: string;
  textColor: string;
  textEffect: TextEffect;
}

// For html2canvas global availability
declare global {
  interface Window {
    html2canvas: (element: HTMLElement, options?: any) => Promise<HTMLCanvasElement>;
  }
}

import React, { useState, useRef } from 'react';
import { AppMode, PosterData, TemplateStyle, LayoutType, TextEffect } from './types';
import { DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, SUPPORTED_LANGUAGES } from './constants';
import { generateBackground } from './services/geminiService';
import PosterPreview from './components/PosterPreview';
import EditorPanel from './components/EditorPanel';
import { Download, Share2, BookOpen, Calendar, AlertTriangle, Image as ImageIcon, Upload, ChevronRight, ChevronLeft, Sparkles, Languages, Wand2, Cross } from 'lucide-react';

const App: React.FC = () => {
  const posterRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadField, setActiveUploadField] = useState<keyof PosterData | null>(null);
  const [isGeneratingBg, setIsGeneratingBg] = useState(false);

  // Initial State
  const [data, setData] = useState<PosterData>({
    mode: AppMode.VERSE,
    verseReference: "John 3:16",
    verseReferenceEnglish: "John 3:16", // Initialize English Reference
    verseText: "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.",
    eventTitle: "Sunday Service",
    eventDetails: "Sunday, 9:00 AM\nMain Sanctuary\nPastor John Doe",
    language: "English",
    interfaceLanguage: "en", // Default UI Language
    template: TemplateStyle.NATURE,
    layout: LayoutType.RIGHT_CORNER,
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Layout Cycling Logic
  const layouts = [
    { id: LayoutType.RIGHT_CORNER, label: 'Corner R' },
    { id: LayoutType.LEFT_CORNER, label: 'Corner L' },
    { id: LayoutType.BOTTOM_MIDDLE, label: 'Bottom' },
    { id: LayoutType.CINEMATIC, label: 'Cinematic' },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    updateData({ layout: layouts[nextIndex].id });
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    updateData({ layout: layouts[prevIndex].id });
  };

  // File Upload Logic
  const triggerUpload = (field: keyof PosterData) => {
    setActiveUploadField(field);
    if (fileInputRef.current) {
      fileInputRef.current.value = ""; // Reset
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUploadField) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          updateData({ [activeUploadField]: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // AI Background Generation
  const handleAiBackgroundGen = async () => {
    if (!process.env.API_KEY) {
        alert("Please configure your API Key to use AI features.");
        return;
    }

    setIsGeneratingBg(true);
    // Pass the verse text (or event title) as context so the AI generates something relatable
    // The service currently takes style, but we can assume the style prompt inside uses the template name
    const bgUrl = await generateBackground(data.template); 

    if (bgUrl) {
      updateData({ backgroundImageUrl: bgUrl });
    } else {
      alert("Failed to generate background. Please try again.");
    }
    setIsGeneratingBg(false);
  };

  const handleDownload = async () => {
    if (posterRef.current && window.html2canvas) {
      try {
        // Use a small timeout to ensure images are loaded if they were just swapped
        setTimeout(async () => {
            const canvas = await window.html2canvas(posterRef.current!, {
                useCORS: true, // Important for external images
                scale: 2, // Higher quality
                backgroundColor: null,
            });

            const link = document.createElement('a');
            link.download = `gracelens-${data.mode.toLowerCase()}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        }, 100);
      } catch (err) {
        console.error("Download failed", err);
        alert("Could not download image. Please try again.");
      }
    } else {
        alert("Download library not loaded yet.");
    }
  };

  const handleShare = () => {
    if (navigator.share) {
        alert("On a mobile device, this would open the share sheet. Generate the image first to share properly!");
    } else {
        alert("Share feature is available on mobile devices.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileChange} 
      />

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-2xl mx-auto px-4 sm:px-6 h-auto py-3 flex flex-col sm:flex-row items-center justify-between gap-3">

          {/* Futuristic Logo */}
          <div className="flex items-center gap-3 group cursor-pointer self-start sm:self-auto">
             <div className="relative w-10 h-10 flex items-center justify-center">
                <div className="absolute inset-0 bg-cyan-500 blur-lg opacity-20 group-hover:opacity-40 transition-opacity rounded-full"></div>
                <div className="relative bg-gradient-to-br from-slate-900 to-slate-800 rounded-xl p-2 shadow-lg ring-1 ring-white/10 group-hover:ring-cyan-400/50 transition-all flex items-center justify-center">
                   {/* Updated Icon to Cross */}
                   <Cross className="text-cyan-400 w-full h-full" />
                </div>
                <div className="absolute -top-1 -right-1">
                    <Sparkles size={12} className="text-purple-500 fill-purple-500 animate-pulse" />
                </div>
             </div>
             <div className="flex flex-col">
                <h1 className="text-2xl font-bold tracking-tight" style={{ fontFamily: "'Orbitron', sans-serif" }}>
                  <span className="bg-clip-text text-transparent bg-gradient-to-r from-cyan-500 via-blue-600 to-purple-600">
                    GraceLens
                  </span>
                </h1>
                {/* Updated Subtitle */}
                <span className="text-[10px] font-bold tracking-[0.2em] text-slate-400 uppercase -mt-1 pl-0.5">
                    CHRISTIAN POSTER APP
                </span>
             </div>
          </div>

          <div className="flex items-center gap-3 self-end sm:self-auto">
             {/* LANGUAGE SELECTION DROPDOWN */}
             <div className="relative group">
                <div className="flex items-center gap-1.5 bg-slate-100 px-3 py-1.5 rounded-lg cursor-pointer border border-slate-200 hover:bg-slate-50 hover:border-blue-300 transition-all">
                   <Languages size={14} className="text-slate-500"/>
                   <span className="text-xs font-bold text-slate-700">Selection</span>
                   <select 
                      value={data.interfaceLanguage}
                      onChange={(e) => updateData({ interfaceLanguage: e.target.value, language: e.target.options[e.target.selectedIndex].text })}
                      className="absolute inset-0 opacity-0 cursor-pointer"
                   >
                      {SUPPORTED_LANGUAGES.map(lang => (
                         <option key={lang.code} value={lang.code}>{lang.name}</option>
                      ))}
                   </select>
                   <span className="text-[10px] bg-slate-200 px-1.5 rounded text-slate-600 font-mono ml-1">{data.interfaceLanguage.toUpperCase()}</span>
                </div>
             </div>

             {/* Tabs: High Contrast Style */}
             <nav className="flex bg-slate-100/80 p-1.5 rounded-xl shadow-inner border border-slate-200/50">
                <button 
                  onClick={() => switchMode(AppMode.VERSE)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.VERSE ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <BookOpen size={14}/> Verse
                </button>
                <button 
                  onClick={() => switchMode(AppMode.EVENT)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.EVENT ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <Calendar size={14}/> Event
                </button>
             </nav>
          </div>
        </div>
      </header>

      {/* Main Content - Centered Single Column */}
      <main className="flex-1 w-full max-w-2xl mx-auto px-4 py-8 flex flex-col items-center gap-8">

        {!process.env.API_KEY && (
           <div className="w-full bg-amber-50 border-l-4 border-amber-500 p-4 rounded-xl flex items-start gap-3 shadow-sm">
              <AlertTriangle className="text-amber-500 mt-0.5" />
              <div>
                  <h3 className="font-bold text-amber-800">API Key Missing</h3>
                  <p className="text-amber-700 text-sm">Please set your <code className="bg-amber-100 px-1 rounded">process.env.API_KEY</code> to use the AI translation and background generation features.</p>
              </div>
           </div>
        )}

        {/* 1. Poster Preview with Side Arrow Navigation */}
        <div className="relative w-fit group select-none">

            {/* Left Arrow */}
            <button 
                onClick={prevLayout}
                className="absolute -left-4 md:-left-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                title="Previous Layout"
            >
                <ChevronLeft size={24} className="group-hover/btn:-translate-x-0.5 transition-transform" />
            </button>

            {/* Poster Container */}
            <div className="bg-white p-2 rounded-[2rem] shadow-2xl shadow-slate-200 border-4 border-white relative ring-1 ring-slate-100">
                {/* Background Glow */}
                <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 to-purple-500/10 blur-3xl rounded-full transform scale-110 z-0 pointer-events-none"></div>

                <div className="relative z-10 rounded-3xl overflow-hidden">
                    <PosterPreview data={data} ref={posterRef} onTriggerUpload={triggerUpload} />
                </div>
            </div>

            {/* Right Arrow */}
            <button 
                onClick={nextLayout}
                className="absolute -right-4 md:-right-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                title="Next Layout"
            >
                <ChevronRight size={24} className="group-hover/btn:translate-x-0.5 transition-transform" />
            </button>

            {/* Layout Indicator */}
            <div className="absolute -bottom-10 left-0 right-0 flex justify-center items-center gap-3">
                 <div className="bg-slate-900/5 backdrop-blur-sm px-4 py-1.5 rounded-full border border-slate-200/50 flex items-center gap-2">
                    <span className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Layout:</span>
                    <span className="text-xs font-bold text-slate-800">
                        {layouts[currentLayoutIndex].label}
                    </span>
                 </div>
                 <div className="flex gap-1.5">
                    {layouts.map((l, i) => (
                        <div key={l.id} className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${i === currentLayoutIndex ? 'bg-blue-600 w-4' : 'bg-slate-300'}`} />
                    ))}
                 </div>
            </div>
        </div>

        {/* Spacer for layout indicator */}
        <div className="h-6"></div>

        {/* 2. Action Buttons (New Layout) */}
        <div className="w-full flex flex-col gap-3">

            {/* Main Actions Row: Download | Background | Share */}
            <div className="flex gap-3 w-full">

                {/* Download Button - Dark */}
                <button 
                    onClick={handleDownload}
                    className="flex-1 bg-slate-900 text-white py-3.5 rounded-2xl font-bold shadow-lg shadow-slate-200 hover:bg-black hover:scale-[1.01] active:scale-[0.99] transition-all flex justify-center items-center gap-2"
                >
                    <Download size={20} /> Download
                </button>

                {/* Background Upload Button - Light Blue */}
                <button 
                    onClick={() => triggerUpload('backgroundImageUrl')}
                    className="flex-1 bg-indigo-50 text-indigo-600 border border-indigo-100 py-3.5 rounded-2xl font-bold hover:bg-indigo-100 transition-all flex justify-center items-center gap-2"
                >
                    <ImageIcon size={20} /> Background
                </button>

                {/* Share Button - White Outline */}
                <button 
                    onClick={handleShare}
                    className="flex-1 bg-white text-slate-700 border-2 border-slate-100 py-3.5 rounded-2xl font-bold hover:bg-slate-50 hover:border-slate-200 transition-all flex justify-center items-center gap-2"
                >
                    <Share2 size={20} /> Share
                </button>
            </div>

            {/* Bottom Row: AI Generator - Gradient Full Width */}
            <button 
                onClick={handleAiBackgroundGen}
                disabled={isGeneratingBg}
                className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-200/50 hover:shadow-xl hover:shadow-blue-300/50 hover:scale-[1.01] active:scale-[0.99] transition-all flex justify-center items-center gap-2.5 disabled:opacity-70 disabled:cursor-not-allowed group relative overflow-hidden"
            >
                {/* Shimmer Effect */}
                <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:animate-shimmer skew-x-12"></div>

                {isGeneratingBg ? (
                    <>
                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                        Generating Relatable Background...
                    </>
                ) : (
                    <>
                        <Wand2 size={20} className="text-blue-100" /> 
                        Generate AI Background 
                        <span className="text-[10px] bg-white/20 px-1.5 py-0.5 rounded text-blue-50 ml-1">Beta</span>
                    </>
                )}
            </button>
        </div>

        {/* 5. Editor Panel */}
        <div className="w-full">
            <EditorPanel data={data} onUpdate={updateData} />
        </div>

      </main>

      <footer className="bg-white border-t border-slate-200 mt-12 py-8">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <p className="text-slate-400 text-sm font-medium">&copy; {new Date().getFullYear()} GraceLens. AI-Powered Christian Design.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { AppMode, PosterData, TemplateStyle, TextEffect } from '../types';
import { CONTENT_LANGUAGES, DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, UI_TRANSLATIONS, SUPPORTED_LANGUAGES } from '../constants';
import { fetchVerse } from '../services/bibleService';
import { translateText, recommendFonts } from '../services/geminiService';
import { Search, Sparkles, Type, Calendar, Palette, ChevronDown, Globe, BookOpen, Wand2, ChevronLeft, ChevronRight } from 'lucide-react';

interface Props {
  data: PosterData;
  onUpdate: (data: Partial<PosterData>) => void;
}

const EditorPanel: React.FC<Props> = ({ data, onUpdate }) => {
  const [verseQuery, setVerseQuery] = useState("");
  const [isSearching, setIsSearching] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);

  // Font AI State
  const [isAiFontMode, setIsAiFontMode] = useState(false);
  const [fontAiQuery, setFontAiQuery] = useState("");
  const [isGeneratingFont, setIsGeneratingFont] = useState(false);
  const [suggestedFonts, setSuggestedFonts] = useState<string[]>([]);

  // Font Carousel State
  const [fontPage, setFontPage] = useState(0);
  const FONTS_PER_PAGE = 6;
  const totalFontPages = Math.ceil(AVAILABLE_FONTS.length / FONTS_PER_PAGE);

  // State for custom dropdowns
  const [isLangOpen, setIsLangOpen] = useState(false);
  const langDropdownRef = useRef<HTMLDivElement>(null);

  const LIGHT_COLORS = [
    "#FFFFFF", "#F1F5F9", "#FEF08A", "#BAE6FD", "#FECDD3", "#BBF7D0", "#E9D5FF"
  ];
  const DARK_COLORS = [
    "#000000", "#334155", "#1E3A8A", "#881337", "#14532D", "#581C87", "#451A03"
  ];

  // New Gradient Colors
  const GRADIENT_COLORS = [
    "linear-gradient(to right, #bf953f, #fcf6ba, #b38728, #fbf5b7, #aa771c)", // Gold
    "linear-gradient(to right, #D7D7D7, #FFFFFF, #EAEAEA, #C0C0C0)", // Silver
    "linear-gradient(to right, #ff9a9e 0%, #fecfef 99%, #fecfef 100%)", // Rose
    "linear-gradient(to right, #4facfe 0%, #00f2fe 100%)", // Blue
    "linear-gradient(135deg, #FFF 0%, #000 100%)", // Mono
    "linear-gradient(to right, #f83600 0%, #f9d423 100%)", // Fire
  ];

  const TEXT_EFFECTS = [
    { id: TextEffect.NONE, label: 'None', style: {} },
    { id: TextEffect.SHADOW_SOFT, label: 'Soft', style: { textShadow: '0 2px 4px rgba(0,0,0,0.4)' } },
    { id: TextEffect.SHADOW_HARD, label: 'Bold', style: { textShadow: '2px 2px 0 #000' } },
    { id: TextEffect.OUTLINE, label: 'Outline', style: { WebkitTextStroke: '1px black', color: 'transparent' } },
    { id: TextEffect.NEON, label: 'Neon', style: { textShadow: '0 0 5px #fff, 0 0 10px currentColor' } },
    { id: TextEffect.RETRO, label: 'Retro', style: { textShadow: '2px 2px 0 #ccc, 4px 4px 0 #999' } },
  ];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (langDropdownRef.current && !langDropdownRef.current.contains(event.target as Node)) {
        setIsLangOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Helpers
  const currentLangCode = data.interfaceLanguage || 'en';
  const t = (key: keyof typeof UI_TRANSLATIONS['en']) => {
    // @ts-ignore - dynamic key access
    return UI_TRANSLATIONS[currentLangCode]?.[key] || UI_TRANSLATIONS['en'][key] || key;
  };

  const handleSearchVerse = async () => {
    if (!verseQuery) return;
    setIsSearching(true);

    // Find the Bible Version ID for the current language
    const langConfig = SUPPORTED_LANGUAGES.find(l => l.code === data.interfaceLanguage);
    const bibleVersion = langConfig?.bibleVersion || 'web'; // Default to WEB (English)

    // Pass the version to fetchVerse
    const result = await fetchVerse(verseQuery, bibleVersion);
    setIsSearching(false);

    if (result) {
      // 1. Initially set what we got. 
      // Assumption: The API returns standard English refs usually, or we treat it as the "Source" ref.
      onUpdate({ 
        verseText: result.text,
        verseReference: result.reference, // This becomes the display ref
        verseReferenceEnglish: result.reference // Backup as English Ref
      });

      // 2. If the user has explicitly selected a Target Language that is NOT English,
      // translate the text AND reference.
      if (data.language !== 'English') {
         handleTranslate(result.text, data.language, result.reference);
      }
    } else {
      alert("Verse not found. Try format 'John 3:16'");
    }
  };

  const handleTranslate = async (text: string, langName: string, ref: string) => {
    setIsTranslating(true);

    // 1. Translate the Text
    const translatedText = await translateText(text, langName);

    // 2. Translate the Reference explicitly if not English
    let translatedRef = ref;

    if (langName !== 'English') {
        const candidate = await translateText(ref, langName);
        // Safety: ensure it didn't hallucinate a whole paragraph
        if (candidate.length < 50) {
            translatedRef = candidate;
        }
    }

    // 3. Update State:
    // verseReference -> Localized (e.g. Arabic)
    // verseReferenceEnglish -> Keep original English (passed as 'ref' argument usually)
    onUpdate({ 
        verseText: translatedText, 
        verseReference: translatedRef, 
        verseReferenceEnglish: ref // Preserves the source/English ref
    });

    setIsTranslating(false);
  };

  const handleAiFontGeneration = async () => {
    if (!fontAiQuery.trim()) return;
    setIsGeneratingFont(true);
    const result = await recommendFonts(fontAiQuery);
    setIsGeneratingFont(false);

    if (result.fontValues.length > 0) {
      setSuggestedFonts(result.fontValues);
      onUpdate({ fontFamily: result.fontValues[0] });
      if (result.suggestedColor) {
        onUpdate({ textColor: result.suggestedColor });
      }
      setIsAiFontMode(false); 
    } else {
      alert("Could not find matching fonts.");
    }
  };

  const handleTemplateChange = (style: TemplateStyle) => {
    onUpdate({ 
      template: style,
      backgroundImageUrl: DEFAULT_BACKGROUNDS[style]
    });
  };

  const nextFontPage = () => {
    if (fontPage < totalFontPages - 1) {
        setFontPage(prev => prev + 1);
    }
  };

  const prevFontPage = () => {
    if (fontPage > 0) {
        setFontPage(prev => prev - 1);
    }
  };

  const currentFonts = AVAILABLE_FONTS.slice(fontPage * FONTS_PER_PAGE, (fontPage + 1) * FONTS_PER_PAGE);

  return (
    <div className="space-y-6 p-6 bg-white rounded-2xl shadow-xl border border-slate-100">

      {/* Header */}
      <div className="pb-2">
        <h2 className="text-2xl font-serif font-bold text-slate-900 flex items-center gap-2">
          {data.mode === AppMode.VERSE ? <Sparkles className="w-6 h-6 text-gold" /> : <Calendar className="w-6 h-6 text-blue-500" />}
          <span className="bg-gradient-to-r from-slate-900 to-slate-600 bg-clip-text text-transparent">
            {data.mode === AppMode.VERSE ? t('verse_editor') : t('event_editor')}
          </span>
        </h2>
        <p className="text-slate-400 text-sm mt-1">{t('customize_msg')}</p>
      </div>

      {/* RICH LANGUAGE SELECTOR (CONTENT LANGUAGE) */}
      <div className="relative group z-30" ref={langDropdownRef}>
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1">
          <Globe size={12} /> Target Language
        </label>
        <button 
          onClick={() => setIsLangOpen(!isLangOpen)}
          className="w-full flex items-center justify-between p-3.5 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-blue-300 hover:shadow-md transition-all group-hover:ring-2 group-hover:ring-blue-50"
        >
          <span className="font-semibold text-slate-800">{data.language}</span>
          <ChevronDown size={16} className={`text-slate-400 transition-transform ${isLangOpen ? 'rotate-180' : ''}`} />
        </button>

        {isLangOpen && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-2xl border border-slate-100 max-h-60 overflow-y-auto p-1.5 z-40 animate-in fade-in zoom-in-95 duration-200">
            {CONTENT_LANGUAGES.map(lang => (
              <button
                key={lang}
                onClick={() => {
                  const newLang = lang;
                  onUpdate({ language: newLang });
                  setIsLangOpen(false);
                  if (data.mode === AppMode.VERSE && data.verseText) {
                    // Use verseReferenceEnglish as source if available, otherwise verseReference
                    const sourceRef = data.verseReferenceEnglish || data.verseReference;
                    handleTranslate(data.verseText, newLang, sourceRef);
                  }
                }}
                className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${data.language === lang ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'}`}
              >
                {lang}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Content Input */}
      {data.mode === AppMode.VERSE ? (
        <div className="space-y-4">

          {/* RICH FIND VERSE SEARCH BAR */}
          <div className="relative z-20">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1">
               <BookOpen size={12} /> {t('find_verse')}
            </label>
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search size={18} className="text-slate-400 group-focus-within:text-blue-500 transition-colors" />
              </div>
              <input 
                type="text" 
                placeholder={t('search_placeholder')}
                className="w-full pl-10 pr-12 py-3.5 bg-white border border-slate-200 rounded-xl shadow-sm text-slate-800 font-medium placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-400 transition-all"
                value={verseQuery}
                onChange={(e) => setVerseQuery(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSearchVerse()}
              />
              <button 
                onClick={handleSearchVerse}
                disabled={isSearching}
                className="absolute right-2 top-2 p-1.5 bg-slate-100 text-slate-500 rounded-lg hover:bg-blue-600 hover:text-white transition-all disabled:opacity-50"
              >
                {isSearching ? <span className="block w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></span> : <ChevronDown className="rotate-[-90deg]" size={16} />}
              </button>
            </div>
          </div>

          <div className="space-y-0 shadow-sm rounded-xl overflow-hidden border border-slate-200 focus-within:ring-2 focus-within:ring-blue-50 focus-within:border-blue-300 transition-all">
             <textarea 
               className="w-full p-4 h-28 text-base bg-slate-900 text-white placeholder-slate-400 resize-none outline-none font-serif leading-relaxed"
               value={data.verseText}
               onChange={(e) => onUpdate({ verseText: e.target.value })}
               placeholder={t('verse_text_placeholder')}
             />
             <div className="bg-slate-800 px-4 py-2 border-t border-slate-700 flex items-center gap-2">
               <span className="text-xs font-bold text-slate-400 uppercase">Ref:</span>
               <input 
                 type="text"
                 className="flex-1 bg-transparent text-sm font-bold text-slate-200 outline-none placeholder-slate-500"
                 value={data.verseReference}
                 onChange={(e) => onUpdate({ verseReference: e.target.value })}
                 placeholder="Genesis 1:1"
               />
               {isTranslating && <span className="text-xs text-blue-400 font-medium animate-pulse">Translating...</span>}
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="relative">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5">{t('event_title')}</label>
            <input 
              type="text" 
              placeholder="e.g. Youth Worship Night"
              className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm font-bold text-white focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all placeholder:text-slate-500"
              value={data.eventTitle}
              onChange={(e) => onUpdate({ eventTitle: e.target.value })}
            />
          </div>
          <div className="relative">
             <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5">{t('event_details')}</label>
             <textarea 
               placeholder={t('event_details_placeholder')}
               className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm h-28 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all resize-none text-white placeholder:text-slate-500"
               value={data.eventDetails}
               onChange={(e) => onUpdate({ eventDetails: e.target.value })}
             />
          </div>
        </div>
      )}

      {/* Typography Section */}
      <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-4 relative z-10">
        <div className="flex items-center justify-between">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1">
            <Palette size={12} /> {t('typography')}
            </label>

            {/* AI Font Generator Toggle */}
            <button 
                onClick={() => setIsAiFontMode(!isAiFontMode)}
                className={`text-xs px-2 py-1 rounded-md flex items-center gap-1 transition-colors ${isAiFontMode ? 'bg-purple-100 text-purple-700 font-bold' : 'text-slate-400 hover:bg-slate-100'}`}
                title="Generate AI Font Recommendations"
            >
                <Wand2 size={12} /> AI Fonts
            </button>
        </div>

        {/* AI Font Input Area */}
        {isAiFontMode && (
             <div className="flex gap-2 animate-in slide-in-from-top-2 duration-300">
                <input 
                    type="text" 
                    placeholder="Describe mood (e.g. 'Spooky', 'Retro', 'Elegant')..."
                    className="flex-1 px-3 py-2 text-sm border border-purple-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-100"
                    value={fontAiQuery}
                    onChange={(e) => setFontAiQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAiFontGeneration()}
                />
                <button 
                    onClick={handleAiFontGeneration}
                    disabled={isGeneratingFont}
                    className="bg-purple-600 text-white px-3 py-2 rounded-lg hover:bg-purple-700 disabled:opacity-50 transition-colors"
                >
                    {isGeneratingFont ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"/> : <Sparkles size={16} />}
                </button>
             </div>
        )}

        {/* Font Slider (Paginated Grid) */}
        <div className="relative bg-white border border-slate-200 rounded-xl shadow-sm p-2 overflow-hidden">
             <div className="flex justify-between items-center mb-2 px-1">
                <button 
                  onClick={prevFontPage}
                  disabled={fontPage === 0}
                  className="p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors"
                >
                    <ChevronLeft size={20} />
                </button>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    Font ({fontPage + 1}/{totalFontPages})
                </span>
                <button 
                  onClick={nextFontPage}
                  disabled={fontPage === totalFontPages - 1}
                  className={`p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors ${fontPage < totalFontPages - 1 ? 'animate-pulse text-blue-500' : ''}`}
                >
                    <ChevronRight size={20} />
                </button>
             </div>

             <div className="grid grid-cols-2 gap-2">
                {currentFonts.map((font) => (
                    <button
                        key={font.name}
                        onClick={() => onUpdate({ fontFamily: font.value })}
                        className={`p-2.5 rounded-lg border text-center transition-all h-14 flex items-center justify-center ${data.fontFamily === font.value ? 'bg-blue-50 border-blue-400 text-blue-700 ring-1 ring-blue-100' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-white hover:border-blue-200'}`}
                        title={font.name}
                    >
                        <span className="truncate w-full text-sm" style={{ fontFamily: font.value.split(',')[0].replace(/'/g, "") }}>
                            {font.name.split('(')[0].trim()}
                        </span>
                    </button>
                ))}
             </div>

             {/* Pagination Dots */}
             <div className="flex justify-center gap-1.5 mt-2">
                {Array.from({ length: totalFontPages }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`w-1.5 h-1.5 rounded-full transition-colors ${i === fontPage ? 'bg-slate-800' : 'bg-slate-300'}`} 
                    />
                ))}
             </div>
        </div>

        {/* Color Palette & Gradient */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-4">
           {/* Color Header + Custom Picker */}
           <div className="flex justify-between items-center">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{t('text_color')}</label>
              <div className="flex items-center gap-2">
                 <div className="w-5 h-5 rounded-full border border-slate-200 shadow-inner overflow-hidden relative cursor-pointer ring-1 ring-offset-1 ring-slate-100">
                   <input 
                     type="color" 
                     value={data.textColor.startsWith('linear') ? '#ffffff' : data.textColor}
                     onChange={(e) => onUpdate({ textColor: e.target.value })}
                     className="absolute -top-2 -left-2 w-10 h-10 cursor-pointer p-0 opacity-0" 
                   />
                   <div className="w-full h-full" style={{ background: data.textColor }}></div>
                 </div>
              </div>
           </div>

           {/* Color Grid */}
           <div className="space-y-3">
              <div className="flex justify-between">
                {LIGHT_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>
              <div className="flex justify-between">
                {DARK_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>

              {/* Gradient Options */}
              <div className="pt-2 border-t border-slate-100">
                 <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">Gradients</p>
                 <div className="flex justify-between">
                    {GRADIENT_COLORS.map((gradient, i) => (
                        <button
                            key={i}
                            onClick={() => onUpdate({ textColor: gradient })}
                            className={`w-6 h-6 rounded-full border transition-all ${data.textColor === gradient ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                            style={{ background: gradient }}
                            title="Gradient"
                        />
                    ))}
                 </div>
              </div>
           </div>

           <div className="h-px bg-slate-100 w-full my-2"></div>

           {/* Text Effects Selector */}
           <div className="pt-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 block">{t('text_effects')}</label>
              <div className="grid grid-cols-3 gap-2">
                 {TEXT_EFFECTS.map((effect) => (
                    <button
                        key={effect.id}
                        onClick={() => onUpdate({ textEffect: effect.id })}
                        className={`text-xs py-2 px-1 rounded-lg border transition-all font-medium ${data.textEffect === effect.id ? 'bg-blue-50 border-blue-400 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:border-blue-200'}`}
                        style={{ fontFamily: 'sans-serif' }}
                    >
                        <span style={effect.style as any}>Aa</span> {effect.label}
                    </button>
                 ))}
              </div>
           </div>
        </div>
      </div>

      {/* Custom Name */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('footer_label')}</label>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl p-3 focus-within:bg-white focus-within:border-blue-300 focus-within:ring-4 focus-within:ring-blue-50 transition-all">
          <Type size={16} className="text-slate-400" />
          <input 
            type="text" 
            placeholder="Family Name / Church Name"
            className="flex-1 outline-none bg-transparent text-sm font-medium text-slate-800"
            value={data.customName}
            onChange={(e) => onUpdate({ customName: e.target.value })}
          />
        </div>
      </div>

      {/* Template Selection */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('theme')}</label>
        <div className="grid grid-cols-5 gap-3">
          {Object.values(TemplateStyle).map((style) => (
            <button
              key={style}
              onClick={() => handleTemplateChange(style)}
              className={`group relative w-full aspect-[3/4] rounded-xl border-2 transition-all shadow-sm overflow-hidden ${data.template === style ? 'border-blue-600 ring-2 ring-blue-100 scale-105' : 'border-transparent hover:border-blue-200 hover:scale-105'}`}
              title={style}
            >
               {/* Use Real Image Thumbnail */}
               <div className="w-full h-full bg-cover bg-center transition-transform group-hover:scale-110 duration-700"
                    style={{ backgroundImage: `url(${DEFAULT_BACKGROUNDS[style]})` }}
               ></div>

               {/* Label Overlay */}
               <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent p-1.5 pt-4 flex justify-center">
                  <span className="text-[9px] font-bold text-white uppercase tracking-wider">{style}</span>
               </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default EditorPanel;

import React, { forwardRef, useMemo } from 'react';
import { PosterData, AppMode, TemplateStyle, LayoutType, TextEffect } from '../types';
import { Upload, Camera, Image as ImageIcon } from 'lucide-react';

interface Props {
  data: PosterData;
  scale?: number;
  onTriggerUpload?: (field: keyof PosterData) => void;
}

const PosterPreview = forwardRef<HTMLDivElement, Props>(({ data, scale = 1, onTriggerUpload }, ref) => {
  // Styles based on template
  const getTemplateStyles = () => {
    switch (data.template) {
      case TemplateStyle.MINIMAL:
        return { overlay: "bg-white/90", textBase: "text-slate-900" };
      case TemplateStyle.NATURE:
        return { overlay: "bg-black/20", textBase: "text-white" };
      case TemplateStyle.ABSTRACT:
        return { overlay: "bg-purple-900/40", textBase: "text-white" };
      case TemplateStyle.GOLDEN:
        return { overlay: "bg-black/60", textBase: "text-amber-100" };
      case TemplateStyle.GRADIENT:
        return { overlay: "bg-gradient-to-t from-blue-900/80 via-transparent to-transparent", textBase: "text-white" };
      default:
        return { overlay: "bg-black/40", textBase: "text-white" };
    }
  };

  const styles = getTemplateStyles();

  // Helper to generate text styles based on Effect
  const getTextEffectStyles = (effect: TextEffect, color: string): React.CSSProperties => {
    const base: React.CSSProperties = {
      fontFamily: data.fontFamily,
      color: color,
    };

    if (color.startsWith('linear-gradient')) {
        base.backgroundImage = color;
        base.backgroundClip = 'text';
        base.WebkitBackgroundClip = 'text';
        base.WebkitTextFillColor = 'transparent';
        base.color = 'transparent'; 
    }

    switch (effect) {
      case TextEffect.SHADOW_SOFT:
        return { ...base, textShadow: '0 4px 8px rgba(0,0,0,0.5)' };
      case TextEffect.SHADOW_HARD:
        return { ...base, textShadow: '3px 3px 0px rgba(0,0,0,1)' };
      case TextEffect.OUTLINE:
        return { 
          ...base, 
          WebkitTextStroke: `1px ${color === '#000000' ? '#ffffff' : '#000000'}`, 
          textShadow: 'none' 
        };
      case TextEffect.NEON:
        return { 
          ...base, 
          textShadow: `0 0 5px #fff, 0 0 10px ${color}, 0 0 20px ${color}` 
        };
      case TextEffect.RETRO:
        return { ...base, textShadow: '2px 2px 0px #d1d5db, 4px 4px 0px #9ca3af' };
      case TextEffect.ELEGANT:
        return { ...base, textShadow: '0px 1px 0px rgba(255,255,255,0.4), 0px -1px 0px rgba(0,0,0,0.4)' };
      case TextEffect.GLITCH:
        return { ...base, textShadow: '2px 0 rgba(255,0,0,0.5), -2px 0 rgba(0,0,255,0.5)' };
      case TextEffect.NONE:
      default:
        return base;
    }
  };

  const textStyle = getTextEffectStyles(data.textEffect, data.textColor);
  const accentStyle: React.CSSProperties = {
    fontFamily: data.fontFamily,
    color: data.textColor.startsWith('linear-gradient') ? '#ffffff' : data.textColor,
    opacity: 0.9,
    textShadow: '0px 1px 2px rgba(0,0,0,0.5)',
  };

  const baseWidth = 400;
  const baseHeight = 500;

  // --- Intelligent Highlighting Logic ---

  // 1. Determine which words to highlight
  const highlightedKeywords = useMemo(() => {
    if (data.mode !== AppMode.VERSE || !data.verseText) return new Set<string>();

    const text = data.verseText;
    const commonStopWords = new Set(['the', 'and', 'that', 'have', 'for', 'not', 'with', 'you', 'this', 'but', 'his', 'from', 'they', 'we', 'say', 'her', 'she', 'will', 'an', 'one', 'would', 'there', 'their', 'what', 'so', 'up', 'out', 'if', 'about', 'who', 'get', 'which', 'go', 'me', 'when', 'make', 'can', 'like', 'time', 'no', 'just', 'him', 'know', 'take', 'people', 'into', 'year', 'your', 'good', 'some', 'could', 'them', 'see', 'other', 'than', 'then', 'now', 'look', 'only', 'come', 'its', 'over', 'think', 'also', 'back', 'after', 'use', 'two', 'how', 'our', 'work', 'first', 'well', 'way', 'even', 'new', 'want', 'because', 'any', 'these', 'give', 'day', 'most', 'us', 'are', 'is', 'was', 'be', 'been', 'being']);

    const christianKeywords = new Set(['god', 'jesus', 'lord', 'christ', 'holy', 'spirit', 'father', 'faith', 'love', 'grace', 'mercy', 'peace', 'joy', 'hope', 'life', 'light', 'truth', 'heart', 'soul', 'pray', 'bless', 'glory', 'saved', 'world', 'son', 'heaven', 'believe', 'eternal', 'word', 'king', 'cross', 'blood', 'lamb', 'shepherd']);

    const words = text.split(/[\s,.!?;:"'-]+/); // Split by punctuation to score clean words

    const candidates = words.map((w, i) => {
        const clean = w.toLowerCase();
        let score = 0;
        if (clean.length < 3) return { word: clean, score: 0 }; // Ignore tiny words

        if (christianKeywords.has(clean)) score += 20;
        if (!commonStopWords.has(clean)) score += clean.length; // Length bonus
        if (w.length > 0 && w[0] === w[0].toUpperCase() && /^[A-Z]/.test(w)) score += 5; // Capitalization bonus

        return { word: clean, score };
    });

    // Sort by score
    const sorted = candidates.filter(c => c.score > 0).sort((a, b) => b.score - a.score);

    // Pick top 3 unique
    const topWords = new Set<string>();
    for (const c of sorted) {
        if (topWords.size >= 3) break;
        topWords.add(c.word);
    }
    return topWords;
  }, [data.verseText, data.mode]);

  // 2. Define Highlight Style (Complementary Font & Color)
  const highlightStyle = useMemo(() => {
    const isBaseScript = data.fontFamily.includes('cursive') || data.fontFamily.includes('Vibes') || data.fontFamily.includes('Script') || data.fontFamily.includes('Pacifico');

    // If base is script, use a strong Serif for highlights. If base is Sans/Serif, use a nice Script.
    const font = isBaseScript ? "'Cinzel', serif" : "'Great Vibes', cursive";

    // Determine Highlight Color based on background brightness estimate (using textColor as proxy)
    // If text is whiteish -> Accent is Gold/Amber
    // If text is blackish -> Accent is Deep Red/Blue or Gold
    const isDarkText = data.textColor === '#000000' || data.textColor.startsWith('#0') || data.textColor.startsWith('#1') || data.textColor.startsWith('#3');
    const color = isDarkText ? '#B45309' : '#FCD34D'; // Amber-700 vs Amber-300

    return {
        fontFamily: font,
        color: color,
        fontWeight: isBaseScript ? 'bold' : 'normal', // Serif highlights need bold, Script usually doesn't
        fontSize: '1.25em',
        textShadow: isDarkText ? 'none' : '0 0 10px rgba(252, 211, 77, 0.5)', // Glow for light mode
    };
  }, [data.fontFamily, data.textColor]);

  // 3. Render Component
  const HighlightedVerseText = () => {
    if (!data.verseText) return null;

    // Split text but keep delimiters/punctuation for reconstruction
    const parts = data.verseText.split(/(\s+|[.,!?;:"'-]+)/g);

    return (
        <p className="text-3xl md:text-3xl leading-snug italic px-4" style={textStyle}>
            "
            {parts.map((part, i) => {
                const clean = part.toLowerCase().replace(/[^a-z0-9]/g, '');
                const isHighlight = clean.length > 2 && highlightedKeywords.has(clean);

                if (isHighlight) {
                    return (
                        <span key={i} style={{ ...highlightStyle, display: 'inline-block', transform: 'scale(1.1)' }}>
                            {part}
                        </span>
                    );
                }
                return <span key={i}>{part}</span>;
            })}
            "
        </p>
    );
  };

  // Interactive Upload Wrapper
  const UploadTrigger = ({ field, children, className = "" }: { field: keyof PosterData, children?: React.ReactNode, className?: string }) => (
    <div 
      className={`relative group cursor-pointer ${className}`}
      onClick={(e) => { e.stopPropagation(); onTriggerUpload?.(field); }}
      title={`Click to upload ${field === 'backgroundImageUrl' ? 'Background' : field === 'uploadedPhotoUrl' ? 'Photo' : 'Logo'}`}
    >
      {children}
      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-inherit z-50 pointer-events-none">
        <Upload size={16} className="text-white" />
      </div>
    </div>
  );

  // Common Elements
  const LogoElement = () => (
    <UploadTrigger field="logoUrl" className="inline-block rounded-full overflow-hidden">
      {data.logoUrl ? (
        <img src={data.logoUrl} alt="Logo" className="h-16 w-16 object-cover rounded-full drop-shadow-md" crossOrigin="anonymous"/>
      ) : (
        <div className="h-16 w-16 bg-white/20 border-2 border-dashed border-white/50 rounded-full flex items-center justify-center backdrop-blur-sm">
            <span className="text-[10px] text-white font-bold uppercase">Logo</span>
        </div>
      )}
    </UploadTrigger>
  );

  const PhotoElement = ({ className = "" }: { className?: string }) => (
     <UploadTrigger field="uploadedPhotoUrl" className={className}>
        {data.uploadedPhotoUrl ? (
            <div className="w-full h-full rounded-[2.5rem] border-4 border-white/30 overflow-hidden shadow-2xl">
                <img src={data.uploadedPhotoUrl} alt="User" className="w-full h-full object-cover" crossOrigin="anonymous"/>
            </div>
        ) : (
            <div className="w-full h-full rounded-[2.5rem] border-4 border-dashed border-white/40 bg-white/10 flex flex-col items-center justify-center text-white/80 backdrop-blur-sm">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1 uppercase">Photo</span>
            </div>
        )}
     </UploadTrigger>
  );

  const TextContent = ({ align = "center" }: { align?: "left" | "center" | "right" }) => (
    <div className={`flex flex-col gap-4 ${align === 'center' ? 'items-center text-center' : align === 'left' ? 'items-start text-left' : 'items-end text-right'}`}>
         {data.mode === AppMode.VERSE ? (
            <>
              {/* Highlighted Verse Component */}
              <HighlightedVerseText />

              <div className="h-1 w-12 bg-current opacity-50 rounded-full" style={{ color: data.textColor }}></div>

              <div className="flex flex-col items-center gap-1">
                  {/* Primary Reference (Selected Language) */}
                  <p className="text-lg font-bold uppercase tracking-widest" style={accentStyle}>
                    {data.verseReference}
                  </p>

                  {/* English Reference (Only show if it's different/exists) */}
                  {data.verseReferenceEnglish && data.verseReferenceEnglish !== data.verseReference && (
                      <p className="text-sm font-bold uppercase tracking-widest opacity-80" style={{ ...accentStyle, fontFamily: "'Inter', sans-serif" }}>
                        {data.verseReferenceEnglish}
                      </p>
                  )}
              </div>
            </>
          ) : (
            <>
              <h1 className="text-4xl font-bold leading-tight" style={textStyle}>
                {data.eventTitle || "Event Title"}
              </h1>
              <p className="text-lg whitespace-pre-wrap font-light opacity-90" style={textStyle}>
                {data.eventDetails || "Date • Time • Venue"}
              </p>
            </>
          )}
    </div>
  );

  const renderLayoutContent = () => {
    switch (data.layout) {
      // 1) Right Corner: Photo Top-Right, Logo Top-Left
      case LayoutType.RIGHT_CORNER:
        return (
          <div className="w-full h-full p-6 flex flex-col">
             <div className="flex justify-between items-start mb-4">
                {/* Logo Top Left */}
                <div className="flex flex-col items-start gap-1">
                    <LogoElement />
                    {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                </div>
                {/* Photo Top Right */}
                <div className="w-60 h-60">
                    <PhotoElement />
                </div>
             </div>

             {/* Text Area */}
             <div className="flex-1 flex items-center justify-center">
                <TextContent align="center" />
             </div>
          </div>
        );

      // 2) Left Corner: Photo Top-Left, Logo Top-Right
      case LayoutType.LEFT_CORNER:
        return (
            <div className="w-full h-full p-6 flex flex-col">
               <div className="flex justify-between items-start mb-4">
                  {/* Photo Top Left */}
                  <div className="w-60 h-60">
                      <PhotoElement />
                  </div>
                  {/* Logo Top Right */}
                  <div className="flex flex-col items-end gap-1">
                      <LogoElement />
                      {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                  </div>
               </div>

               {/* Text Area */}
               <div className="flex-1 flex items-center justify-center">
                  <TextContent align="center" />
               </div>
            </div>
          );

      // 3) Bottom Middle: Content Top, Photo Bottom Center, Logo Bottom Left
      case LayoutType.BOTTOM_MIDDLE:
        return (
            <div className="w-full h-full p-6 flex flex-col">
               {/* Text Area Top */}
               <div className="flex-1 flex items-center justify-center mb-8">
                  <TextContent align="center" />
               </div>

               {/* Bottom Section */}
               <div className="relative h-64 w-full mt-4">
                   {/* Logo Bottom Left */}
                   <div className="absolute bottom-0 left-0 flex flex-col items-start gap-1">
                      <LogoElement />
                      {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90">{data.customName}</span>}
                   </div>

                   {/* Photo Bottom Center */}
                   <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-60 h-60">
                       <PhotoElement />
                   </div>
               </div>
            </div>
        );

      // 4) Cinematic
      case LayoutType.CINEMATIC:
      default:
        return (
          <div className="w-full h-full flex flex-col justify-end relative">
            <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/30 z-0 pointer-events-none"></div>

            {/* Interactive Areas */}
            <div className="absolute top-6 left-6 z-10">
               <LogoElement />
            </div>

            <div className="absolute top-6 right-6 z-10 w-24 h-24 opacity-80 hover:opacity-100 transition-opacity">
                <PhotoElement className="w-full h-full" />
            </div>

            <div className="relative z-20 p-8 text-center pb-16">
               <div className="w-px h-12 bg-white/50 mx-auto mb-4"></div>
               <TextContent align="center" />
               {data.customName && <p className="mt-4 text-xs font-bold uppercase tracking-[0.2em] text-white/70">{data.customName}</p>}
            </div>
          </div>
        );
    }
  };

  return (
    <div className="w-full flex justify-center py-4 select-none" style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }}>
      <div 
        ref={ref}
        id="poster-canvas"
        className={`relative bg-slate-200 overflow-hidden shadow-[0_20px_50px_-12px_rgba(0,0,0,0.5)] flex flex-col group/poster`}
        style={{ width: baseWidth, height: baseHeight }}
      >
        {/* Background Image (Click to Upload) */}
        <div 
            className="absolute inset-0 z-0 cursor-pointer"
            onClick={(e) => { e.stopPropagation(); onTriggerUpload?.('backgroundImageUrl'); }}
            title="Click background to change image"
        >
            {data.backgroundImageUrl ? (
            <img 
                src={data.backgroundImageUrl} 
                alt="Background" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                crossOrigin="anonymous"
            />
            ) : (
            <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                <ImageIcon className="text-slate-600" size={48} />
            </div>
            )}
            {/* Hover hint for background */}
            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover/poster:opacity-100 flex items-center justify-center transition-opacity pointer-events-none">
                <span className="bg-black/60 text-white px-3 py-1 rounded-full text-xs font-bold backdrop-blur-sm border border-white/20">
                    Click elements to edit
                </span>
            </div>
        </div>

        {/* Overlay for non-cinematic modes */}
        {data.layout !== LayoutType.CINEMATIC && (
          <div className={`absolute inset-0 z-0 pointer-events-none ${styles.overlay}`}></div>
        )}

        {/* Content Layer */}
        <div className="relative z-10 w-full h-full pointer-events-auto">
           {renderLayoutContent()}
        </div>

      </div>
    </div>
  );
});

PosterPreview.displayName = 'PosterPreview';

export default PosterPreview;

export enum AppMode {
  VERSE = 'VERSE',
  EVENT = 'EVENT'
}

export enum TemplateStyle {
  MINIMAL = 'Minimal',
  NATURE = 'Nature',
  ABSTRACT = 'Abstract',
  GOLDEN = 'Golden',
  GRADIENT = 'Gradient'
}

export enum LayoutType {
  RIGHT_CORNER = 'Right Corner',
  LEFT_CORNER = 'Left Corner',
  BOTTOM_MIDDLE = 'Bottom Middle',
  CINEMATIC = 'Cinematic'
}

export enum TextEffect {
  NONE = 'none',
  SHADOW_SOFT = 'shadow-soft',
  SHADOW_HARD = 'shadow-hard',
  OUTLINE = 'outline',
  NEON = 'neon',
  RETRO = 'retro',
  ELEGANT = 'elegant',
  GLITCH = 'glitch'
}

export interface PosterData {
  mode: AppMode;
  // Verse Mode
  verseReference: string; // The Localized/Target Language Reference
  verseReferenceEnglish: string; // The English Reference
  verseText: string;
  // Event Mode
  eventTitle: string;
  eventDetails: string; // Date, Time, Venue
  // Shared
  language: string; // Target language for translation
  interfaceLanguage: string; // UI Language
  template: TemplateStyle;
  layout: LayoutType;
  backgroundImageUrl: string | null;
  uploadedPhotoUrl: string | null;
  logoUrl: string | null;
  customName: string; // Family name / Church name

  // Customization
  fontFamily: string;
  textColor: string;
  textEffect: TextEffect;

  // Flexible Layout
  textPosition: { x: number; y: number }; // Percentage 0-100
  textWidth: number; // Percentage 0-100
}

// For html2canvas global availability
declare global {
  interface Window {
    html2canvas: (element: HTMLElement, options?: any) => Promise<HTMLCanvasElement>;
  }
}

import React, { useState, useRef } from 'react';
import { AppMode, PosterData, TemplateStyle, LayoutType, TextEffect } from './types';
import { DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, SUPPORTED_LANGUAGES } from './constants';
import { generateBackground } from './services/geminiService';
import PosterPreview from './components/PosterPreview';
import EditorPanel from './components/EditorPanel';
import { Download, Share2, BookOpen, Calendar, AlertTriangle, Image as ImageIcon, Upload, ChevronRight, ChevronLeft, Sparkles, Languages, Wand2, Cross } from 'lucide-react';

const App: React.FC = () => {
  const posterRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadField, setActiveUploadField] = useState<keyof PosterData | null>(null);
  const [isGeneratingBg, setIsGeneratingBg] = useState(false);

  // Initial State
  const [data, setData] = useState<PosterData>({
    mode: AppMode.VERSE,
    verseReference: "John 3:16",
    verseReferenceEnglish: "John 3:16", // Initialize English Reference
    verseText: "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.",
    eventTitle: "Sunday Service",
    eventDetails: "Sunday, 9:00 AM\nMain Sanctuary\nPastor John Doe",
    language: "English",
    interfaceLanguage: "en", // Default UI Language
    template: TemplateStyle.NATURE,
    layout: LayoutType.RIGHT_CORNER,
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,

    // Flexible Layout Defaults (Centered, 80% width)
    textPosition: { x: 50, y: 50 },
    textWidth: 80,
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Layout Cycling Logic
  const layouts = [
    { id: LayoutType.RIGHT_CORNER, label: 'Corner R' },
    { id: LayoutType.LEFT_CORNER, label: 'Corner L' },
    { id: LayoutType.BOTTOM_MIDDLE, label: 'Bottom' },
    { id: LayoutType.CINEMATIC, label: 'Cinematic' },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    updateData({ layout: layouts[nextIndex].id });
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    updateData({ layout: layouts[prevIndex].id });
  };

  // File Upload Logic
  const triggerUpload = (field: keyof PosterData) => {
    setActiveUploadField(field);
    if (fileInputRef.current) {
      fileInputRef.current.value = ""; // Reset
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUploadField) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          updateData({ [activeUploadField]: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // AI Background Generation
  const handleAiBackgroundGen = async () => {
    if (!process.env.API_KEY) {
        alert("Please configure your API Key to use AI features.");
        return;
    }

    setIsGeneratingBg(true);
    // Pass the verse text (or event title) as context so the AI generates something relatable
    // The service currently takes style, but we can assume the style prompt inside uses the template name
    const bgUrl = await generateBackground(data.template); 

    if (bgUrl) {
      updateData({ backgroundImageUrl: bgUrl });
    } else {
      alert("Failed to generate background. Please try again.");
    }
    setIsGeneratingBg(false);
  };

  const handleDownload = async () => {
    if (posterRef.current && window.html2canvas) {
      try {
        // Use a small timeout to ensure images are loaded if they were just swapped
        setTimeout(async () => {
            const canvas = await window.html2canvas(posterRef.current!, {
                useCORS: true, // Important for external images
                scale: 2, // Higher quality
                backgroundColor: null,
            });

            const link = document.createElement('a');
            link.download = `gracelens-${data.mode.toLowerCase()}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        }, 100);
      } catch (err) {
        console.error("Download failed", err);
        alert("Could not download image. Please try again.");
      }
    } else {
        alert("Download library not loaded yet.");
    }
  };

  const handleShare = () => {
    if (navigator.share) {
        alert("On a mobile device, this would open the share sheet. Generate the image first to share properly!");
    } else {
        alert("Share feature is available on mobile devices.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileChange} 
      />

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-2xl mx-auto px-4 sm:px-6 h-auto py-3 flex flex-col sm:flex-row items-center justify-between gap-3">

          {/* Futuristic Logo */}
          <div className="flex items-center gap-3 group cursor-pointer self-start sm:self-auto">
             <div className="relative w-10 h-10 flex items-center justify-center">
                <div className="absolute inset-0 bg-cyan-500 blur-lg opacity-20 group-hover:opacity-40 transition-opacity rounded-full"></div>
                <div className="relative bg-gradient-to-br from-slate-900 to-slate-800 rounded-xl p-2 shadow-lg ring-1 ring-white/10 group-hover:ring-cyan-400/50 transition-all flex items-center justify-center">
                   {/* Updated Icon to Cross */}
                   <Cross className="text-cyan-400 w-full h-full" />
                </div>
                <div className="absolute -top-1 -right-1">
                    <Sparkles size={12} className="text-purple-500 fill-purple-500 animate-pulse" />
                </div>
             </div>
             <div className="flex flex-col">
                <h1 className="text-2xl font-bold tracking-tight" style={{ fontFamily: "'Orbitron', sans-serif" }}>
                  <span className="bg-clip-text text-transparent bg-gradient-to-r from-cyan-500 via-blue-600 to-purple-600">
                    GraceLens
                  </span>
                </h1>
                {/* Updated Subtitle */}
                <span className="text-[10px] font-bold tracking-[0.2em] text-slate-400 uppercase -mt-1 pl-0.5">
                    CHRISTIAN POSTER APP
                </span>
             </div>
          </div>

          <div className="flex items-center gap-3 self-end sm:self-auto">
             {/* LANGUAGE SELECTION DROPDOWN */}
             <div className="relative group">
                <div className="flex items-center gap-1.5 bg-slate-100 px-3 py-1.5 rounded-lg cursor-pointer border border-slate-200 hover:bg-slate-50 hover:border-blue-300 transition-all">
                   <Languages size={14} className="text-slate-500"/>
                   <span className="text-xs font-bold text-slate-700">Selection</span>
                   <select 
                      value={data.interfaceLanguage}
                      onChange={(e) => updateData({ interfaceLanguage: e.target.value, language: e.target.options[e.target.selectedIndex].text })}
                      className="absolute inset-0 opacity-0 cursor-pointer"
                   >
                      {SUPPORTED_LANGUAGES.map(lang => (
                         <option key={lang.code} value={lang.code}>{lang.name}</option>
