import React, { useState, useRef } from 'react';
import { AppMode, PosterData, TemplateStyle, LayoutType, TextEffect } from './types';
import { DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, SUPPORTED_LANGUAGES } from './constants';
import { generateBackground } from './services/geminiService';
import PosterPreview from './components/PosterPreview';
import EditorPanel from './components/EditorPanel';
import { Download, Share2, BookOpen, Calendar, AlertTriangle, Image as ImageIcon, Upload, ChevronRight, ChevronLeft, Sparkles, Languages, Wand2, Cross } from 'lucide-react';

const App: React.FC = () => {
  const posterRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadField, setActiveUploadField] = useState<keyof PosterData | null>(null);
  const [isGeneratingBg, setIsGeneratingBg] = useState(false);

  // Initial State
  const [data, setData] = useState<PosterData>({
    mode: AppMode.VERSE,
    verseReference: "John 3:16",
    verseReferenceEnglish: "John 3:16", // Initialize English Reference
    verseText: "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.",
    eventTitle: "Sunday Service",
    eventDetails: "Sunday, 9:00 AM\nMain Sanctuary\nPastor John Doe",
    language: "English",
    interfaceLanguage: "en", // Default UI Language
    template: TemplateStyle.NATURE,
    layout: LayoutType.RIGHT_CORNER,
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,

    // Flexible Layout Defaults (Centered, 80% width, 1.0 scale)
    textPosition: { x: 50, y: 50 },
    textWidth: 80,
    textScale: 1.0, 
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Layout Cycling Logic
  const layouts = [
    { id: LayoutType.RIGHT_CORNER, label: 'Corner R' },
    { id: LayoutType.LEFT_CORNER, label: 'Corner L' },
    { id: LayoutType.BOTTOM_MIDDLE, label: 'Bottom' },
    { id: LayoutType.CINEMATIC, label: 'Cinematic' },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    updateData({ layout: layouts[nextIndex].id });
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    updateData({ layout: layouts[prevIndex].id });
  };

  // File Upload Logic
  const triggerUpload = (field: keyof PosterData) => {
    setActiveUploadField(field);
    if (fileInputRef.current) {
      fileInputRef.current.value = ""; // Reset
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUploadField) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          updateData({ [activeUploadField]: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // AI Background Generation
  const handleAiBackgroundGen = async () => {
    if (!process.env.API_KEY) {
        alert("Please configure your API Key to use AI features.");
        return;
    }

    setIsGeneratingBg(true);
    // Pass the verse text (or event title) as context so the AI generates something relatable
    // The service currently takes style, but we can assume the style prompt inside uses the template name
    const bgUrl = await generateBackground(data.template); 

    if (bgUrl) {
      updateData({ backgroundImageUrl: bgUrl });
    } else {
      alert("Failed to generate background. Please try again.");
    }
    setIsGeneratingBg(false);
  };

  const handleDownload = async () => {
    if (posterRef.current && window.html2canvas) {
      try {
        // Use a small timeout to ensure images are loaded if they were just swapped
        setTimeout(async () => {
            const canvas = await window.html2canvas(posterRef.current!, {
                useCORS: true, // Important for external images
                scale: 2, // Higher quality
                backgroundColor: null,
            });

            const link = document.createElement('a');
            link.download = `gracelens-${data.mode.toLowerCase()}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        }, 100);
      } catch (err) {
        console.error("Download failed", err);
        alert("Could not download image. Please try again.");
      }
    } else {
        alert("Download library not loaded yet.");
    }
  };

  const handleShare = () => {
    if (navigator.share) {
        alert("On a mobile device, this would open the share sheet. Generate the image first to share properly!");
    } else {
        alert("Share feature is available on mobile devices.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileChange} 
      />

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-2xl mx-auto px-4 sm:px-6 h-auto py-3 flex flex-col sm:flex-row items-center justify-between gap-3">

          {/* Futuristic Logo */}
          <div className="flex items-center gap-3 group cursor-pointer self-start sm:self-auto">
             <div className="relative w-10 h-10 flex items-center justify-center">
                <div className="absolute inset-0 bg-cyan-500 blur-lg opacity-20 group-hover:opacity-40 transition-opacity rounded-full"></div>
                <div className="relative bg-gradient-to-br from-slate-900 to-slate-800 rounded-xl p-2 shadow-lg ring-1 ring-white/10 group-hover:ring-cyan-400/50 transition-all flex items-center justify-center">
                   {/* Updated Icon to Cross */}
                   <Cross className="text-cyan-400 w-full h-full" />
                </div>
                <div className="absolute -top-1 -right-1">
                    <Sparkles size={12} className="text-purple-500 fill-purple-500 animate-pulse" />
                </div>
             </div>
             <div className="flex flex-col">
                <h1 className="text-2xl font-bold tracking-tight" style={{ fontFamily: "'Orbitron', sans-serif" }}>
                  <span className="bg-clip-text text-transparent bg-gradient-to-r from-cyan-500 via-blue-600 to-purple-600">
                    GraceLens
                  </span>
                </h1>
                {/* Updated Subtitle */}
                <span className="text-[10px] font-bold tracking-[0.2em] text-slate-400 uppercase -mt-1 pl-0.5">
                    CHRISTIAN POSTER APP
                </span>
             </div>
          </div>

          <div className="flex items-center gap-3 self-end sm:self-auto">
             {/* LANGUAGE SELECTION DROPDOWN */}
             <div className="relative group">
                <div className="flex items-center gap-1.5 bg-slate-100 px-3 py-1.5 rounded-lg cursor-pointer border border-slate-200 hover:bg-slate-50 hover:border-blue-300 transition-all">
                   <Languages size={14} className="text-slate-500"/>
                   <span className="text-xs font-bold text-slate-700">Selection</span>
                   <select 
                      value={data.interfaceLanguage}
                      onChange={(e) => updateData({ interfaceLanguage: e.target.value, language: e.target.options[e.target.selectedIndex].text })}
                      className="absolute inset-0 opacity-0 cursor-pointer"
                   >
                      {SUPPORTED_LANGUAGES.map(lang => (
                         <option key={lang.code} value={lang.code}>{lang.name}</option>
                      ))}
                   </select>
                   <span className="text-[10px] bg-slate-200 px-1.5 rounded text-slate-600 font-mono ml-1">{data.interfaceLanguage.toUpperCase()}</span>
                </div>
             </div>

             {/* Tabs: High Contrast Style */}
             <nav className="flex bg-slate-100/80 p-1.5 rounded-xl shadow-inner border border-slate-200/50">
                <button 
                  onClick={() => switchMode(AppMode.VERSE)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.VERSE ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <BookOpen size={14}/> Verse
                </button>
                <button 
                  onClick={() => switchMode(AppMode.EVENT)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.EVENT ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <Calendar size={14}/> Event
                </button>
             </nav>
          </div>
        </div>
      </header>

      {/* Main Content - Centered Single Column */}
      <main className="flex-1 w-full max-w-2xl mx-auto px-4 py-8 flex flex-col items-center gap-8">

        {!process.env.API_KEY && (
           <div className="w-full bg-amber-50 border-l-4 border-amber-500 p-4 rounded-xl flex items-start gap-3 shadow-sm">
              <AlertTriangle className="text-amber-500 mt-0.5" />
              <div>
                  <h3 className="font-bold text-amber-800">API Key Missing</h3>
                  <p className="text-amber-700 text-sm">Please set your <code className="bg-amber-100 px-1 rounded">process.env.API_KEY</code> to use the AI translation and background generation features.</p>
              </div>
           </div>
        )}

        {/* 1. Poster Preview with Side Arrow Navigation */}
        <div className="relative w-fit group select-none">

            {/* Left Arrow */}
            <button 
                onClick={prevLayout}
                className="absolute -left-4 md:-left-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                title="Previous Layout"
            >
                <ChevronLeft size={24} className="group-hover/btn:-translate-x-0.5 transition-transform" />
