            {/* Poster Container */}
            <div className="bg-white p-2 rounded-[2rem] shadow-2xl shadow-slate-200 border-4 border-white relative ring-1 ring-slate-100">
                {/* Background Glow */}
                <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 to-purple-500/10 blur-3xl rounded-full transform scale-110 z-0 pointer-events-none"></div>

                <div className="relative z-10 rounded-3xl overflow-hidden">
                    <PosterPreview 
                        data={data} 
                        ref={posterRef} 
                        onTriggerUpload={triggerUpload} 
                        // We can pass a callback to update state from the preview
                        onUpdateData={updateData}
                    />
                </div>
            </div>

            {/* Right Arrow */}
            <button 
                onClick={nextLayout}
                className="absolute -right-4 md:-right-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                title="Next Layout"
            >
                <ChevronRight size={24} className="group-hover/btn:translate-x-0.5 transition-transform" />
            </button>

            {/* Layout Indicator */}
            <div className="absolute -bottom-10 left-0 right-0 flex justify-center items-center gap-3">
                 <div className="bg-slate-900/5 backdrop-blur-sm px-4 py-1.5 rounded-full border border-slate-200/50 flex items-center gap-2">
                    <span className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Layout:</span>
                    <span className="text-xs font-bold text-slate-800">
                        {layouts[currentLayoutIndex].label}
