  const [initialScale, setInitialScale] = useState(1);

  const handleMouseDown = (e: React.MouseEvent, id: 'text' | 'logo' | 'photo', action: 'drag' | 'resize' | 'scale') => {
    e.stopPropagation();
    setActiveDragId(id);
    setDragAction(action);
    setDragStart({ x: e.clientX, y: e.clientY });
    if (action === 'scale') {
        setInitialScale(data.textScale || 1);
    }
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!activeDragId) return;
      if (!onUpdateData) return;

      const deltaX = (e.clientX - dragStart.x) / scale;
      const deltaY = (e.clientY - dragStart.y) / scale;

      // Convert pixels to percentage relative to canvas
      const deltaXPercent = (deltaX / baseWidth) * 100;
      const deltaYPercent = (deltaY / baseHeight) * 100;

      if (activeDragId === 'text') {
          if (dragAction === 'drag') {
            onUpdateData({
              textPosition: {
                x: Math.max(0, Math.min(100, data.textPosition.x + deltaXPercent)),
                y: Math.max(0, Math.min(100, data.textPosition.y + deltaYPercent)),
              }
            });
          } else if (dragAction === 'resize') {
            onUpdateData({
                textWidth: Math.max(20, Math.min(100, data.textWidth + deltaXPercent))
            });
          } else if (dragAction === 'scale') {
             const scaleDelta = (deltaX + deltaY) * 0.005; 
             const newScale = Math.max(0.5, Math.min(3.0, initialScale + scaleDelta));
             onUpdateData({ textScale: newScale });
          }
      } else if (activeDragId === 'logo' && dragAction === 'drag') {
          onUpdateData({
              logoPosition: {
                  x: Math.max(0, Math.min(100, (data.logoPosition?.x || 10) + deltaXPercent)),
                  y: Math.max(0, Math.min(100, (data.logoPosition?.y || 10) + deltaYPercent))
              }
          });
      } else if (activeDragId === 'photo' && dragAction === 'drag') {
          onUpdateData({
              photoPosition: {
                  x: Math.max(0, Math.min(100, (data.photoPosition?.x || 90) + deltaXPercent)),
                  y: Math.max(0, Math.min(100, (data.photoPosition?.y || 10) + deltaYPercent))
              }
          });
      }

      if (dragAction === 'drag' || dragAction === 'resize') {
          setDragStart({ x: e.clientX, y: e.clientY });
      }
    };

    const handleMouseUp = () => {
      setActiveDragId(null);
    };

    if (activeDragId) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [activeDragId, dragAction, dragStart, initialScale, data, onUpdateData, scale]);


  // --- Components ---
  const HighlightedVerseText = () => {
    if (!data.verseText) return null;
    const parts = data.verseText.split(/(\s+|[.,!?;:"'-]+)/g);
    const fontSizeVal = `${(1.875 * (data.textScale || 1)).toFixed(3)}rem`;

    return (
        <p className="leading-snug italic px-4" style={{ ...textStyle, fontSize: fontSizeVal }}>
            "
            {parts.map((part, i) => {
                const clean = part.toLowerCase().replace(/[^a-z0-9]/g, '');
                const isHighlight = clean.length > 2 && highlightedKeywords.has(clean);
                if (isHighlight) {
                    return (
                        <span key={i} style={{ ...highlightStyle, display: 'inline-block', transform: 'scale(1.1)', fontSize: '1.25em' }}>
                            {part}
                        </span>
                    );
                }
                return <span key={i}>{part}</span>;
            })}
            "
        </p>
    );
  };

  const UploadTrigger = ({ field, children, className = "" }: { field: keyof PosterData, children?: React.ReactNode, className?: string }) => (
    <div 
      className={`relative group cursor-pointer ${className}`}
      onClick={(e) => { e.stopPropagation(); onTriggerUpload?.(field); }}
      title={`Click to upload ${field === 'backgroundImageUrl' ? 'Background' : field === 'uploadedPhotoUrl' ? 'Photo' : 'Logo'}`}
    >
      {children}
      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-inherit z-50 pointer-events-none">
        <Upload size={16} className="text-white" />
      </div>
    </div>
  );

  const LogoElement = () => (
    <UploadTrigger field="logoUrl" className="inline-block rounded-full overflow-hidden w-16 h-16">
      {data.logoUrl ? (
        <img src={data.logoUrl} alt="Logo" className="w-full h-full object-cover rounded-full drop-shadow-md" crossOrigin="anonymous"/>
      ) : (
        <div className="w-full h-full bg-white/20 border-2 border-dashed border-white/50 rounded-full flex items-center justify-center backdrop-blur-sm">
            <span className="text-[10px] text-white font-bold uppercase">Logo</span>
        </div>
      )}
    </UploadTrigger>
  );

  const PhotoElement = ({ className = "" }: { className?: string }) => (
     <UploadTrigger field="uploadedPhotoUrl" className={`w-24 h-24 ${className}`}>
        {data.uploadedPhotoUrl ? (
            <div className="w-full h-full rounded-[1.5rem] border-4 border-white/30 overflow-hidden shadow-2xl">
                <img src={data.uploadedPhotoUrl} alt="User" className="w-full h-full object-cover" crossOrigin="anonymous"/>
            </div>
        ) : (
            <div className="w-full h-full rounded-[1.5rem] border-4 border-dashed border-white/40 bg-white/10 flex flex-col items-center justify-center text-white/80 backdrop-blur-sm">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1 uppercase">Photo</span>
            </div>
        )}
     </UploadTrigger>
  );

  const TextContent = () => (
    <div className={`flex flex-col gap-4 items-center text-center`}>
         {data.mode === AppMode.VERSE ? (
            <>
              <HighlightedVerseText />
              <div className="h-1 w-12 bg-current opacity-50 rounded-full" style={{ color: data.textColor }}></div>
              <div className="flex flex-col items-center gap-1">
                  <p className="text-lg font-bold uppercase tracking-widest" style={accentStyle}>{data.verseReference}</p>
                  {data.verseReferenceEnglish && data.verseReferenceEnglish !== data.verseReference && (
                      <p className="text-sm font-bold uppercase tracking-widest opacity-80" style={{ ...accentStyle, fontFamily: "'Inter', sans-serif" }}>
                        {data.verseReferenceEnglish}
                      </p>
                  )}
              </div>
            </>
          ) : (
            <>
              <h1 className="text-4xl font-bold leading-tight" style={textStyle}>{data.eventTitle || "Event Title"}</h1>
              <p className="text-lg whitespace-pre-wrap font-light opacity-90" style={textStyle}>{data.eventDetails || "Date • Time • Venue"}</p>
            </>
          )}
    </div>
  );

  const renderOverlays = () => {
    switch (data.layout) {
      case LayoutType.CINEMATIC:
        return (
           <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/30 z-0 pointer-events-none"></div>
        );
      default:
        // Generic overlay from template style if needed, can be empty if handled by root style
        return null;
    }
  };

  return (
    <div className="w-full flex justify-center py-4 select-none" style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }}>
      <div 
        ref={ref}
        id="poster-canvas"
        className={`relative bg-slate-200 overflow-hidden shadow-[0_20px_50px_-12px_rgba(0,0,0,0.5)] flex flex-col group/poster`}
        style={{ width: baseWidth, height: baseHeight }}
      >
        {/* Background Image (Click to Upload) */}
        <div 
            className="absolute inset-0 z-0 cursor-pointer"
            onClick={(e) => { e.stopPropagation(); onTriggerUpload?.('backgroundImageUrl'); }}
            title="Click background to change image"
        >
            {data.backgroundImageUrl ? (
            <img 
                src={data.backgroundImageUrl} 
                alt="Background" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                crossOrigin="anonymous"
            />
            ) : (
            <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                <ImageIcon className="text-slate-600" size={48} />
            </div>
            )}
        </div>

        {/* Overlay for non-cinematic modes (Template Color Overlay) */}
        {data.layout !== LayoutType.CINEMATIC && (
          <div className={`absolute inset-0 z-0 pointer-events-none ${styles.overlay}`}></div>
        )}

        {/* Layout Specific Overlays (e.g. Cinematic Gradient) */}
        {renderOverlays()}

        {/* --- MOVABLE LAYERS --- */}

        {/* 1. Logo */}
        <DraggableElement 
            position={data.logoPosition || {x: 10, y: 10}}
            isActive={activeDragId === 'logo'}
            onMouseDown={(e, action) => handleMouseDown(e, 'logo', action)}
        >
             <div className="flex flex-col items-center">
                <LogoElement />
                {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90 mt-1 shadow-black drop-shadow-md">{data.customName}</span>}
             </div>
        </DraggableElement>

        {/* 2. Photo */}
        <DraggableElement 
            position={data.photoPosition || {x: 90, y: 10}}
            isActive={activeDragId === 'photo'}
            onMouseDown={(e, action) => handleMouseDown(e, 'photo', action)}
        >
             <PhotoElement />
        </DraggableElement>

        {/* 3. Text (With Resize/Scale options) */}
        <DraggableElement 
            position={data.textPosition} 
            width={data.textWidth} 
            resizable={true}
            isActive={activeDragId === 'text'}
            onMouseDown={(e, action) => handleMouseDown(e, 'text', action)}
        >
            <TextContent />
        </DraggableElement>

      </div>
    </div>
  );
});

PosterPreview.displayName = 'PosterPreview';

export default PosterPreview;

export enum AppMode {
  VERSE = 'VERSE',
  EVENT = 'EVENT'
}

export enum TemplateStyle {
  MINIMAL = 'Minimal',
  NATURE = 'Nature',
  ABSTRACT = 'Abstract',
  GOLDEN = 'Golden',
  GRADIENT = 'Gradient'
}

export enum LayoutType {
  RIGHT_CORNER = 'Right Corner',
  LEFT_CORNER = 'Left Corner',
  BOTTOM_MIDDLE = 'Bottom Middle',
  CINEMATIC = 'Cinematic'
}

export enum TextEffect {
  NONE = 'none',
  SHADOW_SOFT = 'shadow-soft',
  SHADOW_HARD = 'shadow-hard',
  OUTLINE = 'outline',
  NEON = 'neon',
  RETRO = 'retro',
  ELEGANT = 'elegant',
  GLITCH = 'glitch'
}

export interface PosterData {
  mode: AppMode;
  // Verse Mode
  verseReference: string; // The Localized/Target Language Reference
  verseReferenceEnglish: string; // The English Reference
  verseText: string;
  // Event Mode
  eventTitle: string;
  eventDetails: string; // Date, Time, Venue
  // Shared
  language: string; // Target language for translation
  interfaceLanguage: string; // UI Language
  template: TemplateStyle;
  layout: LayoutType;
  backgroundImageUrl: string | null;
  uploadedPhotoUrl: string | null;
  logoUrl: string | null;
  customName: string; // Family name / Church name

  // Customization
  fontFamily: string;
  textColor: string;
  textEffect: TextEffect;

  // Flexible Layout
  textPosition: { x: number; y: number }; // Percentage 0-100
  textWidth: number; // Percentage 0-100
  textScale: number; // Font size multiplier (1.0 = base size)

  // Movable Assets
  logoPosition: { x: number; y: number }; // Percentage 0-100
  logoWidth: number; // Percentage 0-100
  photoPosition: { x: number; y: number }; // Percentage 0-100
  photoWidth: number; // Percentage 0-100
}

// For html2canvas global availability
declare global {
  interface Window {
    html2canvas: (element: HTMLElement, options?: any) => Promise<HTMLCanvasElement>;
  }
}

import React, { useState, useRef } from 'react';
import { AppMode, PosterData, TemplateStyle, LayoutType, TextEffect } from './types';
import { DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, SUPPORTED_LANGUAGES } from './constants';
import { generateBackground } from './services/geminiService';
import PosterPreview from './components/PosterPreview';
import EditorPanel from './components/EditorPanel';
import { Download, Share2, BookOpen, Calendar, AlertTriangle, Image as ImageIcon, Upload, ChevronRight, ChevronLeft, Sparkles, Languages, Wand2, Cross } from 'lucide-react';

const App: React.FC = () => {
  const posterRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadField, setActiveUploadField] = useState<keyof PosterData | null>(null);
  const [isGeneratingBg, setIsGeneratingBg] = useState(false);

  // Initial State
  const [data, setData] = useState<PosterData>({
    mode: AppMode.VERSE,
    verseReference: "John 3:16",
    verseReferenceEnglish: "John 3:16", // Initialize English Reference
    verseText: "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.",
    eventTitle: "Sunday Service",
    eventDetails: "Sunday, 9:00 AM\nMain Sanctuary\nPastor John Doe",
    language: "English",
    interfaceLanguage: "en", // Default UI Language
    template: TemplateStyle.NATURE,
    layout: LayoutType.RIGHT_CORNER,
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,

    // Flexible Layout Defaults (Centered, 80% width, 1.0 scale)
    textPosition: { x: 50, y: 50 },
    textWidth: 80,
    textScale: 1.0, 

    // Movable Assets Defaults
    logoPosition: { x: 10, y: 10 },
    logoWidth: 16,
    photoPosition: { x: 90, y: 10 },
    photoWidth: 24,
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Layout Cycling Logic - Now defines positions
  const layouts = [
    { 
        id: LayoutType.RIGHT_CORNER, 
        label: 'Corner R',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 85, y: 15 }, // Top Right
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.LEFT_CORNER, 
        label: 'Corner L',
        presets: {
            logoPosition: { x: 90, y: 10 },
            photoPosition: { x: 15, y: 15 }, // Top Left
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.BOTTOM_MIDDLE, 
        label: 'Bottom',
        presets: {
            logoPosition: { x: 10, y: 88 },
            photoPosition: { x: 50, y: 85 }, // Bottom Center
            textPosition: { x: 50, y: 40 } // Text pushed up slightly
        }
    },
    { 
        id: LayoutType.CINEMATIC, 
        label: 'Cinematic',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 90, y: 10 },
            textPosition: { x: 50, y: 70 } // Text lower
        }
    },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const applyLayout = (index: number) => {
    const layout = layouts[index];
    updateData({ 
        layout: layout.id,
        logoPosition: layout.presets.logoPosition,
        photoPosition: layout.presets.photoPosition,
        textPosition: layout.presets.textPosition,
    });
  };

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    applyLayout(nextIndex);
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    applyLayout(prevIndex);
  };

  // File Upload Logic
  const triggerUpload = (field: keyof PosterData) => {
    setActiveUploadField(field);
    if (fileInputRef.current) {
      fileInputRef.current.value = ""; // Reset
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUploadField) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          updateData({ [activeUploadField]: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // AI Background Generation
  const handleAiBackgroundGen = async () => {
    if (!process.env.API_KEY) {
        alert("Please configure your API Key to use AI features.");
        return;
    }

    setIsGeneratingBg(true);
    // Pass the verse text (or event title) as context so the AI generates something relatable
    // The service currently takes style, but we can assume the style prompt inside uses the template name
    const bgUrl = await generateBackground(data.template); 

    if (bgUrl) {
      updateData({ backgroundImageUrl: bgUrl });
    } else {
      alert("Failed to generate background. Please try again.");
    }
    setIsGeneratingBg(false);
  };

  const handleDownload = async () => {
    if (posterRef.current && window.html2canvas) {
      try {
        // Use a small timeout to ensure images are loaded if they were just swapped
        setTimeout(async () => {
            const canvas = await window.html2canvas(posterRef.current!, {
                useCORS: true, // Important for external images
                scale: 2, // Higher quality
                backgroundColor: null,
            });

            const link = document.createElement('a');
            link.download = `gracelens-${data.mode.toLowerCase()}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        }, 100);
      } catch (err) {
        console.error("Download failed", err);
        alert("Could not download image. Please try again.");
      }
    } else {
        alert("Download library not loaded yet.");
    }
  };

  const handleShare = () => {
    if (navigator.share) {
        alert("On a mobile device, this would open the share sheet. Generate the image first to share properly!");
    } else {
        alert("Share feature is available on mobile devices.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileChange} 
      />

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-2xl mx-auto px-4 sm:px-6 h-auto py-3 flex flex-col sm:flex-row items-center justify-between gap-3">

          {/* Futuristic Logo */}
          <div className="flex items-center gap-3 group cursor-pointer self-start sm:self-auto">
             <div className="relative w-10 h-10 flex items-center justify-center">
                <div className="absolute inset-0 bg-cyan-500 blur-lg opacity-20 group-hover:opacity-40 transition-opacity rounded-full"></div>
                <div className="relative bg-gradient-to-br from-slate-900 to-slate-800 rounded-xl p-2 shadow-lg ring-1 ring-white/10 group-hover:ring-cyan-400/50 transition-all flex items-center justify-center">
                   {/* Updated Icon to Cross */}
                   <Cross className="text-cyan-400 w-full h-full" />
                </div>
                <div className="absolute -top-1 -right-1">
                    <Sparkles size={12} className="text-purple-500 fill-purple-500 animate-pulse" />
                </div>
             </div>
             <div className="flex flex-col">
                <h1 className="text-2xl font-bold tracking-tight" style={{ fontFamily: "'Orbitron', sans-serif" }}>
                  <span className="bg-clip-text text-transparent bg-gradient-to-r from-cyan-500 via-blue-600 to-purple-600">
                    GraceLens
                  </span>
                </h1>
                {/* Updated Subtitle */}
                <span className="text-[10px] font-bold tracking-[0.2em] text-slate-400 uppercase -mt-1 pl-0.5">
                    CHRISTIAN POSTER APP
                </span>
             </div>
          </div>

          <div className="flex items-center gap-3 self-end sm:self-auto">
             {/* LANGUAGE SELECTION DROPDOWN */}
             <div className="relative group">
                <div className="flex items-center gap-1.5 bg-slate-100 px-3 py-1.5 rounded-lg cursor-pointer border border-slate-200 hover:bg-slate-50 hover:border-blue-300 transition-all">
                   <Languages size={14} className="text-slate-500"/>
                   <span className="text-xs font-bold text-slate-700">Selection</span>
                   <select 
                      value={data.interfaceLanguage}
                      onChange={(e) => updateData({ interfaceLanguage: e.target.value, language: e.target.options[e.target.selectedIndex].text })}
                      className="absolute inset-0 opacity-0 cursor-pointer"
                   >
                      {SUPPORTED_LANGUAGES.map(lang => (
                         <option key={lang.code} value={lang.code}>{lang.name}</option>
                      ))}
                   </select>
                   <span className="text-[10px] bg-slate-200 px-1.5 rounded text-slate-600 font-mono ml-1">{data.interfaceLanguage.toUpperCase()}</span>
                </div>
             </div>

             {/* Tabs: High Contrast Style */}
             <nav className="flex bg-slate-100/80 p-1.5 rounded-xl shadow-inner border border-slate-200/50">
                <button 
                  onClick={() => switchMode(AppMode.VERSE)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.VERSE ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <BookOpen size={14}/> Verse
                </button>
                <button 
                  onClick={() => switchMode(AppMode.EVENT)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.EVENT ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <Calendar size={14}/> Event
                </button>
             </nav>
          </div>
        </div>
      </header>

      {/* Main Content - Centered Single Column */}
      <main className="flex-1 w-full max-w-2xl mx-auto px-4 py-8 flex flex-col items-center gap-8">

        {!process.env.API_KEY && (
           <div className="w-full bg-amber-50 border-l-4 border-amber-500 p-4 rounded-xl flex items-start gap-3 shadow-sm">
              <AlertTriangle className="text-amber-500 mt-0.5" />
              <div>
                  <h3 className="font-bold text-amber-800">API Key Missing</h3>
                  <p className="text-amber-700 text-sm">Please set your <code className="bg-amber-100 px-1 rounded">process.env.API_KEY</code> to use the AI translation and background generation features.</p>
              </div>
           </div>
        )}

        {/* 1. Poster Preview with Side Arrow Navigation */}
        <div className="relative w-fit group select-none">

            {/* Left Arrow */}
            <button 
                onClick={prevLayout}
                className="absolute -left-4 md:-left-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                title="Previous Layout"
            >
                <ChevronLeft size={24} className="group-hover/btn:-translate-x-0.5 transition-transform" />
            </button>

            {/* Poster Container */}
            <div className="bg-white p-2 rounded-[2rem] shadow-2xl shadow-slate-200 border-4 border-white relative ring-1 ring-slate-100">
                {/* Background Glow */}
                <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 to-purple-500/10 blur-3xl rounded-full transform scale-110 z-0 pointer-events-none"></div>

                <div className="relative z-10 rounded-3xl overflow-hidden">
                    <PosterPreview 
                        data={data} 
                        ref={posterRef} 
                        onTriggerUpload={triggerUpload} 
                        // We can pass a callback to update state from the preview
                        onUpdateData={updateData}
                    />
                </div>
            </div>

            {/* Right Arrow */}
            <button 
                onClick={nextLayout}
                className="absolute -right-4 md:-right-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                title="Next Layout"
            >
                <ChevronRight size={24} className="group-hover/btn:translate-x-0.5 transition-transform" />
            </button>

            {/* Layout Indicator */}
            <div className="absolute -bottom-10 left-0 right-0 flex justify-center items-center gap-3">
                 <div className="bg-slate-900/5 backdrop-blur-sm px-4 py-1.5 rounded-full border border-slate-200/50 flex items-center gap-2">
                    <span className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Layout:</span>
                    <span className="text-xs font-bold text-slate-800">
                        {layouts[currentLayoutIndex].label}
                    </span>
                 </div>
                 <div className="flex gap-1.5">
                    {layouts.map((l, i) => (
                        <div key={l.id} className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${i === currentLayoutIndex ? 'bg-blue-600 w-4' : 'bg-slate-300'}`} />
                    ))}
                 </div>
            </div>
        </div>

        {/* Spacer for layout indicator */}
        <div className="h-6"></div>

        {/* 2. Action Buttons (New Layout) */}
        <div className="w-full flex flex-col gap-3">

            {/* Main Actions Row: Download | Background | Share */}
            <div className="flex gap-3 w-full">

                {/* Download Button - Dark */}
                <button 
                    onClick={handleDownload}
                    className="flex-1 bg-slate-900 text-white py-3.5 rounded-2xl font-bold shadow-lg shadow-slate-200 hover:bg-black hover:scale-[1.01] active:scale-[0.99] transition-all flex justify-center items-center gap-2"
                >
                    <Download size={20} /> Download
                </button>

                {/* Background Upload Button - Light Blue */}
                <button 
                    onClick={() => triggerUpload('backgroundImageUrl')}
                    className="flex-1 bg-indigo-50 text-indigo-600 border border-indigo-100 py-3.5 rounded-2xl font-bold hover:bg-indigo-100 transition-all flex justify-center items-center gap-2"
                >
                    <ImageIcon size={20} /> Background
                </button>

                {/* Share Button - White Outline */}
                <button 
                    onClick={handleShare}
                    className="flex-1 bg-white text-slate-700 border-2 border-slate-100 py-3.5 rounded-2xl font-bold hover:bg-slate-50 hover:border-slate-200 transition-all flex justify-center items-center gap-2"
                >
                    <Share2 size={20} /> Share
                </button>
            </div>

            {/* Bottom Row: AI Generator - Gradient Full Width */}
            <button 
                onClick={handleAiBackgroundGen}
                disabled={isGeneratingBg}
                className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-200/50 hover:shadow-xl hover:shadow-blue-300/50 hover:scale-[1.01] active:scale-[0.99] transition-all flex justify-center items-center gap-2.5 disabled:opacity-70 disabled:cursor-not-allowed group relative overflow-hidden"
            >
                {/* Shimmer Effect */}
                <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:animate-shimmer skew-x-12"></div>

                {isGeneratingBg ? (
                    <>
                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                        Generating Relatable Background...
                    </>
                ) : (
                    <>
                        <Wand2 size={20} className="text-blue-100" /> 
                        Generate AI Background 
                        <span className="text-[10px] bg-white/20 px-1.5 py-0.5 rounded text-blue-50 ml-1">Beta</span>
                    </>
                )}
            </button>
        </div>

        {/* 5. Editor Panel */}
        <div className="w-full">
            <EditorPanel data={data} onUpdate={updateData} />
        </div>

      </main>

      <footer className="bg-white border-t border-slate-200 mt-12 py-8">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <p className="text-slate-400 text-sm font-medium">&copy; {new Date().getFullYear()} GraceLens. AI-Powered Christian Design.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { forwardRef, useMemo, useState, useEffect } from 'react';
import { PosterData, AppMode, TemplateStyle, LayoutType, TextEffect } from '../types';
import { Upload, Camera, Image as ImageIcon, Move, ArrowRightLeft, Maximize } from 'lucide-react';

interface Props {
  data: PosterData;
  scale?: number;
  onTriggerUpload?: (field: keyof PosterData) => void;
  onUpdateData?: (newData: Partial<PosterData>) => void;
}

// Extracted DraggableElement to fix TS error and improve performance
interface DraggableElementProps {
    position: { x: number, y: number };
    children: React.ReactNode;
    width?: number;
    resizable?: boolean;
    isActive: boolean;
    onMouseDown: (e: React.MouseEvent, action: 'drag' | 'resize' | 'scale') => void;
}

const DraggableElement: React.FC<DraggableElementProps> = ({ 
    position, 
    children, 
    width, 
    resizable = false,
    isActive,
    onMouseDown
}) => (
  <div 
      className="absolute z-50 group/element flex flex-col items-center justify-center cursor-move"
      style={{
          left: `${position.x}%`,
          top: `${position.y}%`,
          width: width ? `${width}%` : 'auto',
          transform: 'translate(-50%, -50%)',
          userSelect: 'none'
      }}
      onMouseDown={(e) => onMouseDown(e, 'drag')}
  >
      {/* Border indicating selected/hover */}
      <div className={`absolute -inset-2 border-2 border-dashed border-blue-400 rounded-lg pointer-events-none transition-opacity duration-200 ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}></div>

      {/* Move Handle (Visual) */}
      <div className={`absolute -top-6 left-1/2 -translate-x-1/2 bg-blue-500 text-white px-2 py-0.5 rounded-t-md text-[9px] font-bold uppercase flex items-center gap-1 transition-opacity duration-200 pointer-events-none ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}>
          <Move size={10} /> Move
      </div>

      {/* Resize Handles */}
      {resizable && (
          <>
              {/* Width Resize Handle (Right) */}
              <div 
                  className={`absolute -right-4 top-1/2 -translate-y-1/2 w-6 h-10 bg-blue-500 rounded-md cursor-ew-resize flex items-center justify-center shadow-lg transition-opacity duration-200 ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}
                  onMouseDown={(e) => onMouseDown(e, 'resize')}
                  title="Drag to resize width"
              >
                  <ArrowRightLeft size={14} className="text-white" />
              </div>

              {/* Scale/Size Handle (Bottom Right) */}
              <div 
                  className={`absolute -right-4 -bottom-4 w-8 h-8 bg-blue-600 rounded-full cursor-nwse-resize flex items-center justify-center shadow-lg transition-opacity duration-200 ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}
                  onMouseDown={(e) => onMouseDown(e, 'scale')}
                  title="Drag to scale"
              >
                  <Maximize size={14} className="text-white" />
              </div>
          </>
      )}

      {children}
  </div>
);

const PosterPreview = forwardRef<HTMLDivElement, Props>(({ data, scale = 1, onTriggerUpload, onUpdateData }, ref) => {
  // Styles based on template
  const getTemplateStyles = () => {
    switch (data.template) {
      case TemplateStyle.MINIMAL:
        return { overlay: "bg-white/90", textBase: "text-slate-900" };
      case TemplateStyle.NATURE:
        return { overlay: "bg-black/20", textBase: "text-white" };
      case TemplateStyle.ABSTRACT:
        return { overlay: "bg-purple-900/40", textBase: "text-white" };
      case TemplateStyle.GOLDEN:
        return { overlay: "bg-black/60", textBase: "text-amber-100" };
      case TemplateStyle.GRADIENT:
        return { overlay: "bg-gradient-to-t from-blue-900/80 via-transparent to-transparent", textBase: "text-white" };
      default:
        return { overlay: "bg-black/40", textBase: "text-white" };
    }
  };

  const styles = getTemplateStyles();

  // Helper to generate text styles based on Effect
  const getTextEffectStyles = (effect: TextEffect, color: string): React.CSSProperties => {
    const base: React.CSSProperties = {
      fontFamily: data.fontFamily,
      color: color,
    };

    if (color.startsWith('linear-gradient')) {
        base.backgroundImage = color;
        base.backgroundClip = 'text';
        base.WebkitBackgroundClip = 'text';
        base.WebkitTextFillColor = 'transparent';
        base.color = 'transparent'; 
    }

    switch (effect) {
      case TextEffect.SHADOW_SOFT:
        return { ...base, textShadow: '0 4px 8px rgba(0,0,0,0.5)' };
      case TextEffect.SHADOW_HARD:
        return { ...base, textShadow: '3px 3px 0px rgba(0,0,0,1)' };
      case TextEffect.OUTLINE:
        return { 
          ...base, 
          WebkitTextStroke: `1px ${color === '#000000' ? '#ffffff' : '#000000'}`, 
          textShadow: 'none' 
        };
      case TextEffect.NEON:
        return { 
          ...base, 
          textShadow: `0 0 5px #fff, 0 0 10px ${color}, 0 0 20px ${color}` 
        };
      case TextEffect.RETRO:
        return { ...base, textShadow: '2px 2px 0px #d1d5db, 4px 4px 0px #9ca3af' };
      case TextEffect.ELEGANT:
        return { ...base, textShadow: '0px 1px 0px rgba(255,255,255,0.4), 0px -1px 0px rgba(0,0,0,0.4)' };
      case TextEffect.GLITCH:
        return { ...base, textShadow: '2px 0 rgba(255,0,0,0.5), -2px 0 rgba(0,0,255,0.5)' };
      case TextEffect.NONE:
      default:
        return base;
    }
  };

  const textStyle = getTextEffectStyles(data.textEffect, data.textColor);
  const accentStyle: React.CSSProperties = {
    fontFamily: data.fontFamily,
    color: data.textColor.startsWith('linear-gradient') ? '#ffffff' : data.textColor,
    opacity: 0.9,
    textShadow: '0px 1px 2px rgba(0,0,0,0.5)',
  };

  const baseWidth = 400;
  const baseHeight = 500;

  // --- Intelligent Highlighting Logic ---
  const highlightedKeywords = useMemo(() => {
    if (data.mode !== AppMode.VERSE || !data.verseText) return new Set<string>();

    const text = data.verseText;
    const commonStopWords = new Set(['the', 'and', 'that', 'have', 'for', 'not', 'with', 'you', 'this', 'but', 'his', 'from', 'they', 'we', 'say', 'her', 'she', 'will', 'an', 'one', 'would', 'there', 'their', 'what', 'so', 'up', 'out', 'if', 'about', 'who', 'get', 'which', 'go', 'me', 'when', 'make', 'can', 'like', 'time', 'no', 'just', 'him', 'know', 'take', 'people', 'into', 'year', 'your', 'good', 'some', 'could', 'them', 'see', 'other', 'than', 'then', 'now', 'look', 'only', 'come', 'its', 'over', 'think', 'also', 'back', 'after', 'use', 'two', 'how', 'our', 'work', 'first', 'well', 'way', 'even', 'new', 'want', 'because', 'any', 'these', 'give', 'day', 'most', 'us', 'are', 'is', 'was', 'be', 'been', 'being']);
    const christianKeywords = new Set(['god', 'jesus', 'lord', 'christ', 'holy', 'spirit', 'father', 'faith', 'love', 'grace', 'mercy', 'peace', 'joy', 'hope', 'life', 'light', 'truth', 'heart', 'soul', 'pray', 'bless', 'glory', 'saved', 'world', 'son', 'heaven', 'believe', 'eternal', 'word', 'king', 'cross', 'blood', 'lamb', 'shepherd']);
    const words = text.split(/[\s,.!?;:"'-]+/); 
    const candidates = words.map((w, i) => {
        const clean = w.toLowerCase();
        let score = 0;
        if (clean.length < 3) return { word: clean, score: 0 };
        if (christianKeywords.has(clean)) score += 20;
        if (!commonStopWords.has(clean)) score += clean.length;
        if (w.length > 0 && w[0] === w[0].toUpperCase() && /^[A-Z]/.test(w)) score += 5;
        return { word: clean, score };
    });
    const sorted = candidates.filter(c => c.score > 0).sort((a, b) => b.score - a.score);
    const topWords = new Set<string>();
    for (const c of sorted) {
        if (topWords.size >= 3) break;
        topWords.add(c.word);
    }
    return topWords;
  }, [data.verseText, data.mode]);

  const highlightStyle = useMemo(() => {
    const isBaseScript = data.fontFamily.includes('cursive') || data.fontFamily.includes('Vibes') || data.fontFamily.includes('Script') || data.fontFamily.includes('Pacifico');
    const font = isBaseScript ? "'Cinzel', serif" : "'Great Vibes', cursive";
    const isDarkText = data.textColor === '#000000' || data.textColor.startsWith('#0') || data.textColor.startsWith('#1') || data.textColor.startsWith('#3');
    const color = isDarkText ? '#B45309' : '#FCD34D';
    return {
        fontFamily: font,
        color: color,
        fontWeight: isBaseScript ? 'bold' : 'normal',
        textShadow: isDarkText ? 'none' : '0 0 10px rgba(252, 211, 77, 0.5)',
    };
  }, [data.fontFamily, data.textColor]);

  // --- Generic Draggable Logic ---
  const [activeDragId, setActiveDragId] = useState<'text' | 'logo' | 'photo' | null>(null);
  const [dragAction, setDragAction] = useState<'drag' | 'resize' | 'scale'>('drag');
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // Track initial values on drag start to calculate deltas accurately
  const [initialScale, setInitialScale] = useState(1);
  const [initialWidth, setInitialWidth] = useState(0);

  const handleMouseDown = (e: React.MouseEvent, id: 'text' | 'logo' | 'photo', action: 'drag' | 'resize' | 'scale') => {
    e.stopPropagation();
    setActiveDragId(id);
    setDragAction(action);
    setDragStart({ x: e.clientX, y: e.clientY });

    // Capture initial values depending on what is being resized
    if (action === 'scale' && id === 'text') {
        setInitialScale(data.textScale || 1);
    }

    // For resizing Width
    if (action === 'resize' || (action === 'scale' && id !== 'text')) {
        if (id === 'text') setInitialWidth(data.textWidth);
        if (id === 'logo') setInitialWidth(data.logoWidth || 16);
        if (id === 'photo') setInitialWidth(data.photoWidth || 24);
    }
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!activeDragId) return;
      if (!onUpdateData) return;

      const deltaX = (e.clientX - dragStart.x) / scale;
      const deltaY = (e.clientY - dragStart.y) / scale;

      // Convert pixels to percentage relative to canvas
      const deltaXPercent = (deltaX / baseWidth) * 100;
      const deltaYPercent = (deltaY / baseHeight) * 100;

      if (activeDragId === 'text') {
          if (dragAction === 'drag') {
            onUpdateData({
              textPosition: {
                x: Math.max(0, Math.min(100, data.textPosition.x + deltaXPercent)),
                y: Math.max(0, Math.min(100, data.textPosition.y + deltaYPercent)),
              }
            });
          } else if (dragAction === 'resize') {
            onUpdateData({
                textWidth: Math.max(20, Math.min(100, initialWidth + deltaXPercent))
            });
          } else if (dragAction === 'scale') {
             // For Text, Scale affects font size
             const scaleDelta = (deltaX + deltaY) * 0.005; 
             const newScale = Math.max(0.5, Math.min(3.0, initialScale + scaleDelta));
             onUpdateData({ textScale: newScale });
          }
      } else if (activeDragId === 'logo') {
          if (dragAction === 'drag') {
             onUpdateData({
                logoPosition: {
                    x: Math.max(0, Math.min(100, (data.logoPosition?.x || 10) + deltaXPercent)),
                    y: Math.max(0, Math.min(100, (data.logoPosition?.y || 10) + deltaYPercent))
                }
            });
          } else if (dragAction === 'resize' || dragAction === 'scale') {
             // For Logo, Scale/Resize affects Width
             onUpdateData({
                logoWidth: Math.max(5, Math.min(60, initialWidth + deltaXPercent))
             });
          }
      } else if (activeDragId === 'photo') {
          if (dragAction === 'drag') {
             onUpdateData({
                photoPosition: {
                    x: Math.max(0, Math.min(100, (data.photoPosition?.x || 90) + deltaXPercent)),
                    y: Math.max(0, Math.min(100, (data.photoPosition?.y || 10) + deltaYPercent))
                }
            });
          } else if (dragAction === 'resize' || dragAction === 'scale') {
             // For Photo, Scale/Resize affects Width
             onUpdateData({
                photoWidth: Math.max(10, Math.min(90, initialWidth + deltaXPercent))
             });
          }
      }

      if (dragAction === 'drag') {
          // Continuous drag update logic requires resetting start for smooth movement if we were adding delta directly to current pos.
          // BUT here we add delta to the *initial* pos if we captured it, OR we add delta to current and reset start.
          // Current logic: data.pos + delta. 
          // To prevent compounding error with rapid updates, typical React drag pattern resets start on every move 
          // so delta is always small incremental.
          setDragStart({ x: e.clientX, y: e.clientY });
      }
      // For Resize/Scale, we rely on `initialWidth` + `totalDelta` (calculated from original dragStart), 
      // so we DO NOT reset dragStart for resize actions to keep the math consistent relative to initial click.
    };

    const handleMouseUp = () => {
      setActiveDragId(null);
    };

    if (activeDragId) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [activeDragId, dragAction, dragStart, initialScale, initialWidth, data, onUpdateData, scale]);


  // --- Components ---
  const HighlightedVerseText = () => {
    if (!data.verseText) return null;
    const parts = data.verseText.split(/(\s+|[.,!?;:"'-]+)/g);
    const fontSizeVal = `${(1.875 * (data.textScale || 1)).toFixed(3)}rem`;

    return (
        <p className="leading-snug italic px-4" style={{ ...textStyle, fontSize: fontSizeVal }}>
            "
            {parts.map((part, i) => {
                const clean = part.toLowerCase().replace(/[^a-z0-9]/g, '');
                const isHighlight = clean.length > 2 && highlightedKeywords.has(clean);
                if (isHighlight) {
                    return (
                        <span key={i} style={{ ...highlightStyle, display: 'inline-block', transform: 'scale(1.1)', fontSize: '1.25em' }}>
                            {part}
                        </span>
                    );
                }
                return <span key={i}>{part}</span>;
            })}
            "
        </p>
    );
  };

  const UploadTrigger = ({ field, children, className = "" }: { field: keyof PosterData, children?: React.ReactNode, className?: string }) => (
    <div 
      className={`relative group cursor-pointer ${className}`}
      onClick={(e) => { e.stopPropagation(); onTriggerUpload?.(field); }}
      title={`Click to upload ${field === 'backgroundImageUrl' ? 'Background' : field === 'uploadedPhotoUrl' ? 'Photo' : 'Logo'}`}
    >
      {children}
      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-inherit z-50 pointer-events-none">
        <Upload size={16} className="text-white" />
      </div>
    </div>
  );

  const LogoElement = () => (
    <UploadTrigger field="logoUrl" className="inline-block rounded-full overflow-hidden w-full h-full">
      {data.logoUrl ? (
        <img src={data.logoUrl} alt="Logo" className="w-full h-full object-cover rounded-full drop-shadow-md" crossOrigin="anonymous"/>
      ) : (
        <div className="w-full h-full bg-white/20 border-2 border-dashed border-white/50 rounded-full flex items-center justify-center backdrop-blur-sm">
            <span className="text-[10px] text-white font-bold uppercase">Logo</span>
        </div>
      )}
    </UploadTrigger>
  );

  const PhotoElement = ({ className = "" }: { className?: string }) => (
     <UploadTrigger field="uploadedPhotoUrl" className={`w-full h-full ${className}`}>
        {data.uploadedPhotoUrl ? (
            <div className="w-full h-full rounded-[1.5rem] border-4 border-white/30 overflow-hidden shadow-2xl">
                <img src={data.uploadedPhotoUrl} alt="User" className="w-full h-full object-cover" crossOrigin="anonymous"/>
            </div>
        ) : (
            <div className="w-full h-full rounded-[1.5rem] border-4 border-dashed border-white/40 bg-white/10 flex flex-col items-center justify-center text-white/80 backdrop-blur-sm">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1 uppercase">Photo</span>
            </div>
        )}
     </UploadTrigger>
  );

  const TextContent = () => (
    <div className={`flex flex-col gap-4 items-center text-center`}>
         {data.mode === AppMode.VERSE ? (
            <>
              <HighlightedVerseText />
              <div className="h-1 w-12 bg-current opacity-50 rounded-full" style={{ color: data.textColor }}></div>
              <div className="flex flex-col items-center gap-1">
                  <p className="text-lg font-bold uppercase tracking-widest" style={accentStyle}>{data.verseReference}</p>
                  {data.verseReferenceEnglish && data.verseReferenceEnglish !== data.verseReference && (
                      <p className="text-sm font-bold uppercase tracking-widest opacity-80" style={{ ...accentStyle, fontFamily: "'Inter', sans-serif" }}>
                        {data.verseReferenceEnglish}
                      </p>
                  )}
              </div>
            </>
          ) : (
            <>
              <h1 className="text-4xl font-bold leading-tight" style={textStyle}>{data.eventTitle || "Event Title"}</h1>
              <p className="text-lg whitespace-pre-wrap font-light opacity-90" style={textStyle}>{data.eventDetails || "Date • Time • Venue"}</p>
            </>
          )}
    </div>
  );

  const renderOverlays = () => {
    switch (data.layout) {
      case LayoutType.CINEMATIC:
        return (
           <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/30 z-0 pointer-events-none"></div>
        );
      default:
        // Generic overlay from template style if needed, can be empty if handled by root style
        return null;
    }
  };

  return (
    <div className="w-full flex justify-center py-4 select-none" style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }}>
      <div 
        ref={ref}
        id="poster-canvas"
        className={`relative bg-slate-200 overflow-hidden shadow-[0_20px_50px_-12px_rgba(0,0,0,0.5)] flex flex-col group/poster`}
        style={{ width: baseWidth, height: baseHeight }}
      >
        {/* Background Image (Click to Upload) */}
        <div 
            className="absolute inset-0 z-0 cursor-pointer"
            onClick={(e) => { e.stopPropagation(); onTriggerUpload?.('backgroundImageUrl'); }}
            title="Click background to change image"
        >
            {data.backgroundImageUrl ? (
            <img 
                src={data.backgroundImageUrl} 
                alt="Background" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                crossOrigin="anonymous"
            />
            ) : (
            <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                <ImageIcon className="text-slate-600" size={48} />
            </div>
            )}
        </div>

        {/* Overlay for non-cinematic modes (Template Color Overlay) */}
        {data.layout !== LayoutType.CINEMATIC && (
          <div className={`absolute inset-0 z-0 pointer-events-none ${styles.overlay}`}></div>
        )}

        {/* Layout Specific Overlays (e.g. Cinematic Gradient) */}
        {renderOverlays()}

        {/* --- MOVABLE LAYERS --- */}

        {/* 1. Logo */}
        <DraggableElement 
            position={data.logoPosition || {x: 10, y: 10}}
            width={data.logoWidth || 16}
            resizable={true}
            isActive={activeDragId === 'logo'}
            onMouseDown={(e, action) => handleMouseDown(e, 'logo', action)}
        >
             <div className="flex flex-col items-center w-full aspect-square">
                <LogoElement />
                {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90 mt-1 shadow-black drop-shadow-md">{data.customName}</span>}
             </div>
        </DraggableElement>

        {/* 2. Photo */}
        <DraggableElement 
            position={data.photoPosition || {x: 90, y: 10}}
            width={data.photoWidth || 24}
            resizable={true}
            isActive={activeDragId === 'photo'}
            onMouseDown={(e, action) => handleMouseDown(e, 'photo', action)}
        >
             <div className="w-full aspect-square">
                <PhotoElement />
             </div>
        </DraggableElement>

        {/* 3. Text (With Resize/Scale options) */}
        <DraggableElement 
            position={data.textPosition} 
            width={data.textWidth} 
            resizable={true}
            isActive={activeDragId === 'text'}
            onMouseDown={(e, action) => handleMouseDown(e, 'text', action)}
        >
            <TextContent />
        </DraggableElement>

      </div>
    </div>
  );
});

PosterPreview.displayName = 'PosterPreview';

export default PosterPreview;

export enum AppMode {
  VERSE = 'VERSE',
  EVENT = 'EVENT'
}

export enum TemplateStyle {
  MINIMAL = 'Minimal',
  NATURE = 'Nature',
  ABSTRACT = 'Abstract',
  GOLDEN = 'Golden',
  GRADIENT = 'Gradient'
}

export enum LayoutType {
  RIGHT_CORNER = 'Right Corner',
  LEFT_CORNER = 'Left Corner',
  BOTTOM_MIDDLE = 'Bottom Middle',
  CINEMATIC = 'Cinematic'
}

export enum PosterAspect {
  PORTRAIT = 'Portrait',
  SQUARE = 'Square',
  LANDSCAPE = 'Desktop'
}

export enum TextEffect {
  NONE = 'none',
  SHADOW_SOFT = 'shadow-soft',
  SHADOW_HARD = 'shadow-hard',
  OUTLINE = 'outline',
  NEON = 'neon',
  RETRO = 'retro',
  ELEGANT = 'elegant',
  GLITCH = 'glitch'
}

export interface PosterData {
  mode: AppMode;
  // Verse Mode
  verseReference: string; // The Localized/Target Language Reference
  verseReferenceEnglish: string; // The English Reference
  verseText: string;
  // Event Mode
  eventTitle: string;
  eventDetails: string; // Date, Time, Venue
  // Shared
  language: string; // Target language for translation
  interfaceLanguage: string; // UI Language
  template: TemplateStyle;
  layout: LayoutType;
  posterAspect: PosterAspect; // New property for size selection
  backgroundImageUrl: string | null;
  uploadedPhotoUrl: string | null;
  logoUrl: string | null;
  customName: string; // Family name / Church name

  // Customization
  fontFamily: string;
  textColor: string;
  textEffect: TextEffect;

  // Flexible Layout
  textPosition: { x: number; y: number }; // Percentage 0-100
  textWidth: number; // Percentage 0-100
  textScale: number; // Font size multiplier (1.0 = base size)

  // Movable Assets
  logoPosition: { x: number; y: number }; // Percentage 0-100
  logoWidth: number; // Percentage 0-100
  photoPosition: { x: number; y: number }; // Percentage 0-100
  photoWidth: number; // Percentage 0-100
}

