import React, { forwardRef, useMemo, useState, useEffect } from 'react';
import { PosterData, AppMode, TemplateStyle, LayoutType, TextEffect } from '../types';
import { POSTER_DIMENSIONS } from '../constants';
import { Upload, Camera, Image as ImageIcon, Move, ArrowRightLeft, Maximize } from 'lucide-react';

interface Props {
  data: PosterData;
  scale?: number;
  onTriggerUpload?: (field: keyof PosterData) => void;
  onUpdateData?: (newData: Partial<PosterData>) => void;
}

// Extracted DraggableElement to fix TS error and improve performance
interface DraggableElementProps {
    position: { x: number, y: number };
    children: React.ReactNode;
    width?: number;
    resizable?: boolean;
    isActive: boolean;
    onMouseDown: (e: React.MouseEvent, action: 'drag' | 'resize' | 'scale') => void;
}

const DraggableElement: React.FC<DraggableElementProps> = ({ 
    position, 
    children, 
    width, 
    resizable = false,
    isActive,
    onMouseDown
}) => (
  <div 
      className="absolute z-50 group/element flex flex-col items-center justify-center cursor-move"
      style={{
          left: `${position.x}%`,
          top: `${position.y}%`,
          width: width ? `${width}%` : 'auto',
          transform: 'translate(-50%, -50%)',
          userSelect: 'none'
      }}
      onMouseDown={(e) => onMouseDown(e, 'drag')}
  >
      {/* Border indicating selected/hover */}
      <div className={`absolute -inset-2 border-2 border-dashed border-blue-400 rounded-lg pointer-events-none transition-opacity duration-200 ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}></div>

      {/* Move Handle (Visual) */}
      <div className={`absolute -top-6 left-1/2 -translate-x-1/2 bg-blue-500 text-white px-2 py-0.5 rounded-t-md text-[9px] font-bold uppercase flex items-center gap-1 transition-opacity duration-200 pointer-events-none ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}>
          <Move size={10} /> Move
      </div>

      {/* Resize Handles */}
      {resizable && (
          <>
              {/* Width Resize Handle (Right) */}
              <div 
                  className={`absolute -right-4 top-1/2 -translate-y-1/2 w-6 h-10 bg-blue-500 rounded-md cursor-ew-resize flex items-center justify-center shadow-lg transition-opacity duration-200 ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}
                  onMouseDown={(e) => onMouseDown(e, 'resize')}
                  title="Drag to resize width"
              >
                  <ArrowRightLeft size={14} className="text-white" />
              </div>

              {/* Scale/Size Handle (Bottom Right) */}
              <div 
                  className={`absolute -right-4 -bottom-4 w-8 h-8 bg-blue-600 rounded-full cursor-nwse-resize flex items-center justify-center shadow-lg transition-opacity duration-200 ${isActive ? 'opacity-100' : 'opacity-0 group-hover/element:opacity-100'}`}
                  onMouseDown={(e) => onMouseDown(e, 'scale')}
                  title="Drag to scale"
              >
                  <Maximize size={14} className="text-white" />
              </div>
          </>
      )}

      {children}
  </div>
);

const PosterPreview = forwardRef<HTMLDivElement, Props>(({ data, scale = 1, onTriggerUpload, onUpdateData }, ref) => {
  // Styles based on template
  const getTemplateStyles = () => {
    switch (data.template) {
      case TemplateStyle.MINIMAL:
        return { overlay: "bg-white/90", textBase: "text-slate-900" };
      case TemplateStyle.NATURE:
        return { overlay: "bg-black/20", textBase: "text-white" };
      case TemplateStyle.ABSTRACT:
        return { overlay: "bg-purple-900/40", textBase: "text-white" };
      case TemplateStyle.GOLDEN:
        return { overlay: "bg-black/60", textBase: "text-amber-100" };
      case TemplateStyle.GRADIENT:
        return { overlay: "bg-gradient-to-t from-blue-900/80 via-transparent to-transparent", textBase: "text-white" };
      default:
        return { overlay: "bg-black/40", textBase: "text-white" };
    }
  };

  const styles = getTemplateStyles();

  // Helper to generate text styles based on Effect
  const getTextEffectStyles = (effect: TextEffect, color: string): React.CSSProperties => {
    const base: React.CSSProperties = {
      fontFamily: data.fontFamily,
      color: color,
    };

    if (color.startsWith('linear-gradient')) {
        base.backgroundImage = color;
        base.backgroundClip = 'text';
        base.WebkitBackgroundClip = 'text';
        base.WebkitTextFillColor = 'transparent';
        base.color = 'transparent'; 
    }

    switch (effect) {
      case TextEffect.SHADOW_SOFT:
        return { ...base, textShadow: '0 4px 8px rgba(0,0,0,0.5)' };
      case TextEffect.SHADOW_HARD:
        return { ...base, textShadow: '3px 3px 0px rgba(0,0,0,1)' };
      case TextEffect.OUTLINE:
        return { 
          ...base, 
          WebkitTextStroke: `1px ${color === '#000000' ? '#ffffff' : '#000000'}`, 
          textShadow: 'none' 
        };
      case TextEffect.NEON:
        return { 
          ...base, 
          textShadow: `0 0 5px #fff, 0 0 10px ${color}, 0 0 20px ${color}` 
        };
      case TextEffect.RETRO:
        return { ...base, textShadow: '2px 2px 0 #d1d5db, 4px 4px 0 #9ca3af' };
      case TextEffect.ELEGANT:
        return { ...base, textShadow: '0px 1px 0px rgba(255,255,255,0.4), 0px -1px 0px rgba(0,0,0,0.4)' };
      case TextEffect.GLITCH:
        return { ...base, textShadow: '2px 0 rgba(255,0,0,0.5), -2px 0 rgba(0,0,255,0.5)' };
      case TextEffect.NONE:
      default:
        return base;
    }
  };

  const textStyle = getTextEffectStyles(data.textEffect, data.textColor);
  const accentStyle: React.CSSProperties = {
    fontFamily: data.fontFamily,
    color: data.textColor.startsWith('linear-gradient') ? '#ffffff' : data.textColor,
    opacity: 0.9,
    textShadow: '0px 1px 2px rgba(0,0,0,0.5)',
  };

  // Dynamic dimensions based on aspect ratio
  const dimensions = POSTER_DIMENSIONS[data.posterAspect] || { width: 400, height: 500 };
  const baseWidth = dimensions.width;
  const baseHeight = dimensions.height;

  // --- Intelligent Highlighting Logic ---
  const highlightedKeywords = useMemo(() => {
    if (data.mode !== AppMode.VERSE || !data.verseText) return new Set<string>();

    const text = data.verseText;
    const commonStopWords = new Set(['the', 'and', 'that', 'have', 'for', 'not', 'with', 'you', 'this', 'but', 'his', 'from', 'they', 'we', 'say', 'her', 'she', 'will', 'an', 'one', 'would', 'there', 'their', 'what', 'so', 'up', 'out', 'if', 'about', 'who', 'get', 'which', 'go', 'me', 'when', 'make', 'can', 'like', 'time', 'no', 'just', 'him', 'know', 'take', 'people', 'into', 'year', 'your', 'good', 'some', 'could', 'them', 'see', 'other', 'than', 'then', 'now', 'look', 'only', 'come', 'its', 'over', 'think', 'also', 'back', 'after', 'use', 'two', 'how', 'our', 'work', 'first', 'well', 'way', 'even', 'new', 'want', 'because', 'any', 'these', 'give', 'day', 'most', 'us', 'are', 'is', 'was', 'be', 'been', 'being']);
    const christianKeywords = new Set(['god', 'jesus', 'lord', 'christ', 'holy', 'spirit', 'father', 'faith', 'love', 'grace', 'mercy', 'peace', 'joy', 'hope', 'life', 'light', 'truth', 'heart', 'soul', 'pray', 'bless', 'glory', 'saved', 'world', 'son', 'heaven', 'believe', 'eternal', 'word', 'king', 'cross', 'blood', 'lamb', 'shepherd']);
    const words = text.split(/[\s,.!?;:"'-]+/); 
    const candidates = words.map((w, i) => {
        const clean = w.toLowerCase();
        let score = 0;
        if (clean.length < 3) return { word: clean, score: 0 };
        if (christianKeywords.has(clean)) score += 20;
        if (!commonStopWords.has(clean)) score += clean.length;
        if (w.length > 0 && w[0] === w[0].toUpperCase() && /^[A-Z]/.test(w)) score += 5;
        return { word: clean, score };
    });
    const sorted = candidates.filter(c => c.score > 0).sort((a, b) => b.score - a.score);
    const topWords = new Set<string>();
    for (const c of sorted) {
        if (topWords.size >= 3) break;
        topWords.add(c.word);
    }
    return topWords;
  }, [data.verseText, data.mode]);

  const highlightStyle = useMemo(() => {
    const isBaseScript = data.fontFamily.includes('cursive') || data.fontFamily.includes('Vibes') || data.fontFamily.includes('Script') || data.fontFamily.includes('Pacifico');
    const font = isBaseScript ? "'Cinzel', serif" : "'Great Vibes', cursive";
    const isDarkText = data.textColor === '#000000' || data.textColor.startsWith('#0') || data.textColor.startsWith('#1') || data.textColor.startsWith('#3');
    const color = isDarkText ? '#B45309' : '#FCD34D';
    return {
        fontFamily: font,
        color: color,
        fontWeight: isBaseScript ? 'bold' : 'normal',
        textShadow: isDarkText ? 'none' : '0 0 10px rgba(252, 211, 77, 0.5)',
    };
  }, [data.fontFamily, data.textColor]);

  // --- Generic Draggable Logic ---
  const [activeDragId, setActiveDragId] = useState<'text' | 'logo' | 'photo' | null>(null);
  const [dragAction, setDragAction] = useState<'drag' | 'resize' | 'scale'>('drag');
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  // Track initial values on drag start to calculate deltas accurately
  const [initialScale, setInitialScale] = useState(1);
  const [initialWidth, setInitialWidth] = useState(0);

  const handleMouseDown = (e: React.MouseEvent, id: 'text' | 'logo' | 'photo', action: 'drag' | 'resize' | 'scale') => {
    e.stopPropagation();
    setActiveDragId(id);
    setDragAction(action);
    setDragStart({ x: e.clientX, y: e.clientY });

    // Capture initial values depending on what is being resized
    if (action === 'scale' && id === 'text') {
        setInitialScale(data.textScale || 1);
    }

    // For resizing Width
    if (action === 'resize' || (action === 'scale' && id !== 'text')) {
        if (id === 'text') setInitialWidth(data.textWidth);
        if (id === 'logo') setInitialWidth(data.logoWidth || 16);
        if (id === 'photo') setInitialWidth(data.photoWidth || 24);
    }
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!activeDragId) return;
      if (!onUpdateData) return;

      const deltaX = (e.clientX - dragStart.x) / scale;
      const deltaY = (e.clientY - dragStart.y) / scale;

      // Convert pixels to percentage relative to canvas
      const deltaXPercent = (deltaX / baseWidth) * 100;
      const deltaYPercent = (deltaY / baseHeight) * 100;

      if (activeDragId === 'text') {
          if (dragAction === 'drag') {
            onUpdateData({
              textPosition: {
                x: Math.max(0, Math.min(100, data.textPosition.x + deltaXPercent)),
                y: Math.max(0, Math.min(100, data.textPosition.y + deltaYPercent)),
              }
            });
          } else if (dragAction === 'resize') {
            onUpdateData({
                textWidth: Math.max(20, Math.min(100, initialWidth + deltaXPercent))
            });
          } else if (dragAction === 'scale') {
             // For Text, Scale affects font size
             const scaleDelta = (deltaX + deltaY) * 0.005; 
             const newScale = Math.max(0.5, Math.min(3.0, initialScale + scaleDelta));
             onUpdateData({ textScale: newScale });
          }
      } else if (activeDragId === 'logo') {
          if (dragAction === 'drag') {
             onUpdateData({
                logoPosition: {
                    x: Math.max(0, Math.min(100, (data.logoPosition?.x || 10) + deltaXPercent)),
                    y: Math.max(0, Math.min(100, (data.logoPosition?.y || 10) + deltaYPercent))
                }
            });
          } else if (dragAction === 'resize' || dragAction === 'scale') {
             // For Logo, Scale/Resize affects Width
             onUpdateData({
                logoWidth: Math.max(5, Math.min(60, initialWidth + deltaXPercent))
             });
          }
      } else if (activeDragId === 'photo') {
          if (dragAction === 'drag') {
             onUpdateData({
                photoPosition: {
                    x: Math.max(0, Math.min(100, (data.photoPosition?.x || 90) + deltaXPercent)),
                    y: Math.max(0, Math.min(100, (data.photoPosition?.y || 10) + deltaYPercent))
                }
            });
          } else if (dragAction === 'resize' || dragAction === 'scale') {
             // For Photo, Scale/Resize affects Width
             onUpdateData({
                photoWidth: Math.max(10, Math.min(90, initialWidth + deltaXPercent))
             });
          }
      }

      if (dragAction === 'drag') {
          // Continuous drag update logic requires resetting start for smooth movement if we were adding delta directly to current pos.
          // BUT here we add delta to the *initial* pos if we captured it, OR we add delta to current and reset start.
          // Current logic: data.pos + delta. 
          // To prevent compounding error with rapid updates, typical React drag pattern resets start on every move 
          // so delta is always small incremental.
          setDragStart({ x: e.clientX, y: e.clientY });
      }
      // For Resize/Scale, we rely on `initialWidth` + `totalDelta` (calculated from original dragStart), 
      // so we DO NOT reset dragStart for resize actions to keep the math consistent relative to initial click.
    };

    const handleMouseUp = () => {
      setActiveDragId(null);
    };

    if (activeDragId) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [activeDragId, dragAction, dragStart, initialScale, initialWidth, data, onUpdateData, scale, baseWidth, baseHeight]);


  // --- Components ---
  const HighlightedVerseText = () => {
    if (!data.verseText) return null;
    const parts = data.verseText.split(/(\s+|[.,!?;:"'-]+)/g);
    const fontSizeVal = `${(1.875 * (data.textScale || 1)).toFixed(3)}rem`;

    return (
        <p className="leading-snug italic px-4" style={{ ...textStyle, fontSize: fontSizeVal }}>
            "
            {parts.map((part, i) => {
                const clean = part.toLowerCase().replace(/[^a-z0-9]/g, '');
                const isHighlight = clean.length > 2 && highlightedKeywords.has(clean);
                if (isHighlight) {
                    return (
                        <span key={i} style={{ ...highlightStyle, display: 'inline-block', transform: 'scale(1.1)', fontSize: '1.25em' }}>
                            {part}
                        </span>
                    );
                }
                return <span key={i}>{part}</span>;
            })}
            "
        </p>
    );
  };

  const UploadTrigger = ({ field, children, className = "" }: { field: keyof PosterData, children?: React.ReactNode, className?: string }) => (
    <div 
      className={`relative group cursor-pointer ${className}`}
      onClick={(e) => { e.stopPropagation(); onTriggerUpload?.(field); }}
      title={`Click to upload ${field === 'backgroundImageUrl' ? 'Background' : field === 'uploadedPhotoUrl' ? 'Photo' : 'Logo'}`}
    >
      {children}
      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity rounded-inherit z-50 pointer-events-none">
        <Upload size={16} className="text-white" />
      </div>
    </div>
  );

  const LogoElement = () => (
    <UploadTrigger field="logoUrl" className="inline-block rounded-full overflow-hidden w-full h-full">
      {data.logoUrl ? (
        <img src={data.logoUrl} alt="Logo" className="w-full h-full object-cover rounded-full drop-shadow-md" crossOrigin="anonymous"/>
      ) : (
        <div className="w-full h-full bg-white/20 border-2 border-dashed border-white/50 rounded-full flex items-center justify-center backdrop-blur-sm">
            <span className="text-[10px] text-white font-bold uppercase">Logo</span>
        </div>
      )}
    </UploadTrigger>
  );

  const PhotoElement = ({ className = "" }: { className?: string }) => (
     <UploadTrigger field="uploadedPhotoUrl" className={`w-full h-full ${className}`}>
        {data.uploadedPhotoUrl ? (
            <div className="w-full h-full rounded-[1.5rem] border-4 border-white/30 overflow-hidden shadow-2xl">
                <img src={data.uploadedPhotoUrl} alt="User" className="w-full h-full object-cover" crossOrigin="anonymous"/>
            </div>
        ) : (
            <div className="w-full h-full rounded-[1.5rem] border-4 border-dashed border-white/40 bg-white/10 flex flex-col items-center justify-center text-white/80 backdrop-blur-sm">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1 uppercase">Photo</span>
            </div>
        )}
     </UploadTrigger>
  );

  const TextContent = () => (
    <div className={`flex flex-col gap-4 items-center text-center`}>
         {data.mode === AppMode.VERSE ? (
            <>
              <HighlightedVerseText />
              <div className="h-1 w-12 bg-current opacity-50 rounded-full" style={{ color: data.textColor }}></div>
              <div className="flex flex-col items-center gap-1">
                  <p className="text-lg font-bold uppercase tracking-widest" style={accentStyle}>{data.verseReference}</p>
                  {data.verseReferenceEnglish && data.verseReferenceEnglish !== data.verseReference && (
                      <p className="text-sm font-bold uppercase tracking-widest opacity-80" style={{ ...accentStyle, fontFamily: "'Inter', sans-serif" }}>
                        {data.verseReferenceEnglish}
                      </p>
                  )}
              </div>
            </>
          ) : (
            <>
              <h1 className="text-4xl font-bold leading-tight" style={textStyle}>{data.eventTitle || "Event Title"}</h1>
              <p className="text-lg whitespace-pre-wrap font-light opacity-90" style={textStyle}>{data.eventDetails || "Date • Time • Venue"}</p>
            </>
          )}
    </div>
  );

  const renderOverlays = () => {
    switch (data.layout) {
      case LayoutType.CINEMATIC:
        return (
           <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/30 z-0 pointer-events-none"></div>
        );
      default:
        // Generic overlay from template style if needed, can be empty if handled by root style
        return null;
    }
  };

  return (
    <div className="w-full flex justify-center py-4 select-none" style={{ transform: `scale(${scale})`, transformOrigin: 'top center' }}>
      <div 
        ref={ref}
        id="poster-canvas"
        className={`relative bg-slate-200 overflow-hidden shadow-[0_20px_50px_-12px_rgba(0,0,0,0.5)] flex flex-col group/poster`}
        style={{ width: baseWidth, height: baseHeight }}
      >
        {/* Background Image (Click to Upload) */}
        <div 
            className="absolute inset-0 z-0 cursor-pointer"
            onClick={(e) => { e.stopPropagation(); onTriggerUpload?.('backgroundImageUrl'); }}
            title="Click background to change image"
        >
            {data.backgroundImageUrl ? (
            <img 
                src={data.backgroundImageUrl} 
                alt="Background" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                crossOrigin="anonymous"
            />
            ) : (
            <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                <ImageIcon className="text-slate-600" size={48} />
            </div>
            )}
        </div>

        {/* Overlay for non-cinematic modes (Template Color Overlay) */}
        {data.layout !== LayoutType.CINEMATIC && (
          <div className={`absolute inset-0 z-0 pointer-events-none ${styles.overlay}`}></div>
        )}

        {/* Layout Specific Overlays (e.g. Cinematic Gradient) */}
        {renderOverlays()}

        {/* --- MOVABLE LAYERS --- */}

        {/* 1. Logo */}
        <DraggableElement 
            position={data.logoPosition || {x: 10, y: 10}}
            width={data.logoWidth || 16}
            resizable={true}
            isActive={activeDragId === 'logo'}
            onMouseDown={(e, action) => handleMouseDown(e, 'logo', action)}
        >
             <div className="flex flex-col items-center w-full aspect-square">
                <LogoElement />
                {data.customName && <span className="text-[10px] font-bold uppercase tracking-widest text-white/90 mt-1 shadow-black drop-shadow-md">{data.customName}</span>}
             </div>
        </DraggableElement>

        {/* 2. Photo */}
        <DraggableElement 
            position={data.photoPosition || {x: 90, y: 10}}
            width={data.photoWidth || 24}
            resizable={true}
            isActive={activeDragId === 'photo'}
            onMouseDown={(e, action) => handleMouseDown(e, 'photo', action)}
        >
             <div className="w-full aspect-square">
                <PhotoElement />
             </div>
        </DraggableElement>

        {/* 3. Text (With Resize/Scale options) */}
        <DraggableElement 
            position={data.textPosition} 
            width={data.textWidth} 
            resizable={true}
            isActive={activeDragId === 'text'}
            onMouseDown={(e, action) => handleMouseDown(e, 'text', action)}
        >
            <TextContent />
        </DraggableElement>

      </div>
    </div>
  );
});

PosterPreview.displayName = 'PosterPreview';

export default PosterPreview;

import React, { useState, useRef, useEffect } from 'react';
import { AppMode, PosterData, TemplateStyle, TextEffect } from '../types';
import { CONTENT_LANGUAGES, DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, UI_TRANSLATIONS, SUPPORTED_LANGUAGES, INPUT_METHOD_CODES } from '../constants';
import { fetchVerse } from '../services/bibleService';
import { translateText, translateReference, recommendFonts, interpretVerseReference } from '../services/geminiService';
import { Search, Sparkles, Type, Calendar, Palette, ChevronDown, Globe, BookOpen, Wand2, ChevronLeft, ChevronRight, Keyboard } from 'lucide-react';

interface Props {
  data: PosterData;
  onUpdate: (data: Partial<PosterData>) => void;
}

const EditorPanel: React.FC<Props> = ({ data, onUpdate }) => {
  const [verseQuery, setVerseQuery] = useState("");
  const [isSearching, setIsSearching] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);

  // Font AI State
  const [isAiFontMode, setIsAiFontMode] = useState(false);
  const [fontAiQuery, setFontAiQuery] = useState("");
  const [isGeneratingFont, setIsGeneratingFont] = useState(false);
  const [suggestedFonts, setSuggestedFonts] = useState<string[]>([]);

  // Font Carousel State
  const [fontPage, setFontPage] = useState(0);
  const FONTS_PER_PAGE = 6;
  const totalFontPages = Math.ceil(AVAILABLE_FONTS.length / FONTS_PER_PAGE);

  // State for custom dropdowns
  const [isLangOpen, setIsLangOpen] = useState(false);
  const langDropdownRef = useRef<HTMLDivElement>(null);

  // Transliteration State
  const [isTransliterationEnabled, setIsTransliterationEnabled] = useState(true);

  const LIGHT_COLORS = [
    "#FFFFFF", "#F1F5F9", "#FEF08A", "#BAE6FD", "#FECDD3", "#BBF7D0", "#E9D5FF"
  ];
  const DARK_COLORS = [
    "#000000", "#334155", "#1E3A8A", "#881337", "#14532D", "#581C87", "#451A03"
  ];

  // New Gradient Colors
  const GRADIENT_COLORS = [
    "linear-gradient(to right, #bf953f, #fcf6ba, #b38728, #fbf5b7, #aa771c)", // Gold
    "linear-gradient(to right, #D7D7D7, #FFFFFF, #EAEAEA, #C0C0C0)", // Silver
    "linear-gradient(to right, #ff9a9e 0%, #fecfef 99%, #fecfef 100%)", // Rose
    "linear-gradient(to right, #4facfe 0%, #00f2fe 100%)", // Blue
    "linear-gradient(135deg, #FFF 0%, #000 100%)", // Mono
    "linear-gradient(to right, #f83600 0%, #f9d423 100%)", // Fire
  ];

  const TEXT_EFFECTS = [
    { id: TextEffect.NONE, label: 'None', style: {} },
    { id: TextEffect.SHADOW_SOFT, label: 'Soft', style: { textShadow: '0 2px 4px rgba(0,0,0,0.4)' } },
    { id: TextEffect.SHADOW_HARD, label: 'Bold', style: { textShadow: '2px 2px 0 #000' } },
    { id: TextEffect.OUTLINE, label: 'Outline', style: { WebkitTextStroke: '1px black', color: 'transparent' } },
    { id: TextEffect.NEON, label: 'Neon', style: { textShadow: '0 0 5px #fff, 0 0 10px currentColor' } },
    { id: TextEffect.RETRO, label: 'Retro', style: { textShadow: '2px 2px 0 #ccc, 4px 4px 0 #999' } },
  ];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (langDropdownRef.current && !langDropdownRef.current.contains(event.target as Node)) {
        setIsLangOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Helpers
  const currentLangCode = data.interfaceLanguage || 'en';
  const t = (key: keyof typeof UI_TRANSLATIONS['en']) => {
    // @ts-ignore - dynamic key access
    return UI_TRANSLATIONS[currentLangCode]?.[key] || UI_TRANSLATIONS['en'][key] || key;
  };

  // --- Transliteration Logic ---
  const handleTransliterate = async (word: string): Promise<string> => {
    const code = INPUT_METHOD_CODES[data.language];
    if (!code || !word) return word;

    try {
        const response = await fetch(`https://inputtools.google.com/request?text=${word}&itc=${code}&num=1&cp=0&cs=1&ie=utf-8&oe=utf-8&app=demopage`);
        const json = await response.json();
        // Structure: ["SUCCESS", [ [ "input_word", [ "suggestion1", ... ] ] ] ]
        if (json[0] === 'SUCCESS' && json[1] && json[1][0] && json[1][0][1]) {
            return json[1][0][1][0]; // Return the first suggestion
        }
    } catch (e) {
        console.error("Transliteration failed", e);
    }
    return word;
  };

  // Reusable Smart Input Handler for Transliteration
  const handleSmartInput = async (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
    currentValue: string,
    updateState: (val: string) => void
  ) => {
    const newVal = e.target.value;

    // Check if transliteration is enabled, language is not English, and user just typed a space
    if (isTransliterationEnabled && data.language !== 'English' && newVal.endsWith(' ') && !currentValue.endsWith(' ')) {
        const textBeforeSpace = newVal.slice(0, -1);

        // Find last word boundary (space or newline)
        const match = textBeforeSpace.match(/([^\s]+)$/);

        if (match) {
            const lastWord = match[1];
            // Only convert if it's alphanumeric (English typing) or contains basic punctuation
            if (/^[a-zA-Z0-9]+$/.test(lastWord)) {
                const translated = await handleTransliterate(lastWord);
                if (translated !== lastWord) {
                    const prefix = textBeforeSpace.substring(0, textBeforeSpace.length - lastWord.length);
                    updateState(prefix + translated + ' ');
                    return;
                }
            }
        }
    }

    updateState(newVal);
  };

  const handleQueryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      handleSmartInput(e, verseQuery, setVerseQuery);
  };
  // -----------------------------

  const handleSearchVerse = async () => {
    if (!verseQuery) return;
    setIsSearching(true);

    // Find the Bible Version ID for the current language
    const langConfig = SUPPORTED_LANGUAGES.find(l => l.code === data.interfaceLanguage);
    const bibleVersion = langConfig?.bibleVersion || 'web'; // Default to WEB (English)

    // INTERCEPT: If the query is likely not English (because user typed in localized language),
    // we need to convert it to English Reference first (e.g. "मार्क 3:7" -> "Mark 3:7")
    // otherwise the API will fail.
    let searchQuery = verseQuery;
    if (data.language !== 'English' && /[^\x00-\x7F]/.test(verseQuery)) {
        searchQuery = await interpretVerseReference(verseQuery);
        console.log("Interpreted Search Query:", searchQuery);
    }

    // Pass the standard English version to fetchVerse
    const result = await fetchVerse(searchQuery, bibleVersion);
    setIsSearching(false);

    if (result) {
      // 1. Initially set what we got. 
      // Assumption: The API returns standard English refs usually, or we treat it as the "Source" ref.
      onUpdate({ 
        verseText: result.text,
        verseReference: result.reference, 
        verseReferenceEnglish: result.reference 
      });

      // 2. If the user has explicitly selected a Target Language that is NOT English,
      // translate the text AND reference.
      // NOTE: We also pass the *User's Typed Query* (verseQuery) as the potential reference 
      // if it was already in the target language!
      if (data.language !== 'English') {
         // If the user typed in the target language (e.g. Hindi), use that as the display reference immediately
         // otherwise translate it.
         if (/[^\x00-\x7F]/.test(verseQuery)) {
             // User typed localized ref, use it!
             onUpdate({ verseReference: verseQuery });
             // Just translate text
             const translatedText = await translateText(result.text, data.language);
             onUpdate({ verseText: translatedText });
         } else {
             // User typed English ref, so translate everything
             handleTranslate(result.text, data.language, result.reference);
         }
      }
    } else {
      alert(`Verse not found for "${searchQuery}". Try format 'John 3:16'`);
    }
  };

  const handleTranslate = async (text: string, langName: string, ref: string) => {
    setIsTranslating(true);

    // 1. Translate the Text
    const translatedTextPromise = translateText(text, langName);

    // 2. Translate the Reference explicitly if not English
    let translatedRefPromise = Promise.resolve(ref);
    if (langName !== 'English') {
        translatedRefPromise = translateReference(ref, langName);
    }

    const [translatedText, translatedRef] = await Promise.all([translatedTextPromise, translatedRefPromise]);

    // 3. Update State:
    onUpdate({ 
        verseText: translatedText, 
        verseReference: translatedRef, 
        verseReferenceEnglish: ref // Preserves the source/English ref
    });

    setIsTranslating(false);
  };

  const handleAiFontGeneration = async () => {
    if (!fontAiQuery.trim()) return;
    setIsGeneratingFont(true);
    const result = await recommendFonts(fontAiQuery);
    setIsGeneratingFont(false);

    if (result.fontValues.length > 0) {
      setSuggestedFonts(result.fontValues);
      onUpdate({ fontFamily: result.fontValues[0] });
      if (result.suggestedColor) {
        onUpdate({ textColor: result.suggestedColor });
      }
      setIsAiFontMode(false); 
    } else {
      alert("Could not find matching fonts.");
    }
  };

  const handleTemplateChange = (style: TemplateStyle) => {
    onUpdate({ 
      template: style,
      backgroundImageUrl: DEFAULT_BACKGROUNDS[style]
    });
  };

  const nextFontPage = () => {
    if (fontPage < totalFontPages - 1) {
        setFontPage(prev => prev + 1);
    }
  };

  const prevFontPage = () => {
    if (fontPage > 0) {
        setFontPage(prev => prev - 1);
    }
  };

  const currentFonts = AVAILABLE_FONTS.slice(fontPage * FONTS_PER_PAGE, (fontPage + 1) * FONTS_PER_PAGE);

  const TransliterationToggle = () => (
    INPUT_METHOD_CODES[data.language] ? (
        <button 
            onClick={() => setIsTransliterationEnabled(!isTransliterationEnabled)}
            className={`text-[10px] font-bold px-2 py-0.5 rounded cursor-pointer transition-colors flex items-center gap-1 ${isTransliterationEnabled ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-400'}`}
            title={`When enabled, typing phonetically in English + Spacebar converts text to ${data.language}`}
        >
            <Keyboard size={10} /> {data.language} Typing {isTransliterationEnabled ? 'ON' : 'OFF'}
        </button>
    ) : null
  );

  return (
    <div className="space-y-6 p-6 bg-white rounded-2xl shadow-xl border border-slate-100">

      {/* Header */}
      <div className="pb-2">
        <h2 className="text-2xl font-serif font-bold text-slate-900 flex items-center gap-2">
          {data.mode === AppMode.VERSE ? <Sparkles className="w-6 h-6 text-gold" /> : <Calendar className="w-6 h-6 text-blue-500" />}
          <span className="bg-gradient-to-r from-slate-900 to-slate-600 bg-clip-text text-transparent">
            {data.mode === AppMode.VERSE ? t('verse_editor') : t('event_editor')}
          </span>
        </h2>
        <p className="text-slate-400 text-sm mt-1">{t('customize_msg')}</p>
      </div>

      {/* RICH LANGUAGE SELECTOR (CONTENT LANGUAGE) */}
      <div className="relative group z-30" ref={langDropdownRef}>
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1">
          <Globe size={12} /> Target Language
        </label>
        <button 
          onClick={() => setIsLangOpen(!isLangOpen)}
          className="w-full flex items-center justify-between p-3.5 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-blue-300 hover:shadow-md transition-all group-hover:ring-2 group-hover:ring-blue-50"
        >
          <span className="font-semibold text-slate-800">{data.language}</span>
          <ChevronDown size={16} className={`text-slate-400 transition-transform ${isLangOpen ? 'rotate-180' : ''}`} />
        </button>

        {isLangOpen && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-2xl border border-slate-100 max-h-60 overflow-y-auto p-1.5 z-40 animate-in fade-in zoom-in-95 duration-200">
            {CONTENT_LANGUAGES.map(lang => (
              <button
                key={lang}
                onClick={() => {
                  const newLang = lang;
                  onUpdate({ language: newLang });
                  setIsLangOpen(false);
                }}
                className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${data.language === lang ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'}`}
              >
                {lang}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Content Input */}
      {data.mode === AppMode.VERSE ? (
        <div className="space-y-4">

          {/* RICH FIND VERSE SEARCH BAR */}
          <div className="relative z-20">
            <div className="flex justify-between items-end mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1">
                <BookOpen size={12} /> {t('find_verse')}
                </label>

                {/* Transliteration Toggle Badge */}
                <TransliterationToggle />
            </div>

            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search size={18} className="text-slate-400 group-focus-within:text-blue-500 transition-colors" />
              </div>
              <input 
                type="text" 
                placeholder={isTransliterationEnabled && data.language !== 'English' ? `Type in ${data.language} (e.g. mark...)` : t('search_placeholder')}
                className="w-full pl-10 pr-12 py-3.5 bg-white border border-slate-200 rounded-xl shadow-sm text-slate-800 font-medium placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-400 transition-all"
                value={verseQuery}
                onChange={handleQueryChange}
                onKeyDown={(e) => e.key === 'Enter' && handleSearchVerse()}
              />
              <button 
                onClick={handleSearchVerse}
                disabled={isSearching}
                className="absolute right-2 top-2 p-1.5 bg-slate-100 text-slate-500 rounded-lg hover:bg-blue-600 hover:text-white transition-all disabled:opacity-50"
              >
                {isSearching ? <span className="block w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></span> : <ChevronDown className="rotate-[-90deg]" size={16} />}
              </button>
            </div>
            {isTransliterationEnabled && data.language !== 'English' && (
                <p className="text-[10px] text-slate-400 mt-1 pl-1">Tip: Type phonetically and press <b>Space</b> to convert to {data.language}.</p>
            )}
          </div>

          <div className="space-y-0 shadow-sm rounded-xl overflow-hidden border border-slate-200 focus-within:ring-2 focus-within:ring-blue-50 focus-within:border-blue-300 transition-all">
             <textarea 
               className="w-full p-4 h-28 text-base bg-slate-900 text-white placeholder-slate-400 resize-none outline-none font-serif leading-relaxed"
               value={data.verseText}
               onChange={(e) => onUpdate({ verseText: e.target.value })}
               placeholder={t('verse_text_placeholder')}
             />
             <div className="bg-slate-800 px-4 py-2 border-t border-slate-700 flex items-center gap-2">
               <span className="text-xs font-bold text-slate-400 uppercase">Ref:</span>
               <input 
                 type="text"
                 className="flex-1 bg-transparent text-sm font-bold text-slate-200 outline-none placeholder-slate-500"
                 value={data.verseReference}
                 onChange={(e) => onUpdate({ verseReference: e.target.value })}
                 placeholder="Genesis 1:1"
               />
               {isTranslating && <span className="text-xs text-blue-400 font-medium animate-pulse">Translating...</span>}
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="relative">
            <div className="flex justify-between items-center mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('event_title')}</label>
                <TransliterationToggle />
            </div>
            <input 
              type="text" 
              placeholder="e.g. Youth Worship Night"
              className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm font-bold text-white focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all placeholder:text-slate-500"
              value={data.eventTitle}
              onChange={(e) => handleSmartInput(e, data.eventTitle, (v) => onUpdate({ eventTitle: v }))}
            />
          </div>
          <div className="relative">
             <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5">{t('event_details')}</label>
             <textarea 
               placeholder={t('event_details_placeholder')}
               className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm h-28 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all resize-none text-white placeholder:text-slate-500"
               value={data.eventDetails}
               onChange={(e) => handleSmartInput(e, data.eventDetails, (v) => onUpdate({ eventDetails: v }))}
             />
             {isTransliterationEnabled && data.language !== 'English' && (
                <p className="text-[10px] text-slate-500 mt-1 pl-1">Phonetic typing active for Title & Details.</p>
             )}
          </div>
        </div>
      )}

      {/* Typography Section */}
      <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-4 relative z-10">
        <div className="flex items-center justify-between">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1">
            <Palette size={12} /> {t('typography')}
            </label>

            {/* AI Font Generator Toggle */}
            <button 
                onClick={() => setIsAiFontMode(!isAiFontMode)}
                className={`text-xs px-2 py-1 rounded-md flex items-center gap-1 transition-colors ${isAiFontMode ? 'bg-purple-100 text-purple-700 font-bold' : 'text-slate-400 hover:bg-slate-100'}`}
                title="Generate AI Font Recommendations"
            >
                <Wand2 size={12} /> AI Fonts
            </button>
        </div>

        {/* AI Font Input Area */}
        {isAiFontMode && (
             <div className="flex gap-2 animate-in slide-in-from-top-2 duration-300">
                <input 
                    type="text" 
                    placeholder="Describe mood (e.g. 'Spooky', 'Retro', 'Elegant')..."
                    className="flex-1 px-3 py-2 text-sm border border-purple-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-100"
                    value={fontAiQuery}
                    onChange={(e) => setFontAiQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAiFontGeneration()}
                />
                <button 
                    onClick={handleAiFontGeneration}
                    disabled={isGeneratingFont}
                    className="bg-purple-600 text-white px-3 py-2 rounded-lg hover:bg-purple-700 disabled:opacity-50 transition-colors"
                >
                    {isGeneratingFont ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"/> : <Sparkles size={16} />}
                </button>
             </div>
        )}

        {/* Font Slider (Paginated Grid) */}
        <div className="relative bg-white border border-slate-200 rounded-xl shadow-sm p-2 overflow-hidden">
             <div className="flex justify-between items-center mb-2 px-1">
                <button 
                  onClick={prevFontPage}
                  disabled={fontPage === 0}
                  className="p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors"
                >
                    <ChevronLeft size={20} />
                </button>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    Font ({fontPage + 1}/{totalFontPages})
                </span>
                <button 
                  onClick={nextFontPage}
                  disabled={fontPage === totalFontPages - 1}
                  className={`p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors ${fontPage < totalFontPages - 1 ? 'animate-pulse text-blue-500' : ''}`}
                >
                    <ChevronRight size={20} />
                </button>
             </div>

             <div className="grid grid-cols-2 gap-2">
                {currentFonts.map((font) => (
                    <button
                        key={font.name}
                        onClick={() => onUpdate({ fontFamily: font.value })}
                        className={`p-2.5 rounded-lg border text-center transition-all h-14 flex items-center justify-center ${data.fontFamily === font.value ? 'bg-blue-50 border-blue-400 text-blue-700 ring-1 ring-blue-100' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-white hover:border-blue-200'}`}
                        title={font.name}
                    >
                        <span className="truncate w-full text-sm" style={{ fontFamily: font.value.split(',')[0].replace(/'/g, "") }}>
                            {font.name.split('(')[0].trim()}
                        </span>
                    </button>
                ))}
             </div>

             {/* Pagination Dots */}
             <div className="flex justify-center gap-1.5 mt-2">
                {Array.from({ length: totalFontPages }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`w-1.5 h-1.5 rounded-full transition-colors ${i === fontPage ? 'bg-slate-800' : 'bg-slate-300'}`} 
                    />
                ))}
             </div>
        </div>

        {/* Color Palette & Gradient */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-4">
           {/* Color Header + Custom Picker */}
           <div className="flex justify-between items-center">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{t('text_color')}</label>
              <div className="flex items-center gap-2">
                 <div className="w-5 h-5 rounded-full border border-slate-200 shadow-inner overflow-hidden relative cursor-pointer ring-1 ring-offset-1 ring-slate-100">
                   <input 
                     type="color" 
                     value={data.textColor.startsWith('linear') ? '#ffffff' : data.textColor}
                     onChange={(e) => onUpdate({ textColor: e.target.value })}
                     className="absolute -top-2 -left-2 w-10 h-10 cursor-pointer p-0 opacity-0" 
                   />
                   <div className="w-full h-full" style={{ background: data.textColor }}></div>
                 </div>
              </div>
           </div>

           {/* Color Grid */}
           <div className="space-y-3">
              <div className="flex justify-between">
                {LIGHT_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>
              <div className="flex justify-between">
                {DARK_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>

              {/* Gradient Options */}
              <div className="pt-2 border-t border-slate-100">
                 <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">Gradients</p>
                 <div className="flex justify-between">
                    {GRADIENT_COLORS.map((gradient, i) => (
                        <button
                            key={i}
                            onClick={() => onUpdate({ textColor: gradient })}
                            className={`w-6 h-6 rounded-full border transition-all ${data.textColor === gradient ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                            style={{ background: gradient }}
                            title="Gradient"
                        />
                    ))}
                 </div>
              </div>
           </div>

           <div className="h-px bg-slate-100 w-full my-2"></div>

           {/* Text Effects Selector */}
           <div className="pt-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 block">{t('text_effects')}</label>
              <div className="grid grid-cols-3 gap-2">
                 {TEXT_EFFECTS.map((effect) => (
                    <button
                        key={effect.id}
                        onClick={() => onUpdate({ textEffect: effect.id })}
                        className={`text-xs py-2 px-1 rounded-lg border transition-all font-medium ${data.textEffect === effect.id ? 'bg-blue-50 border-blue-400 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:border-blue-200'}`}
                        style={{ fontFamily: 'sans-serif' }}
                    >
                        <span style={effect.style as any}>Aa</span> {effect.label}
                    </button>
                 ))}
              </div>
           </div>
        </div>
      </div>

      {/* Custom Name */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('footer_label')}</label>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl p-3 focus-within:bg-white focus-within:border-blue-300 focus-within:ring-4 focus-within:ring-blue-50 transition-all">
          <Type size={16} className="text-slate-400" />
          <input 
            type="text" 
            placeholder="Family Name / Church Name"
            className="flex-1 outline-none bg-transparent text-sm font-medium text-slate-800"
            value={data.customName}
            onChange={(e) => onUpdate({ customName: e.target.value })}
          />
        </div>
      </div>

      {/* Template Selection */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('theme')}</label>
        <div className="grid grid-cols-5 gap-3">
          {Object.values(TemplateStyle).map((style) => (
            <button
              key={style}
              onClick={() => handleTemplateChange(style)}
              className={`group relative w-full aspect-[3/4] rounded-xl border-2 transition-all shadow-sm overflow-hidden ${data.template === style ? 'border-blue-600 ring-2 ring-blue-100 scale-105' : 'border-transparent hover:border-blue-200 hover:scale-105'}`}
              title={style}
            >
               {/* Use Real Image Thumbnail */}
               <div className="w-full h-full bg-cover bg-center transition-transform group-hover:scale-110 duration-700"
                    style={{ backgroundImage: `url(${DEFAULT_BACKGROUNDS[style]})` }}
               ></div>

               {/* Label Overlay */}
               <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent p-1.5 pt-4 flex justify-center">
                  <span className="text-[9px] font-bold text-white uppercase tracking-wider">{style}</span>
               </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default EditorPanel;

import React, { useState, useRef, useEffect } from 'react';
import { AppMode, PosterData, TemplateStyle, TextEffect } from '../types';
import { CONTENT_LANGUAGES, DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, UI_TRANSLATIONS, SUPPORTED_LANGUAGES, INPUT_METHOD_CODES } from '../constants';
import { fetchVerse } from '../services/bibleService';
import { translateText, translateReference, recommendFonts, interpretVerseReference } from '../services/geminiService';
import { Search, Sparkles, Type, Calendar, Palette, ChevronDown, Globe, BookOpen, Wand2, ChevronLeft, ChevronRight, Keyboard } from 'lucide-react';

interface Props {
  data: PosterData;
  onUpdate: (data: Partial<PosterData>) => void;
}

const EditorPanel: React.FC<Props> = ({ data, onUpdate }) => {
  const [verseQuery, setVerseQuery] = useState("");
  const [isSearching, setIsSearching] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);

  // Font AI State
  const [isAiFontMode, setIsAiFontMode] = useState(false);
  const [fontAiQuery, setFontAiQuery] = useState("");
  const [isGeneratingFont, setIsGeneratingFont] = useState(false);
  const [suggestedFonts, setSuggestedFonts] = useState<string[]>([]);

  // Font Carousel State
  const [fontPage, setFontPage] = useState(0);
  const FONTS_PER_PAGE = 6;
  const totalFontPages = Math.ceil(AVAILABLE_FONTS.length / FONTS_PER_PAGE);

  // State for custom dropdowns
  const [isLangOpen, setIsLangOpen] = useState(false);
  const langDropdownRef = useRef<HTMLDivElement>(null);

  // Transliteration State
  const [isTransliterationEnabled, setIsTransliterationEnabled] = useState(true);

  const LIGHT_COLORS = [
    "#FFFFFF", "#F1F5F9", "#FEF08A", "#BAE6FD", "#FECDD3", "#BBF7D0", "#E9D5FF"
  ];
  const DARK_COLORS = [
    "#000000", "#334155", "#1E3A8A", "#881337", "#14532D", "#581C87", "#451A03"
  ];

  // New Gradient Colors
  const GRADIENT_COLORS = [
    "linear-gradient(to right, #bf953f, #fcf6ba, #b38728, #fbf5b7, #aa771c)", // Gold
    "linear-gradient(to right, #D7D7D7, #FFFFFF, #EAEAEA, #C0C0C0)", // Silver
    "linear-gradient(to right, #ff9a9e 0%, #fecfef 99%, #fecfef 100%)", // Rose
    "linear-gradient(to right, #4facfe 0%, #00f2fe 100%)", // Blue
    "linear-gradient(135deg, #FFF 0%, #000 100%)", // Mono
    "linear-gradient(to right, #f83600 0%, #f9d423 100%)", // Fire
  ];

  const TEXT_EFFECTS = [
    { id: TextEffect.NONE, label: 'None', style: {} },
    { id: TextEffect.SHADOW_SOFT, label: 'Soft', style: { textShadow: '0 2px 4px rgba(0,0,0,0.4)' } },
    { id: TextEffect.SHADOW_HARD, label: 'Bold', style: { textShadow: '2px 2px 0 #000' } },
    { id: TextEffect.OUTLINE, label: 'Outline', style: { WebkitTextStroke: '1px black', color: 'transparent' } },
    { id: TextEffect.NEON, label: 'Neon', style: { textShadow: '0 0 5px #fff, 0 0 10px currentColor' } },
    { id: TextEffect.RETRO, label: 'Retro', style: { textShadow: '2px 2px 0 #ccc, 4px 4px 0 #999' } },
  ];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (langDropdownRef.current && !langDropdownRef.current.contains(event.target as Node)) {
        setIsLangOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Helpers
  const currentLangCode = data.interfaceLanguage || 'en';
  const t = (key: keyof typeof UI_TRANSLATIONS['en']) => {
    // @ts-ignore - dynamic key access
    return UI_TRANSLATIONS[currentLangCode]?.[key] || UI_TRANSLATIONS['en'][key] || key;
  };

  // --- Transliteration Logic ---
  const handleTransliterate = async (word: string): Promise<string> => {
    const code = INPUT_METHOD_CODES[data.language];
    if (!code || !word) return word;

    try {
        const response = await fetch(`https://inputtools.google.com/request?text=${word}&itc=${code}&num=1&cp=0&cs=1&ie=utf-8&oe=utf-8&app=demopage`);
        const json = await response.json();
        // Structure: ["SUCCESS", [ [ "input_word", [ "suggestion1", ... ] ] ] ]
        if (json[0] === 'SUCCESS' && json[1] && json[1][0] && json[1][0][1]) {
            return json[1][0][1][0]; // Return the first suggestion
        }
    } catch (e) {
        console.error("Transliteration failed", e);
    }
    return word;
  };

  // Reusable Smart Input Handler for Transliteration
  const handleSmartInput = async (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
    currentValue: string,
    updateState: (val: string) => void
  ) => {
    const newVal = e.target.value;

    // Determine the last character typed (or delimiter)
    // We check if the string grew by 1 char and that char is a delimiter, 
    // or if the length change implies a paste/type event that resulted in a delimiter at end.
    // Simpler check: Does it end with a delimiter now?
    const delimiter = newVal.slice(-1);
    const isDelimiter = delimiter === ' ' || delimiter === '\n'; // Handle Space or Enter

    // Ensure we don't trigger if we just deleted back to a space, or if the value didn't actually add a delimiter
    // The safest way is to check if the new value has a delimiter at the end and the old one didn't (or was shorter).
    // But `currentValue` is the state before this render.

    // We only trigger if the user explicitly typed a delimiter.
    // Limitation: If user pastes "hello ", it triggers. That's fine.

    if (isTransliterationEnabled && data.language !== 'English' && isDelimiter) {
        // Did we already have a delimiter there? (e.g. double space). 
        // If the user types "word  ", the first space triggers "translation ". 
        // The second space -> "translation  ". textBefore is "translation ". Last word is "translation".
        // handleTransliterate("translation") -> might return same if not latin.

        // Optimizing: Only try to translate if the last word is Latin characters.
        const textBeforeDelimiter = newVal.slice(0, -1);
        const match = textBeforeDelimiter.match(/([^\s]+)$/); // Find last word

        if (match) {
            const lastWord = match[1];
            // Only convert if it's alphanumeric (English typing)
            if (/^[a-zA-Z0-9]+$/.test(lastWord)) {
                const translated = await handleTransliterate(lastWord);
                if (translated !== lastWord) {
                    const prefix = textBeforeDelimiter.substring(0, textBeforeDelimiter.length - lastWord.length);
                    updateState(prefix + translated + delimiter);
                    return;
                }
            }
        }
    }

    updateState(newVal);
  };

  const handleQueryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      handleSmartInput(e, verseQuery, setVerseQuery);
  };
  // -----------------------------

  const handleSearchVerse = async () => {
    if (!verseQuery) return;
    setIsSearching(true);

    // Find the Bible Version ID for the current language
    const langConfig = SUPPORTED_LANGUAGES.find(l => l.code === data.interfaceLanguage);
    const bibleVersion = langConfig?.bibleVersion || 'web'; // Default to WEB (English)

    // INTERCEPT: If the query is likely not English (because user typed in localized language),
    // we need to convert it to English Reference first (e.g. "मार्क 3:7" -> "Mark 3:7")
    // otherwise the API will fail.
    let searchQuery = verseQuery;
    if (data.language !== 'English' && /[^\x00-\x7F]/.test(verseQuery)) {
        searchQuery = await interpretVerseReference(verseQuery);
        console.log("Interpreted Search Query:", searchQuery);
    }

    // Pass the standard English version to fetchVerse
    const result = await fetchVerse(searchQuery, bibleVersion);
    setIsSearching(false);

    if (result) {
      // 1. Initially set what we got. 
      // Assumption: The API returns standard English refs usually, or we treat it as the "Source" ref.
      onUpdate({ 
        verseText: result.text,
        verseReference: result.reference, 
        verseReferenceEnglish: result.reference 
      });

      // 2. If the user has explicitly selected a Target Language that is NOT English,
      // translate the text AND reference.
      // NOTE: We also pass the *User's Typed Query* (verseQuery) as the potential reference 
      // if it was already in the target language!
      if (data.language !== 'English') {
         // If the user typed in the target language (e.g. Hindi), use that as the display reference immediately
         // otherwise translate it.
         if (/[^\x00-\x7F]/.test(verseQuery)) {
             // User typed localized ref, use it!
             onUpdate({ verseReference: verseQuery });
             // Just translate text
             const translatedText = await translateText(result.text, data.language);
             onUpdate({ verseText: translatedText });
         } else {
             // User typed English ref, so translate everything
             handleTranslate(result.text, data.language, result.reference);
         }
      }
    } else {
      alert(`Verse not found for "${searchQuery}". Try format 'John 3:16'`);
    }
  };

  const handleTranslate = async (text: string, langName: string, ref: string) => {
    setIsTranslating(true);

    // 1. Translate the Text
    const translatedTextPromise = translateText(text, langName);

    // 2. Translate the Reference explicitly if not English
    let translatedRefPromise = Promise.resolve(ref);
    if (langName !== 'English') {
        translatedRefPromise = translateReference(ref, langName);
    }

    const [translatedText, translatedRef] = await Promise.all([translatedTextPromise, translatedRefPromise]);

    // 3. Update State:
    onUpdate({ 
        verseText: translatedText, 
        verseReference: translatedRef, 
        verseReferenceEnglish: ref // Preserves the source/English ref
    });

    setIsTranslating(false);
  };

  const handleAiFontGeneration = async () => {
    if (!fontAiQuery.trim()) return;
    setIsGeneratingFont(true);
    const result = await recommendFonts(fontAiQuery);
    setIsGeneratingFont(false);

    if (result.fontValues.length > 0) {
      setSuggestedFonts(result.fontValues);
      onUpdate({ fontFamily: result.fontValues[0] });
      if (result.suggestedColor) {
        onUpdate({ textColor: result.suggestedColor });
      }
      setIsAiFontMode(false); 
    } else {
      alert("Could not find matching fonts.");
    }
  };

  const handleTemplateChange = (style: TemplateStyle) => {
    onUpdate({ 
      template: style,
      backgroundImageUrl: DEFAULT_BACKGROUNDS[style]
    });
  };

  const nextFontPage = () => {
    if (fontPage < totalFontPages - 1) {
        setFontPage(prev => prev + 1);
    }
  };

  const prevFontPage = () => {
    if (fontPage > 0) {
        setFontPage(prev => prev - 1);
    }
  };

  const currentFonts = AVAILABLE_FONTS.slice(fontPage * FONTS_PER_PAGE, (fontPage + 1) * FONTS_PER_PAGE);

  const TransliterationToggle = ({ minimal = false }) => (
    INPUT_METHOD_CODES[data.language] ? (
        <button 
            onClick={() => setIsTransliterationEnabled(!isTransliterationEnabled)}
            className={`text-[10px] font-bold px-2 py-0.5 rounded cursor-pointer transition-colors flex items-center gap-1 ${isTransliterationEnabled ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-400'}`}
            title={`When enabled, typing phonetically in English + Spacebar converts text to ${data.language}`}
        >
            <Keyboard size={10} /> 
            {minimal ? 'Typing ON' : `${data.language} Typing ${isTransliterationEnabled ? 'ON' : 'OFF'}`}
        </button>
    ) : null
  );

  return (
    <div className="space-y-6 p-6 bg-white rounded-2xl shadow-xl border border-slate-100">

      {/* Header */}
      <div className="pb-2">
        <h2 className="text-2xl font-serif font-bold text-slate-900 flex items-center gap-2">
          {data.mode === AppMode.VERSE ? <Sparkles className="w-6 h-6 text-gold" /> : <Calendar className="w-6 h-6 text-blue-500" />}
          <span className="bg-gradient-to-r from-slate-900 to-slate-600 bg-clip-text text-transparent">
            {data.mode === AppMode.VERSE ? t('verse_editor') : t('event_editor')}
          </span>
        </h2>
        <p className="text-slate-400 text-sm mt-1">{t('customize_msg')}</p>
      </div>

      {/* RICH LANGUAGE SELECTOR (CONTENT LANGUAGE) */}
      <div className="relative group z-30" ref={langDropdownRef}>
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1">
          <Globe size={12} /> Target Language
        </label>
        <button 
          onClick={() => setIsLangOpen(!isLangOpen)}
          className="w-full flex items-center justify-between p-3.5 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-blue-300 hover:shadow-md transition-all group-hover:ring-2 group-hover:ring-blue-50"
        >
          <span className="font-semibold text-slate-800">{data.language}</span>
          <ChevronDown size={16} className={`text-slate-400 transition-transform ${isLangOpen ? 'rotate-180' : ''}`} />
        </button>

        {isLangOpen && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-2xl border border-slate-100 max-h-60 overflow-y-auto p-1.5 z-40 animate-in fade-in zoom-in-95 duration-200">
            {CONTENT_LANGUAGES.map(lang => (
              <button
                key={lang}
                onClick={() => {
                  const newLang = lang;
                  onUpdate({ language: newLang });
                  setIsLangOpen(false);
                }}
                className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${data.language === lang ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'}`}
              >
                {lang}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Content Input */}
      {data.mode === AppMode.VERSE ? (
        <div className="space-y-4">

          {/* RICH FIND VERSE SEARCH BAR */}
          <div className="relative z-20">
            <div className="flex justify-between items-end mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1">
                <BookOpen size={12} /> {t('find_verse')}
                </label>

                {/* Transliteration Toggle Badge */}
                <TransliterationToggle />
            </div>

            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search size={18} className="text-slate-400 group-focus-within:text-blue-500 transition-colors" />
              </div>
              <input 
                type="text" 
                placeholder={isTransliterationEnabled && data.language !== 'English' ? `Type in ${data.language} (e.g. mark...)` : t('search_placeholder')}
                className="w-full pl-10 pr-12 py-3.5 bg-white border border-slate-200 rounded-xl shadow-sm text-slate-800 font-medium placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-400 transition-all"
                value={verseQuery}
                onChange={handleQueryChange}
                onKeyDown={(e) => e.key === 'Enter' && handleSearchVerse()}
              />
              <button 
                onClick={handleSearchVerse}
                disabled={isSearching}
                className="absolute right-2 top-2 p-1.5 bg-slate-100 text-slate-500 rounded-lg hover:bg-blue-600 hover:text-white transition-all disabled:opacity-50"
              >
                {isSearching ? <span className="block w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></span> : <ChevronDown className="rotate-[-90deg]" size={16} />}
              </button>
            </div>
            {isTransliterationEnabled && data.language !== 'English' && (
                <p className="text-[10px] text-slate-400 mt-1 pl-1">Tip: Type phonetically and press <b>Space</b> to convert to {data.language}.</p>
            )}
          </div>

          <div className="space-y-0 shadow-sm rounded-xl overflow-hidden border border-slate-200 focus-within:ring-2 focus-within:ring-blue-50 focus-within:border-blue-300 transition-all">
             <textarea 
               className="w-full p-4 h-28 text-base bg-slate-900 text-white placeholder-slate-400 resize-none outline-none font-serif leading-relaxed"
               value={data.verseText}
               onChange={(e) => onUpdate({ verseText: e.target.value })}
               placeholder={t('verse_text_placeholder')}
             />
             <div className="bg-slate-800 px-4 py-2 border-t border-slate-700 flex items-center gap-2">
               <span className="text-xs font-bold text-slate-400 uppercase">Ref:</span>
               <input 
                 type="text"
                 className="flex-1 bg-transparent text-sm font-bold text-slate-200 outline-none placeholder-slate-500"
                 value={data.verseReference}
                 onChange={(e) => onUpdate({ verseReference: e.target.value })}
                 placeholder="Genesis 1:1"
               />
               {isTranslating && <span className="text-xs text-blue-400 font-medium animate-pulse">Translating...</span>}
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="relative">
            <div className="flex justify-between items-center mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('event_title')}</label>
                <TransliterationToggle />
            </div>
            <input 
              type="text" 
              placeholder="e.g. Youth Worship Night"
              className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm font-bold text-white focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all placeholder:text-slate-500"
              value={data.eventTitle}
              onChange={(e) => handleSmartInput(e, data.eventTitle, (v) => onUpdate({ eventTitle: v }))}
            />
          </div>
          <div className="relative">
             <div className="flex justify-between items-center mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('event_details')}</label>
                {/* Added visual indicator for Details as requested by user */}
                {isTransliterationEnabled && data.language !== 'English' && INPUT_METHOD_CODES[data.language] && (
                    <span className="text-[10px] bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded font-bold flex items-center gap-1">
                        <Keyboard size={8} /> Typing ON
                    </span>
                )}
             </div>
             <textarea 
               placeholder={t('event_details_placeholder')}
               className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm h-28 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all resize-none text-white placeholder:text-slate-500"
               value={data.eventDetails}
               onChange={(e) => handleSmartInput(e, data.eventDetails, (v) => onUpdate({ eventDetails: v }))}
             />
             {isTransliterationEnabled && data.language !== 'English' && (
                <p className="text-[10px] text-slate-500 mt-1 pl-1">Phonetic typing active (Space or Enter to convert).</p>
             )}
          </div>
        </div>
      )}

      {/* Typography Section */}
      <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-4 relative z-10">
        <div className="flex items-center justify-between">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1">
            <Palette size={12} /> {t('typography')}
            </label>

            {/* AI Font Generator Toggle */}
            <button 
                onClick={() => setIsAiFontMode(!isAiFontMode)}
                className={`text-xs px-2 py-1 rounded-md flex items-center gap-1 transition-colors ${isAiFontMode ? 'bg-purple-100 text-purple-700 font-bold' : 'text-slate-400 hover:bg-slate-100'}`}
                title="Generate AI Font Recommendations"
            >
                <Wand2 size={12} /> AI Fonts
            </button>
        </div>

        {/* AI Font Input Area */}
        {isAiFontMode && (
             <div className="flex gap-2 animate-in slide-in-from-top-2 duration-300">
                <input 
                    type="text" 
                    placeholder="Describe mood (e.g. 'Spooky', 'Retro', 'Elegant')..."
                    className="flex-1 px-3 py-2 text-sm border border-purple-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-100"
                    value={fontAiQuery}
                    onChange={(e) => setFontAiQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAiFontGeneration()}
                />
                <button 
                    onClick={handleAiFontGeneration}
                    disabled={isGeneratingFont}
                    className="bg-purple-600 text-white px-3 py-2 rounded-lg hover:bg-purple-700 disabled:opacity-50 transition-colors"
                >
                    {isGeneratingFont ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"/> : <Sparkles size={16} />}
                </button>
             </div>
        )}

        {/* Font Slider (Paginated Grid) */}
        <div className="relative bg-white border border-slate-200 rounded-xl shadow-sm p-2 overflow-hidden">
             <div className="flex justify-between items-center mb-2 px-1">
                <button 
                  onClick={prevFontPage}
                  disabled={fontPage === 0}
                  className="p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors"
                >
                    <ChevronLeft size={20} />
                </button>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    Font ({fontPage + 1}/{totalFontPages})
                </span>
                <button 
                  onClick={nextFontPage}
                  disabled={fontPage === totalFontPages - 1}
                  className={`p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors ${fontPage < totalFontPages - 1 ? 'animate-pulse text-blue-500' : ''}`}
                >
                    <ChevronRight size={20} />
                </button>
             </div>

             <div className="grid grid-cols-2 gap-2">
                {currentFonts.map((font) => (
                    <button
                        key={font.name}
                        onClick={() => onUpdate({ fontFamily: font.value })}
                        className={`p-2.5 rounded-lg border text-center transition-all h-14 flex items-center justify-center ${data.fontFamily === font.value ? 'bg-blue-50 border-blue-400 text-blue-700 ring-1 ring-blue-100' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-white hover:border-blue-200'}`}
                        title={font.name}
                    >
                        <span className="truncate w-full text-sm" style={{ fontFamily: font.value.split(',')[0].replace(/'/g, "") }}>
                            {font.name.split('(')[0].trim()}
                        </span>
                    </button>
                ))}
             </div>

             {/* Pagination Dots */}
             <div className="flex justify-center gap-1.5 mt-2">
                {Array.from({ length: totalFontPages }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`w-1.5 h-1.5 rounded-full transition-colors ${i === fontPage ? 'bg-slate-800' : 'bg-slate-300'}`} 
                    />
                ))}
             </div>
        </div>

        {/* Color Palette & Gradient */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-4">
           {/* Color Header + Custom Picker */}
           <div className="flex justify-between items-center">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{t('text_color')}</label>
              <div className="flex items-center gap-2">
                 <div className="w-5 h-5 rounded-full border border-slate-200 shadow-inner overflow-hidden relative cursor-pointer ring-1 ring-offset-1 ring-slate-100">
                   <input 
                     type="color" 
                     value={data.textColor.startsWith('linear') ? '#ffffff' : data.textColor}
                     onChange={(e) => onUpdate({ textColor: e.target.value })}
                     className="absolute -top-2 -left-2 w-10 h-10 cursor-pointer p-0 opacity-0" 
                   />
                   <div className="w-full h-full" style={{ background: data.textColor }}></div>
                 </div>
              </div>
           </div>

           {/* Color Grid */}
           <div className="space-y-3">
              <div className="flex justify-between">
                {LIGHT_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>
              <div className="flex justify-between">
                {DARK_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>

              {/* Gradient Options */}
              <div className="pt-2 border-t border-slate-100">
                 <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">Gradients</p>
                 <div className="flex justify-between">
                    {GRADIENT_COLORS.map((gradient, i) => (
                        <button
                            key={i}
                            onClick={() => onUpdate({ textColor: gradient })}
                            className={`w-6 h-6 rounded-full border transition-all ${data.textColor === gradient ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                            style={{ background: gradient }}
                            title="Gradient"
                        />
                    ))}
                 </div>
              </div>
           </div>

           <div className="h-px bg-slate-100 w-full my-2"></div>

           {/* Text Effects Selector */}
           <div className="pt-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 block">{t('text_effects')}</label>
              <div className="grid grid-cols-3 gap-2">
                 {TEXT_EFFECTS.map((effect) => (
                    <button
                        key={effect.id}
                        onClick={() => onUpdate({ textEffect: effect.id })}
                        className={`text-xs py-2 px-1 rounded-lg border transition-all font-medium ${data.textEffect === effect.id ? 'bg-blue-50 border-blue-400 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:border-blue-200'}`}
                        style={{ fontFamily: 'sans-serif' }}
                    >
                        <span style={effect.style as any}>Aa</span> {effect.label}
                    </button>
                 ))}
              </div>
           </div>
        </div>
      </div>

      {/* Custom Name */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('footer_label')}</label>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl p-3 focus-within:bg-white focus-within:border-blue-300 focus-within:ring-4 focus-within:ring-blue-50 transition-all">
          <Type size={16} className="text-slate-400" />
          <input 
            type="text" 
            placeholder="Family Name / Church Name"
            className="flex-1 outline-none bg-transparent text-sm font-medium text-slate-800"
            value={data.customName}
            onChange={(e) => onUpdate({ customName: e.target.value })}
          />
        </div>
      </div>

      {/* Template Selection */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('theme')}</label>
        <div className="grid grid-cols-5 gap-3">
          {Object.values(TemplateStyle).map((style) => (
            <button
              key={style}
              onClick={() => handleTemplateChange(style)}
              className={`group relative w-full aspect-[3/4] rounded-xl border-2 transition-all shadow-sm overflow-hidden ${data.template === style ? 'border-blue-600 ring-2 ring-blue-100 scale-105' : 'border-transparent hover:border-blue-200 hover:scale-105'}`}
              title={style}
            >
               {/* Use Real Image Thumbnail */}
               <div className="w-full h-full bg-cover bg-center transition-transform group-hover:scale-110 duration-700"
                    style={{ backgroundImage: `url(${DEFAULT_BACKGROUNDS[style]})` }}
               ></div>

               {/* Label Overlay */}
               <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent p-1.5 pt-4 flex justify-center">
                  <span className="text-[9px] font-bold text-white uppercase tracking-wider">{style}</span>
               </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default EditorPanel;

import React, { useState, useRef, useEffect } from 'react';
import { AppMode, PosterData, TemplateStyle, TextEffect } from '../types';
import { CONTENT_LANGUAGES, DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, UI_TRANSLATIONS, SUPPORTED_LANGUAGES, INPUT_METHOD_CODES } from '../constants';
import { fetchVerse } from '../services/bibleService';
import { translateText, translateReference, recommendFonts, interpretVerseReference } from '../services/geminiService';
import { Search, Sparkles, Type, Calendar, Palette, ChevronDown, Globe, BookOpen, Wand2, ChevronLeft, ChevronRight, Keyboard } from 'lucide-react';

interface Props {
  data: PosterData;
  onUpdate: (data: Partial<PosterData>) => void;
}

const EditorPanel: React.FC<Props> = ({ data, onUpdate }) => {
  const [verseQuery, setVerseQuery] = useState("");
  const [isSearching, setIsSearching] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);

  // Font AI State
  const [isAiFontMode, setIsAiFontMode] = useState(false);
  const [fontAiQuery, setFontAiQuery] = useState("");
  const [isGeneratingFont, setIsGeneratingFont] = useState(false);
  const [suggestedFonts, setSuggestedFonts] = useState<string[]>([]);

  // Font Carousel State
  const [fontPage, setFontPage] = useState(0);
  const FONTS_PER_PAGE = 6;
  const totalFontPages = Math.ceil(AVAILABLE_FONTS.length / FONTS_PER_PAGE);

  // State for custom dropdowns
  const [isLangOpen, setIsLangOpen] = useState(false);
  const langDropdownRef = useRef<HTMLDivElement>(null);

  // Transliteration State
  const [isTransliterationEnabled, setIsTransliterationEnabled] = useState(true);

  const LIGHT_COLORS = [
    "#FFFFFF", "#F1F5F9", "#FEF08A", "#BAE6FD", "#FECDD3", "#BBF7D0", "#E9D5FF"
  ];
  const DARK_COLORS = [
    "#000000", "#334155", "#1E3A8A", "#881337", "#14532D", "#581C87", "#451A03"
  ];

  // New Gradient Colors
  const GRADIENT_COLORS = [
    "linear-gradient(to right, #bf953f, #fcf6ba, #b38728, #fbf5b7, #aa771c)", // Gold
    "linear-gradient(to right, #D7D7D7, #FFFFFF, #EAEAEA, #C0C0C0)", // Silver
    "linear-gradient(to right, #ff9a9e 0%, #fecfef 99%, #fecfef 100%)", // Rose
    "linear-gradient(to right, #4facfe 0%, #00f2fe 100%)", // Blue
    "linear-gradient(135deg, #FFF 0%, #000 100%)", // Mono
    "linear-gradient(to right, #f83600 0%, #f9d423 100%)", // Fire
  ];

  const TEXT_EFFECTS = [
    { id: TextEffect.NONE, label: 'None', style: {} },
    { id: TextEffect.SHADOW_SOFT, label: 'Soft', style: { textShadow: '0 2px 4px rgba(0,0,0,0.4)' } },
    { id: TextEffect.SHADOW_HARD, label: 'Bold', style: { textShadow: '2px 2px 0 #000' } },
    { id: TextEffect.OUTLINE, label: 'Outline', style: { WebkitTextStroke: '1px black', color: 'transparent' } },
    { id: TextEffect.NEON, label: 'Neon', style: { textShadow: '0 0 5px #fff, 0 0 10px currentColor' } },
    { id: TextEffect.RETRO, label: 'Retro', style: { textShadow: '2px 2px 0 #ccc, 4px 4px 0 #999' } },
  ];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (langDropdownRef.current && !langDropdownRef.current.contains(event.target as Node)) {
        setIsLangOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Helpers
  const currentLangCode = data.interfaceLanguage || 'en';
  const t = (key: keyof typeof UI_TRANSLATIONS['en']) => {
    // @ts-ignore - dynamic key access
    return UI_TRANSLATIONS[currentLangCode]?.[key] || UI_TRANSLATIONS['en'][key] || key;
  };

  // --- Transliteration Logic ---
  const handleTransliterate = async (word: string): Promise<string> => {
    const code = INPUT_METHOD_CODES[data.language];
    if (!code || !word) return word;

    try {
        const response = await fetch(`https://inputtools.google.com/request?text=${word}&itc=${code}&num=1&cp=0&cs=1&ie=utf-8&oe=utf-8&app=demopage`);
        const json = await response.json();
        // Structure: ["SUCCESS", [ [ "input_word", [ "suggestion1", ... ] ] ] ]
        if (json[0] === 'SUCCESS' && json[1] && json[1][0] && json[1][0][1]) {
            return json[1][0][1][0]; // Return the first suggestion
        }
    } catch (e) {
        console.error("Transliteration failed", e);
    }
    return word;
  };

  // Reusable Smart Input Handler for Transliteration
  const handleSmartInput = async (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
    currentValue: string,
    updateState: (val: string) => void
  ) => {
    const newVal = e.target.value;

    // Determine the last character typed (or delimiter)
    const delimiter = newVal.slice(-1);
    const isDelimiter = delimiter === ' ' || delimiter === '\n'; // Handle Space or Enter

    if (isTransliterationEnabled && data.language !== 'English' && isDelimiter) {
        const textBeforeDelimiter = newVal.slice(0, -1);
        const match = textBeforeDelimiter.match(/([^\s]+)$/); // Find last word

        if (match) {
            const lastWord = match[1];
            // Only convert if it's alphanumeric (English typing)
            if (/^[a-zA-Z0-9]+$/.test(lastWord)) {
                const translated = await handleTransliterate(lastWord);
                if (translated !== lastWord) {
                    const prefix = textBeforeDelimiter.substring(0, textBeforeDelimiter.length - lastWord.length);
                    updateState(prefix + translated + delimiter);
                    return;
                }
            }
        }
    }

    updateState(newVal);
  };

  const handleQueryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      handleSmartInput(e, verseQuery, setVerseQuery);
  };

  // --- Language Change & Auto-Translate Logic ---
  const handleLanguageChange = async (newLang: string) => {
    // 1. Update Language State immediately
    onUpdate({ language: newLang });
    setIsLangOpen(false);

    // 2. Trigger Auto-Translation
    if (!process.env.API_KEY) return;
    setIsTranslating(true);

    try {
        if (data.mode === AppMode.EVENT) {
            // Translate both fields in parallel if they have content
            const promises: Promise<string>[] = [];

            if (data.eventTitle && data.eventTitle.trim()) {
                promises.push(translateText(data.eventTitle, newLang));
            } else {
                promises.push(Promise.resolve(data.eventTitle));
            }

            if (data.eventDetails && data.eventDetails.trim()) {
                promises.push(translateText(data.eventDetails, newLang));
            } else {
                promises.push(Promise.resolve(data.eventDetails));
            }

            const [newTitle, newDetails] = await Promise.all(promises);
            onUpdate({ eventTitle: newTitle, eventDetails: newDetails });

        } else if (data.mode === AppMode.VERSE) {
            // Verse Mode: Translate Text and Reference
            if (data.verseText && data.verseText.trim()) {
                 const [translatedText, translatedRef] = await Promise.all([
                    translateText(data.verseText, newLang),
                    // Use English ref as source if available to prevent drift
                    translateReference(data.verseReferenceEnglish || data.verseReference, newLang)
                 ]);
                 onUpdate({ verseText: translatedText, verseReference: translatedRef });
            }
        }
    } catch (e) {
        console.error("Auto-translation failed", e);
    } finally {
        setIsTranslating(false);
    }
  };

  // -----------------------------

  const handleSearchVerse = async () => {
    if (!verseQuery) return;
    setIsSearching(true);

    // Find the Bible Version ID for the current language
    const langConfig = SUPPORTED_LANGUAGES.find(l => l.code === data.interfaceLanguage);
    const bibleVersion = langConfig?.bibleVersion || 'web'; // Default to WEB (English)

    // INTERCEPT: If the query is likely not English (because user typed in localized language),
    // we need to convert it to English Reference first (e.g. "मार्क 3:7" -> "Mark 3:7")
    // otherwise the API will fail.
    let searchQuery = verseQuery;
    if (data.language !== 'English' && /[^\x00-\x7F]/.test(verseQuery)) {
        searchQuery = await interpretVerseReference(verseQuery);
        console.log("Interpreted Search Query:", searchQuery);
    }

    // Pass the standard English version to fetchVerse
    const result = await fetchVerse(searchQuery, bibleVersion);
    setIsSearching(false);

    if (result) {
      // 1. Initially set what we got. 
      // Assumption: The API returns standard English refs usually, or we treat it as the "Source" ref.
      onUpdate({ 
        verseText: result.text,
        verseReference: result.reference, 
        verseReferenceEnglish: result.reference 
      });

      // 2. If the user has explicitly selected a Target Language that is NOT English,
      // translate the text AND reference.
      // NOTE: We also pass the *User's Typed Query* (verseQuery) as the potential reference 
      // if it was already in the target language!
      if (data.language !== 'English') {
         // If the user typed in the target language (e.g. Hindi), use that as the display reference immediately
         // otherwise translate it.
         if (/[^\x00-\x7F]/.test(verseQuery)) {
             // User typed localized ref, use it!
             onUpdate({ verseReference: verseQuery });
             // Just translate text
             const translatedText = await translateText(result.text, data.language);
             onUpdate({ verseText: translatedText });
         } else {
             // User typed English ref, so translate everything
             handleTranslate(result.text, data.language, result.reference);
         }
      }
    } else {
      alert(`Verse not found for "${searchQuery}". Try format 'John 3:16'`);
    }
  };

  const handleTranslate = async (text: string, langName: string, ref: string) => {
    setIsTranslating(true);

    // 1. Translate the Text
    const translatedTextPromise = translateText(text, langName);

    // 2. Translate the Reference explicitly if not English
    let translatedRefPromise = Promise.resolve(ref);
    if (langName !== 'English') {
        translatedRefPromise = translateReference(ref, langName);
    }

    const [translatedText, translatedRef] = await Promise.all([translatedTextPromise, translatedRefPromise]);

    // 3. Update State:
    onUpdate({ 
        verseText: translatedText, 
        verseReference: translatedRef, 
        verseReferenceEnglish: ref // Preserves the source/English ref
    });

    setIsTranslating(false);
  };

  const handleAiFontGeneration = async () => {
    if (!fontAiQuery.trim()) return;
    setIsGeneratingFont(true);
    const result = await recommendFonts(fontAiQuery);
    setIsGeneratingFont(false);

    if (result.fontValues.length > 0) {
      setSuggestedFonts(result.fontValues);
      onUpdate({ fontFamily: result.fontValues[0] });
      if (result.suggestedColor) {
        onUpdate({ textColor: result.suggestedColor });
      }
      setIsAiFontMode(false); 
    } else {
      alert("Could not find matching fonts.");
    }
  };

  const handleTemplateChange = (style: TemplateStyle) => {
    onUpdate({ 
      template: style,
      backgroundImageUrl: DEFAULT_BACKGROUNDS[style]
    });
  };

  const nextFontPage = () => {
    if (fontPage < totalFontPages - 1) {
        setFontPage(prev => prev + 1);
    }
  };

  const prevFontPage = () => {
    if (fontPage > 0) {
        setFontPage(prev => prev - 1);
    }
  };

  const currentFonts = AVAILABLE_FONTS.slice(fontPage * FONTS_PER_PAGE, (fontPage + 1) * FONTS_PER_PAGE);

  const TransliterationToggle = ({ minimal = false }) => (
    INPUT_METHOD_CODES[data.language] ? (
        <button 
            onClick={() => setIsTransliterationEnabled(!isTransliterationEnabled)}
            className={`text-[10px] font-bold px-2 py-0.5 rounded cursor-pointer transition-colors flex items-center gap-1 ${isTransliterationEnabled ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-400'}`}
            title={`When enabled, typing phonetically in English + Spacebar converts text to ${data.language}`}
        >
            <Keyboard size={10} /> 
            {minimal ? 'Typing ON' : `${data.language} Typing ${isTransliterationEnabled ? 'ON' : 'OFF'}`}
        </button>
    ) : null
  );

  return (
    <div className="space-y-6 p-6 bg-white rounded-2xl shadow-xl border border-slate-100">

      {/* Header */}
      <div className="pb-2">
        <h2 className="text-2xl font-serif font-bold text-slate-900 flex items-center gap-2">
          {data.mode === AppMode.VERSE ? <Sparkles className="w-6 h-6 text-gold" /> : <Calendar className="w-6 h-6 text-blue-500" />}
          <span className="bg-gradient-to-r from-slate-900 to-slate-600 bg-clip-text text-transparent">
            {data.mode === AppMode.VERSE ? t('verse_editor') : t('event_editor')}
          </span>
        </h2>
        <p className="text-slate-400 text-sm mt-1">{t('customize_msg')}</p>
      </div>

      {/* RICH LANGUAGE SELECTOR (CONTENT LANGUAGE) */}
      <div className="relative group z-30" ref={langDropdownRef}>
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1">
          <Globe size={12} /> Target Language
        </label>
        <button 
          onClick={() => setIsLangOpen(!isLangOpen)}
          className="w-full flex items-center justify-between p-3.5 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-blue-300 hover:shadow-md transition-all group-hover:ring-2 group-hover:ring-blue-50"
        >
          <span className="font-semibold text-slate-800">{data.language}</span>
          <ChevronDown size={16} className={`text-slate-400 transition-transform ${isLangOpen ? 'rotate-180' : ''}`} />
        </button>

        {isLangOpen && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-2xl border border-slate-100 max-h-60 overflow-y-auto p-1.5 z-40 animate-in fade-in zoom-in-95 duration-200">
            {CONTENT_LANGUAGES.map(lang => (
              <button
                key={lang}
                onClick={() => handleLanguageChange(lang)}
                className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${data.language === lang ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50'}`}
              >
                {lang}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Content Input */}
      {data.mode === AppMode.VERSE ? (
        <div className="space-y-4">

          {/* RICH FIND VERSE SEARCH BAR */}
          <div className="relative z-20">
            <div className="flex justify-between items-end mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1">
                <BookOpen size={12} /> {t('find_verse')}
                </label>

                {/* Transliteration Toggle Badge */}
                <TransliterationToggle />
            </div>

            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search size={18} className="text-slate-400 group-focus-within:text-blue-500 transition-colors" />
              </div>
              <input 
                type="text" 
                placeholder={isTransliterationEnabled && data.language !== 'English' ? `Type in ${data.language} (e.g. mark...)` : t('search_placeholder')}
                className="w-full pl-10 pr-12 py-3.5 bg-white border border-slate-200 rounded-xl shadow-sm text-slate-800 font-medium placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-100 focus:border-blue-400 transition-all"
                value={verseQuery}
                onChange={handleQueryChange}
                onKeyDown={(e) => e.key === 'Enter' && handleSearchVerse()}
              />
              <button 
                onClick={handleSearchVerse}
                disabled={isSearching}
                className="absolute right-2 top-2 p-1.5 bg-slate-100 text-slate-500 rounded-lg hover:bg-blue-600 hover:text-white transition-all disabled:opacity-50"
              >
                {isSearching ? <span className="block w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></span> : <ChevronDown className="rotate-[-90deg]" size={16} />}
              </button>
            </div>
            {isTransliterationEnabled && data.language !== 'English' && (
                <p className="text-[10px] text-slate-400 mt-1 pl-1">Tip: Type phonetically and press <b>Space</b> to convert to {data.language}.</p>
            )}
          </div>

          <div className="space-y-0 shadow-sm rounded-xl overflow-hidden border border-slate-200 focus-within:ring-2 focus-within:ring-blue-50 focus-within:border-blue-300 transition-all">
             <textarea 
               className="w-full p-4 h-28 text-base bg-slate-900 text-white placeholder-slate-400 resize-none outline-none font-serif leading-relaxed"
               value={data.verseText}
               onChange={(e) => onUpdate({ verseText: e.target.value })}
               placeholder={t('verse_text_placeholder')}
             />
             <div className="bg-slate-800 px-4 py-2 border-t border-slate-700 flex items-center gap-2">
               <span className="text-xs font-bold text-slate-400 uppercase">Ref:</span>
               <input 
                 type="text"
                 className="flex-1 bg-transparent text-sm font-bold text-slate-200 outline-none placeholder-slate-500"
                 value={data.verseReference}
                 onChange={(e) => onUpdate({ verseReference: e.target.value })}
                 placeholder="Genesis 1:1"
               />
               {isTranslating && <span className="text-xs text-blue-400 font-medium animate-pulse">Translating...</span>}
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="relative">
            <div className="flex justify-between items-center mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center">
                    {t('event_title')}
                    {isTranslating && data.mode === AppMode.EVENT && <span className="text-[10px] text-blue-500 font-normal ml-2 animate-pulse">Translating...</span>}
                </label>
                <TransliterationToggle />
            </div>
            <input 
              type="text" 
              placeholder="e.g. Youth Worship Night"
              className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm font-bold text-white focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all placeholder:text-slate-500"
              value={data.eventTitle}
              onChange={(e) => handleSmartInput(e, data.eventTitle, (v) => onUpdate({ eventTitle: v }))}
            />
          </div>
          <div className="relative">
             <div className="flex justify-between items-center mb-1.5">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center">
                    {t('event_details')}
                    {isTranslating && data.mode === AppMode.EVENT && <span className="text-[10px] text-blue-500 font-normal ml-2 animate-pulse">Translating...</span>}
                </label>
                {/* Added visual indicator for Details as requested by user */}
                {isTransliterationEnabled && data.language !== 'English' && INPUT_METHOD_CODES[data.language] && (
                    <span className="text-[10px] bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded font-bold flex items-center gap-1">
                        <Keyboard size={8} /> Typing ON
                    </span>
                )}
             </div>
             <textarea 
               placeholder={t('event_details_placeholder')}
               className="w-full p-3.5 bg-slate-900 border border-slate-700 rounded-xl shadow-sm h-28 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-900/50 transition-all resize-none text-white placeholder:text-slate-500"
               value={data.eventDetails}
               onChange={(e) => handleSmartInput(e, data.eventDetails, (v) => onUpdate({ eventDetails: v }))}
             />
             {isTransliterationEnabled && data.language !== 'English' && (
                <p className="text-[10px] text-slate-500 mt-1 pl-1">Phonetic typing active (Space or Enter to convert).</p>
             )}
          </div>
        </div>
      )}

      {/* Typography Section */}
      <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-4 relative z-10">
        <div className="flex items-center justify-between">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1">
            <Palette size={12} /> {t('typography')}
            </label>

            {/* AI Font Generator Toggle */}
            <button 
                onClick={() => setIsAiFontMode(!isAiFontMode)}
                className={`text-xs px-2 py-1 rounded-md flex items-center gap-1 transition-colors ${isAiFontMode ? 'bg-purple-100 text-purple-700 font-bold' : 'text-slate-400 hover:bg-slate-100'}`}
                title="Generate AI Font Recommendations"
            >
                <Wand2 size={12} /> AI Fonts
            </button>
        </div>

        {/* AI Font Input Area */}
        {isAiFontMode && (
             <div className="flex gap-2 animate-in slide-in-from-top-2 duration-300">
                <input 
                    type="text" 
                    placeholder="Describe mood (e.g. 'Spooky', 'Retro', 'Elegant')..."
                    className="flex-1 px-3 py-2 text-sm border border-purple-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-100"
                    value={fontAiQuery}
                    onChange={(e) => setFontAiQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAiFontGeneration()}
                />
                <button 
                    onClick={handleAiFontGeneration}
                    disabled={isGeneratingFont}
                    className="bg-purple-600 text-white px-3 py-2 rounded-lg hover:bg-purple-700 disabled:opacity-50 transition-colors"
                >
                    {isGeneratingFont ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"/> : <Sparkles size={16} />}
                </button>
             </div>
        )}

        {/* Font Slider (Paginated Grid) */}
        <div className="relative bg-white border border-slate-200 rounded-xl shadow-sm p-2 overflow-hidden">
             <div className="flex justify-between items-center mb-2 px-1">
                <button 
                  onClick={prevFontPage}
                  disabled={fontPage === 0}
                  className="p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors"
                >
                    <ChevronLeft size={20} />
                </button>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    Font ({fontPage + 1}/{totalFontPages})
                </span>
                <button 
                  onClick={nextFontPage}
                  disabled={fontPage === totalFontPages - 1}
                  className={`p-1 rounded-full hover:bg-slate-100 disabled:opacity-30 transition-colors ${fontPage < totalFontPages - 1 ? 'animate-pulse text-blue-500' : ''}`}
                >
                    <ChevronRight size={20} />
                </button>
             </div>

             <div className="grid grid-cols-2 gap-2">
                {currentFonts.map((font) => (
                    <button
                        key={font.name}
                        onClick={() => onUpdate({ fontFamily: font.value })}
                        className={`p-2.5 rounded-lg border text-center transition-all h-14 flex items-center justify-center ${data.fontFamily === font.value ? 'bg-blue-50 border-blue-400 text-blue-700 ring-1 ring-blue-100' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-white hover:border-blue-200'}`}
                        title={font.name}
                    >
                        <span className="truncate w-full text-sm" style={{ fontFamily: font.value.split(',')[0].replace(/'/g, "") }}>
                            {font.name.split('(')[0].trim()}
                        </span>
                    </button>
                ))}
             </div>

             {/* Pagination Dots */}
             <div className="flex justify-center gap-1.5 mt-2">
                {Array.from({ length: totalFontPages }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`w-1.5 h-1.5 rounded-full transition-colors ${i === fontPage ? 'bg-slate-800' : 'bg-slate-300'}`} 
                    />
                ))}
             </div>
        </div>

        {/* Color Palette & Gradient */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-4">
           {/* Color Header + Custom Picker */}
           <div className="flex justify-between items-center">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{t('text_color')}</label>
              <div className="flex items-center gap-2">
                 <div className="w-5 h-5 rounded-full border border-slate-200 shadow-inner overflow-hidden relative cursor-pointer ring-1 ring-offset-1 ring-slate-100">
                   <input 
                     type="color" 
                     value={data.textColor.startsWith('linear') ? '#ffffff' : data.textColor}
                     onChange={(e) => onUpdate({ textColor: e.target.value })}
                     className="absolute -top-2 -left-2 w-10 h-10 cursor-pointer p-0 opacity-0" 
                   />
                   <div className="w-full h-full" style={{ background: data.textColor }}></div>
                 </div>
              </div>
           </div>

           {/* Color Grid */}
           <div className="space-y-3">
              <div className="flex justify-between">
                {LIGHT_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>
              <div className="flex justify-between">
                {DARK_COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => onUpdate({ textColor: color })}
                    className={`w-6 h-6 rounded-full border transition-all ${data.textColor === color ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                    style={{ backgroundColor: color }}
                    title={color}
                  />
                ))}
              </div>

              {/* Gradient Options */}
              <div className="pt-2 border-t border-slate-100">
                 <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">Gradients</p>
                 <div className="flex justify-between">
                    {GRADIENT_COLORS.map((gradient, i) => (
                        <button
                            key={i}
                            onClick={() => onUpdate({ textColor: gradient })}
                            className={`w-6 h-6 rounded-full border transition-all ${data.textColor === gradient ? 'ring-2 ring-blue-500 scale-110 border-white' : 'border-slate-200 hover:scale-110'}`}
                            style={{ background: gradient }}
                            title="Gradient"
                        />
                    ))}
                 </div>
              </div>
           </div>

           <div className="h-px bg-slate-100 w-full my-2"></div>

           {/* Text Effects Selector */}
           <div className="pt-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 block">{t('text_effects')}</label>
              <div className="grid grid-cols-3 gap-2">
                 {TEXT_EFFECTS.map((effect) => (
                    <button
                        key={effect.id}
                        onClick={() => onUpdate({ textEffect: effect.id })}
                        className={`text-xs py-2 px-1 rounded-lg border transition-all font-medium ${data.textEffect === effect.id ? 'bg-blue-50 border-blue-400 text-blue-700' : 'bg-white border-slate-200 text-slate-600 hover:border-blue-200'}`}
                        style={{ fontFamily: 'sans-serif' }}
                    >
                        <span style={effect.style as any}>Aa</span> {effect.label}
                    </button>
                 ))}
              </div>
           </div>
        </div>
      </div>

      {/* Custom Name */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('footer_label')}</label>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl p-3 focus-within:bg-white focus-within:border-blue-300 focus-within:ring-4 focus-within:ring-blue-50 transition-all">
          <Type size={16} className="text-slate-400" />
          <input 
            type="text" 
            placeholder="Family Name / Church Name"
            className="flex-1 outline-none bg-transparent text-sm font-medium text-slate-800"
            value={data.customName}
            onChange={(e) => onUpdate({ customName: e.target.value })}
          />
        </div>
      </div>

      {/* Template Selection */}
      <div className="space-y-2">
        <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">{t('theme')}</label>
        <div className="grid grid-cols-5 gap-3">
          {Object.values(TemplateStyle).map((style) => (
            <button
              key={style}
              onClick={() => handleTemplateChange(style)}
              className={`group relative w-full aspect-[3/4] rounded-xl border-2 transition-all shadow-sm overflow-hidden ${data.template === style ? 'border-blue-600 ring-2 ring-blue-100 scale-105' : 'border-transparent hover:border-blue-200 hover:scale-105'}`}
              title={style}
            >
               {/* Use Real Image Thumbnail */}
               <div className="w-full h-full bg-cover bg-center transition-transform group-hover:scale-110 duration-700"
                    style={{ backgroundImage: `url(${DEFAULT_BACKGROUNDS[style]})` }}
               ></div>

               {/* Label Overlay */}
               <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent p-1.5 pt-4 flex justify-center">
                  <span className="text-[9px] font-bold text-white uppercase tracking-wider">{style}</span>
               </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

