    const layout = layouts[index];
    updateData({ 
        layout: layout.id,
        logoPosition: layout.presets.logoPosition,
        photoPosition: layout.presets.photoPosition,
        textPosition: layout.presets.textPosition,
    });
  };

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
