    template: TemplateStyle.NATURE,
    layout: LayoutType.RIGHT_CORNER,
    posterAspect: PosterAspect.PORTRAIT, // Default aspect ratio
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,

    // Flexible Layout Defaults (Centered, 80% width, 1.0 scale)
    textPosition: { x: 50, y: 50 },
    textWidth: 80,
    textScale: 1.0, 

    // Movable Assets Defaults
    logoPosition: { x: 10, y: 10 },
    logoWidth: 16,
    photoPosition: { x: 90, y: 10 },
    photoWidth: 24,
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Close language menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (langMenuRef.current && !langMenuRef.current.contains(event.target as Node)) {
        setIsLangMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Layout Cycling Logic - Now defines positions
  const layouts = [
    { 
        id: LayoutType.RIGHT_CORNER, 
        label: 'Corner R',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 85, y: 15 }, // Top Right
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.LEFT_CORNER, 
        label: 'Corner L',
        presets: {
            logoPosition: { x: 90, y: 10 },
            photoPosition: { x: 15, y: 15 }, // Top Left
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.BOTTOM_MIDDLE, 
        label: 'Bottom',
        presets: {
            logoPosition: { x: 10, y: 88 },
            photoPosition: { x: 50, y: 85 }, // Bottom Center
            textPosition: { x: 50, y: 40 } // Text pushed up slightly
        }
    },
    { 
        id: LayoutType.CINEMATIC, 
        label: 'Cinematic',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 90, y: 10 },
            textPosition: { x: 50, y: 70 } // Text lower
        }
    },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const applyLayout = (index: number) => {
    const layout = layouts[index];
    updateData({ 
        layout: layout.id,
        logoPosition: layout.presets.logoPosition,
        photoPosition: layout.presets.photoPosition,
        textPosition: layout.presets.textPosition,
    });
  };

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    applyLayout(nextIndex);
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    applyLayout(prevIndex);
  };

  // File Upload Logic
  const triggerUpload = (field: keyof PosterData) => {
    setActiveUploadField(field);
    if (fileInputRef.current) {
      fileInputRef.current.value = ""; // Reset
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUploadField) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          updateData({ [activeUploadField]: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // AI Background Generation
  const handleAiBackgroundGen = async (type: 'abstract' | 'realistic') => {
    if (!process.env.API_KEY) {
        alert("Please configure your API Key to use AI features.");
        return;
    }

    setIsGeneratingBg(true);

    let contextText = "";

    if (type === 'abstract') {
        // Cycle through 6 abstract styles
        const modes = [
            // Mode 0: Default Artistic (Heavenly)
            "Focus on soft color gradients, smooth textures, matte finishes, heavenly light rays, and artistic color combinations.",

            // Mode 1: Solid Prime Colors with Shadow
            "A minimal, solid background using a single bold primary color (like Deep Blue, Red, or Gold) with a soft, elegant shadow vignette. Matte finish paper texture. No gradients, just solid color with depth.",

            // Mode 2: Two Color Combo
            "A smooth, artistic blend of exactly two complementary colors with soft shadowing. Modern gradient style, spiritual and clean.",

            // Mode 3: Sparkling Gradient (New)
            "A magical vertical gradient background (blue to red or similar) with a overlay of sparkling stars or soft snow dust. High resolution, ethereal, dreamy texture.",

            // Mode 4: Vintage Damask (New)
            "A rich, vintage damask pattern background (deep green, royal blue, or burgundy) with subtle floral or ornamental textures. Classic wallpaper style, elegant and spiritual.",

            // Mode 5: Rustic Texture (New)
            "A natural rustic texture background, like burlap, canvas, or linen paper. Organic and simple. Neutral or warm earth tones. Optionally with faint, simple white line art patterns."
        ];

        contextText = modes[abstractCycle];

        // Advance cycle for next click (Loop 0-5)
        setAbstractCycle((prev) => (prev + 1) % modes.length);

    } else {
        // Realistic uses verse text
        contextText = data.mode === AppMode.VERSE ? data.verseText : `${data.eventTitle} ${data.eventDetails}`;
    }

    const bgUrl = await generateBackground(data.template, type, contextText); 

    if (bgUrl) {
      updateData({ backgroundImageUrl: bgUrl });
    } else {
      alert("Failed to generate background. Please try again.");
    }
    setIsGeneratingBg(false);
  };

  const handleDownload = async () => {
    if (posterRef.current && window.html2canvas) {
      try {
        // Use a small timeout to ensure images are loaded if they were just swapped
        setTimeout(async () => {
            const canvas = await window.html2canvas(posterRef.current!, {
                useCORS: true, // Important for external images
                scale: 2, // Higher quality
                backgroundColor: null,
            });

            const link = document.createElement('a');
            link.download = `gracelens-${data.mode.toLowerCase()}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        }, 100);
      } catch (err) {
        console.error("Download failed", err);
        alert("Could not download image. Please try again.");
      }
    } else {
        alert("Download library not loaded yet.");
    }
  };

  const handleShare = () => {
    if (navigator.share) {
        alert("On a mobile device, this would open the share sheet. Generate the image first to share properly!");
    } else {
        alert("Share feature is available on mobile devices.");
    }
  };

  // Helper to get next style name for button label
  const getNextStyleName = () => {
      // The state 'abstractCycle' is the index of the style that will be generated when clicked NOW.
      const currentNames = ["Heavenly", "Solid", "Dual Tone", "Sparkle", "Vintage", "Rustic"];
      return currentNames[abstractCycle];
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileChange} 
      />

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-2xl mx-auto px-4 sm:px-6 h-auto py-3 flex flex-col sm:flex-row items-center justify-between gap-3">

          {/* Futuristic Logo */}
          <div className="flex items-center gap-3 group cursor-pointer self-start sm:self-auto">
             <div className="relative w-10 h-10 flex items-center justify-center">
                <div className="absolute inset-0 bg-cyan-500 blur-lg opacity-20 group-hover:opacity-40 transition-opacity rounded-full"></div>
                <div className="relative bg-gradient-to-br from-slate-900 to-slate-800 rounded-xl p-2 shadow-lg ring-1 ring-white/10 group-hover:ring-cyan-400/50 transition-all flex items-center justify-center">
                   <Cross className="text-cyan-400 w-full h-full" />
                </div>
                <div className="absolute -top-1 -right-1">
                    <Sparkles size={12} className="text-purple-500 fill-purple-500 animate-pulse" />
                </div>
             </div>
             <div className="flex flex-col">
                <h1 className="text-2xl font-bold tracking-tight" style={{ fontFamily: "'Orbitron', sans-serif" }}>
                  <span className="bg-clip-text text-transparent bg-gradient-to-r from-cyan-500 via-blue-600 to-purple-600">
                    GraceLens
                  </span>
                </h1>
                <span className="text-[10px] font-bold tracking-[0.2em] text-slate-400 uppercase -mt-1 pl-0.5">
                    CHRISTIAN POSTER APP
                </span>
             </div>
          </div>

          <div className="flex items-center gap-3 self-end sm:self-auto">
             {/* LANGUAGE SELECTION DROPDOWN */}
             <div className="relative" ref={langMenuRef}>
                <button
                    onClick={() => setIsLangMenuOpen(!isLangMenuOpen)} 
                    className="flex items-center gap-1.5 bg-slate-100 px-3 py-1.5 rounded-lg cursor-pointer border border-slate-200 hover:bg-slate-50 hover:border-blue-300 transition-all"
                >
                   <Languages size={14} className="text-slate-500"/>
                   <span className="text-xs font-bold text-slate-700">Selection</span>
                   <span className="text-[10px] bg-slate-200 px-1.5 rounded text-slate-600 font-mono ml-1 uppercase">{data.interfaceLanguage}</span>
                </button>

                {isLangMenuOpen && (
                    <div className="absolute top-full right-0 mt-2 w-48 bg-white rounded-xl shadow-xl border border-slate-100 max-h-80 overflow-y-auto z-50 animate-in fade-in zoom-in-95 duration-200">
                         {SUPPORTED_LANGUAGES.map(lang => (
                             <button
                                key={lang.code}
                                onClick={() => {
                                    updateData({ interfaceLanguage: lang.code, language: lang.name });
                                    setIsLangMenuOpen(false);
                                }}
                                className={`w-full text-left px-4 py-2.5 text-sm hover:bg-slate-50 transition-colors border-b border-slate-50 last:border-none ${data.interfaceLanguage === lang.code ? 'bg-blue-50 text-blue-700 font-bold' : 'text-slate-700'}`}
                             >
                                {lang.name}
                             </button>
                         ))}
                    </div>
                )}
             </div>

             {/* Tabs: High Contrast Style */}
             <nav className="flex bg-slate-100/80 p-1.5 rounded-xl shadow-inner border border-slate-200/50">
                <button 
                  onClick={() => switchMode(AppMode.VERSE)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.VERSE ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <BookOpen size={14}/> Verse
                </button>
                <button 
                  onClick={() => switchMode(AppMode.EVENT)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.EVENT ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <Calendar size={14}/> Event
                </button>
             </nav>
          </div>
        </div>
      </header>

      {/* Main Content - Centered Single Column */}
      <main className="flex-1 w-full max-w-2xl mx-auto px-4 py-8 flex flex-col items-center gap-8">

        {!process.env.API_KEY && (
           <div className="w-full bg-amber-50 border-l-4 border-amber-500 p-4 rounded-xl flex items-start gap-3 shadow-sm">
              <AlertTriangle className="text-amber-500 mt-0.5" />
              <div>
                  <h3 className="font-bold text-amber-800">API Key Missing</h3>
                  <p className="text-amber-700 text-sm">Please set your <code className="bg-amber-100 px-1 rounded">process.env.API_KEY</code> to use the AI translation and background generation features.</p>
              </div>
           </div>
        )}

        {/* 1. Poster Preview with Side Arrow Navigation */}
        <div className="relative w-fit group select-none flex flex-col items-center gap-6">

            {/* Size Selector Toolbar */}
            <div className="bg-white/80 backdrop-blur-md px-3 py-2 rounded-full border border-slate-200 shadow-sm flex items-center gap-2">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2">Size:</span>

                <button 
                   onClick={() => updateData({ posterAspect: PosterAspect.PORTRAIT })}
                   className={`p-2 rounded-full transition-all ${data.posterAspect === PosterAspect.PORTRAIT ? 'bg-blue-100 text-blue-600 ring-2 ring-blue-100' : 'text-slate-400 hover:bg-slate-100'}`}
                   title="Portrait (4:5)"
                >
                    <RectangleVertical size={18} />
                </button>

                <button 
                   onClick={() => updateData({ posterAspect: PosterAspect.SQUARE })}
                   className={`p-2 rounded-full transition-all ${data.posterAspect === PosterAspect.SQUARE ? 'bg-blue-100 text-blue-600 ring-2 ring-blue-100' : 'text-slate-400 hover:bg-slate-100'}`}
                   title="Square (1:1)"
                >
                    <Square size={18} />
                </button>

                <button 
                   onClick={() => updateData({ posterAspect: PosterAspect.LANDSCAPE })}
                   className={`p-2 rounded-full transition-all ${data.posterAspect === PosterAspect.LANDSCAPE ? 'bg-blue-100 text-blue-600 ring-2 ring-blue-100' : 'text-slate-400 hover:bg-slate-100'}`}
                   title="Desktop (16:9)"
                >
                    <Monitor size={18} />
                </button>
            </div>

            <div className="relative">
                {/* Left Arrow */}
                <button 
                    onClick={prevLayout}
                    className="absolute -left-4 md:-left-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                    title="Previous Layout"
                >
                    <ChevronLeft size={24} className="group-hover/btn:-translate-x-0.5 transition-transform" />
                </button>

                {/* Poster Container */}
                <div className="bg-white p-2 rounded-[2rem] shadow-2xl shadow-slate-200 border-4 border-white relative ring-1 ring-slate-100 transition-all duration-300 ease-out">
                    {/* Background Glow */}
                    <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 to-purple-500/10 blur-3xl rounded-full transform scale-110 z-0 pointer-events-none"></div>

                    <div className="relative z-10 rounded-3xl overflow-hidden">
                        <PosterPreview 
                            data={data} 
                            ref={posterRef} 
                            onTriggerUpload={triggerUpload} 
                            // We can pass a callback to update state from the preview
                            onUpdateData={updateData}
                        />
                    </div>
                </div>

                {/* Right Arrow */}
                <button 
                    onClick={nextLayout}
                    className="absolute -right-4 md:-right-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                    title="Next Layout"
                >
                    <ChevronRight size={24} className="group-hover/btn:translate-x-0.5 transition-transform" />
                </button>
            </div>

            {/* Layout Indicator */}
            <div className="flex justify-center items-center gap-3">
                 <div className="bg-slate-900/5 backdrop-blur-sm px-4 py-1.5 rounded-full border border-slate-200/50 flex items-center gap-2">
                    <span className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Layout:</span>
                    <span className="text-xs font-bold text-slate-800">
                        {layouts[currentLayoutIndex].label}
                    </span>
                 </div>
                 <div className="flex gap-1.5">
                    {layouts.map((l, i) => (
                        <div key={l.id} className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${i === currentLayoutIndex ? 'bg-blue-600 w-4' : 'bg-slate-300'}`} />
                    ))}
                 </div>
            </div>
        </div>

        {/* Spacer for layout indicator */}
        <div className="h-2"></div>

        {/* 2. Action Buttons (New Layout) */}
        <div className="w-full flex flex-col gap-3">

            {/* Main Actions Row: Download | Background | Share */}
            <div className="flex gap-3 w-full">

                {/* Download Button - Dark */}
                <button 
                    onClick={handleDownload}
                    className="flex-1 bg-slate-900 text-white py-3.5 rounded-2xl font-bold shadow-lg shadow-slate-200 hover:bg-black hover:scale-[1.01] active:scale-[0.99] transition-all flex justify-center items-center gap-2"
                >
                    <Download size={20} /> Download
                </button>

                {/* Background Upload Button - Light Blue */}
                <button 
                    onClick={() => triggerUpload('backgroundImageUrl')}
                    className="flex-1 bg-indigo-50 text-indigo-600 border border-indigo-100 py-3.5 rounded-2xl font-bold hover:bg-indigo-100 transition-all flex justify-center items-center gap-2"
                >
                    <ImageIcon size={20} /> Background
                </button>

                {/* Share Button - White Outline */}
                <button 
                    onClick={handleShare}
                    className="flex-1 bg-white text-slate-700 border-2 border-slate-100 py-3.5 rounded-2xl font-bold hover:bg-slate-50 hover:border-slate-200 transition-all flex justify-center items-center gap-2"
                >
                    <Share2 size={20} /> Share
                </button>
            </div>

            {/* AI Generator Buttons Split */}
            <div className="grid grid-cols-2 gap-3">
                {/* Abstract Button */}
                <button 
                    onClick={() => handleAiBackgroundGen('abstract')}
                    disabled={isGeneratingBg}
                    className="w-full bg-gradient-to-r from-purple-500 to-pink-500 text-white py-4 rounded-2xl font-bold shadow-lg hover:scale-[1.01] active:scale-[0.99] transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-70 disabled:cursor-not-allowed relative overflow-hidden group"
                >
                     {/* Shimmer */}
                     <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:animate-shimmer skew-x-12"></div>
                     {isGeneratingBg ? (
                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                     ) : (
                        <>
                           <div className="flex items-center gap-2">
                             <Palette size={18} className="text-purple-100" />
                             <span>Abstract Art</span>
                           </div>
                           <span className="text-[10px] font-normal text-purple-100 opacity-80">
                             Generate: {getNextStyleName()}
                           </span>
                        </>
                     )}
                </button>

                {/* Realistic Button */}
                <button 
                    onClick={() => handleAiBackgroundGen('realistic')}
                    disabled={isGeneratingBg}
                    className="w-full bg-gradient-to-r from-blue-600 to-cyan-600 text-white py-4 rounded-2xl font-bold shadow-lg hover:scale-[1.01] active:scale-[0.99] transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-70 disabled:cursor-not-allowed relative overflow-hidden group"
                >
                     {/* Shimmer */}
                     <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:animate-shimmer skew-x-12"></div>
                     {isGeneratingBg ? (
                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                     ) : (
                        <>
                           <div className="flex items-center gap-2">
                             <Wand2 size={18} className="text-blue-100" />
                             <span>Smart Scene</span>
                           </div>
                           <span className="text-[10px] font-normal text-blue-100 opacity-80">Matches Verse Context</span>
                        </>
                     )}
                </button>
            </div>
        </div>

        {/* 5. Editor Panel */}
        <div className="w-full">
            <EditorPanel data={data} onUpdate={updateData} />
        </div>

      </main>

      <footer className="bg-white border-t border-slate-200 mt-12 py-8">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <p className="text-slate-400 text-sm font-medium">&copy; {new Date().getFullYear()} GraceLens. AI-Powered Christian Design.</p>
          <a 
            href="https://youtube.com/@parablooms?si=pWqDcQ9u8o0_pPtD" 
            target="_blank" 
            rel="noopener noreferrer" 
            className="inline-flex items-center gap-2 mt-3 text-sm font-semibold text-slate-500 hover:text-red-600 transition-colors"
          >
            <Youtube size={16} />
            Visit Parablooms on YouTube
          </a>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { AppMode, PosterData, TemplateStyle, LayoutType, TextEffect, PosterAspect } from './types';
import { DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, SUPPORTED_LANGUAGES } from './constants';
import { generateBackground } from './services/geminiService';
import PosterPreview from './components/PosterPreview';
import EditorPanel from './components/EditorPanel';
import { Download, Share2, BookOpen, Calendar, AlertTriangle, Image as ImageIcon, Upload, ChevronRight, ChevronLeft, Sparkles, Languages, Wand2, Cross, RectangleVertical, Square, Monitor, Youtube, Palette } from 'lucide-react';

const App: React.FC = () => {
  const posterRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadField, setActiveUploadField] = useState<keyof PosterData | null>(null);
  const [isGeneratingBg, setIsGeneratingBg] = useState(false);

  // Abstract Background Cycle State (0-8)
  const [abstractCycle, setAbstractCycle] = useState(0);

  // Language Menu State
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);
  const langMenuRef = useRef<HTMLDivElement>(null);

  // Initial State
  const [data, setData] = useState<PosterData>({
    mode: AppMode.VERSE,
    verseReference: "John 3:16",
    verseReferenceEnglish: "John 3:16", // Initialize English Reference
    verseText: "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.",
    eventTitle: "Sunday Service",
    eventDetails: "Sunday, 9:00 AM\nMain Sanctuary\nPastor John Doe",
    language: "English",
    interfaceLanguage: "en", // Default UI Language
    template: TemplateStyle.NATURE,
    layout: LayoutType.RIGHT_CORNER,
    posterAspect: PosterAspect.PORTRAIT, // Default aspect ratio
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,

    // Flexible Layout Defaults (Centered, 80% width, 1.0 scale)
    textPosition: { x: 50, y: 50 },
    textWidth: 80,
    textScale: 1.0, 

    // Movable Assets Defaults
    logoPosition: { x: 10, y: 10 },
    logoWidth: 16,
    photoPosition: { x: 90, y: 10 },
    photoWidth: 24,
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Close language menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (langMenuRef.current && !langMenuRef.current.contains(event.target as Node)) {
        setIsLangMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Layout Cycling Logic - Now defines positions
  const layouts = [
    { 
        id: LayoutType.RIGHT_CORNER, 
        label: 'Corner R',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 85, y: 15 }, // Top Right
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.LEFT_CORNER, 
        label: 'Corner L',
        presets: {
            logoPosition: { x: 90, y: 10 },
            photoPosition: { x: 15, y: 15 }, // Top Left
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.BOTTOM_MIDDLE, 
        label: 'Bottom',
        presets: {
            logoPosition: { x: 10, y: 88 },
            photoPosition: { x: 50, y: 85 }, // Bottom Center
            textPosition: { x: 50, y: 40 } // Text pushed up slightly
        }
    },
    { 
        id: LayoutType.CINEMATIC, 
        label: 'Cinematic',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 90, y: 10 },
            textPosition: { x: 50, y: 70 } // Text lower
        }
    },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const applyLayout = (index: number) => {
    const layout = layouts[index];
    updateData({ 
        layout: layout.id,
        logoPosition: layout.presets.logoPosition,
        photoPosition: layout.presets.photoPosition,
        textPosition: layout.presets.textPosition,
    });
  };

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    applyLayout(nextIndex);
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    applyLayout(prevIndex);
  };

  // File Upload Logic
  const triggerUpload = (field: keyof PosterData) => {
    setActiveUploadField(field);
    if (fileInputRef.current) {
      fileInputRef.current.value = ""; // Reset
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUploadField) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          updateData({ [activeUploadField]: ev.target.result as string });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // AI Background Generation
  const handleAiBackgroundGen = async (type: 'abstract' | 'realistic') => {
    if (!process.env.API_KEY) {
        alert("Please configure your API Key to use AI features.");
        return;
    }

    setIsGeneratingBg(true);

    let contextText = "";

    if (type === 'abstract') {
        // Cycle through 9 abstract styles
        const modes = [
            // Mode 0: Default Artistic (Heavenly)
            "Focus on soft color gradients, smooth textures, matte finishes, heavenly light rays, and artistic color combinations.",

            // Mode 1: Solid Prime Colors with Shadow
            "A minimal, solid background using a single bold primary color (like Deep Blue, Red, or Gold) with a soft, elegant shadow vignette. Matte finish paper texture. No gradients, just solid color with depth.",

            // Mode 2: Two Color Combo
            "A smooth, artistic blend of exactly two complementary colors with soft shadowing. Modern gradient style, spiritual and clean.",

            // Mode 3: Sparkling Gradient
            "A magical vertical gradient background (blue to red or similar) with a overlay of sparkling stars or soft snow dust. High resolution, ethereal, dreamy texture.",

            // Mode 4: Vintage Damask
            "A rich, vintage damask pattern background (deep green, royal blue, or burgundy) with subtle floral or ornamental textures. Classic wallpaper style, elegant and spiritual.",

            // Mode 5: Rustic Texture
            "A natural rustic texture background, like burlap, canvas, or linen paper. Organic and simple. Neutral or warm earth tones. Optionally with faint, simple white line art patterns.",

            // Mode 6: Silk/Satin
            "A luxurious satin fabric texture background (deep red, royal blue, or gold). Smooth silky folds, elegant drapery, soft lighting. Photorealistic cloth texture, rich and noble.",

            // Mode 7: Winter/Snowflake Pattern
            "A deep blue or dark elegant background with a pattern of silver snowflakes and stars. Festive, spiritual, winter theme. Magical and high quality texture.",

            // Mode 8: Minimal Line Art
            "A clean cream or off-white textured paper background with minimal gold line art patterns (stars, crosses, doves, or bells). Elegant, modern, minimalist Christian design."
        ];

        contextText = modes[abstractCycle];

        // Advance cycle for next click (Loop 0-8)
        setAbstractCycle((prev) => (prev + 1) % modes.length);

    } else {
        // Realistic uses verse text
        contextText = data.mode === AppMode.VERSE ? data.verseText : `${data.eventTitle} ${data.eventDetails}`;
    }

    const bgUrl = await generateBackground(data.template, type, contextText); 

    if (bgUrl) {
      updateData({ backgroundImageUrl: bgUrl });
    } else {
      alert("Failed to generate background. Please try again.");
    }
    setIsGeneratingBg(false);
  };

  const handleDownload = async () => {
    if (posterRef.current && window.html2canvas) {
      try {
        // Use a small timeout to ensure images are loaded if they were just swapped
        setTimeout(async () => {
            const canvas = await window.html2canvas(posterRef.current!, {
                useCORS: true, // Important for external images
                scale: 2, // Higher quality
                backgroundColor: null,
            });

            const link = document.createElement('a');
            link.download = `gracelens-${data.mode.toLowerCase()}-${Date.now()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        }, 100);
      } catch (err) {
        console.error("Download failed", err);
        alert("Could not download image. Please try again.");
      }
    } else {
        alert("Download library not loaded yet.");
    }
  };

  const handleShare = () => {
    if (navigator.share) {
        alert("On a mobile device, this would open the share sheet. Generate the image first to share properly!");
    } else {
        alert("Share feature is available on mobile devices.");
    }
  };

  // Helper to get next style name for button label
  const getNextStyleName = () => {
      // The state 'abstractCycle' is the index of the style that will be generated when clicked NOW.
      const currentNames = [
          "Heavenly", "Solid", "Dual Tone", 
          "Sparkle", "Vintage", "Rustic",
          "Satin", "Snowflake", "Line Art"
      ];
      return currentNames[abstractCycle];
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans text-slate-900">

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileChange} 
      />

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-2xl mx-auto px-4 sm:px-6 h-auto py-3 flex flex-col sm:flex-row items-center justify-between gap-3">

          {/* Futuristic Logo */}
          <div className="flex items-center gap-3 group cursor-pointer self-start sm:self-auto">
             <div className="relative w-10 h-10 flex items-center justify-center">
                <div className="absolute inset-0 bg-cyan-500 blur-lg opacity-20 group-hover:opacity-40 transition-opacity rounded-full"></div>
                <div className="relative bg-gradient-to-br from-slate-900 to-slate-800 rounded-xl p-2 shadow-lg ring-1 ring-white/10 group-hover:ring-cyan-400/50 transition-all flex items-center justify-center">
                   <Cross className="text-cyan-400 w-full h-full" />
                </div>
                <div className="absolute -top-1 -right-1">
                    <Sparkles size={12} className="text-purple-500 fill-purple-500 animate-pulse" />
                </div>
             </div>
             <div className="flex flex-col">
                <h1 className="text-2xl font-bold tracking-tight" style={{ fontFamily: "'Orbitron', sans-serif" }}>
                  <span className="bg-clip-text text-transparent bg-gradient-to-r from-cyan-500 via-blue-600 to-purple-600">
                    GraceLens
                  </span>
                </h1>
                <span className="text-[10px] font-bold tracking-[0.2em] text-slate-400 uppercase -mt-1 pl-0.5">
                    CHRISTIAN POSTER APP
                </span>
             </div>
          </div>

          <div className="flex items-center gap-3 self-end sm:self-auto">
             {/* LANGUAGE SELECTION DROPDOWN */}
             <div className="relative" ref={langMenuRef}>
                <button
                    onClick={() => setIsLangMenuOpen(!isLangMenuOpen)} 
                    className="flex items-center gap-1.5 bg-slate-100 px-3 py-1.5 rounded-lg cursor-pointer border border-slate-200 hover:bg-slate-50 hover:border-blue-300 transition-all"
                >
                   <Languages size={14} className="text-slate-500"/>
                   <span className="text-xs font-bold text-slate-700">Selection</span>
                   <span className="text-[10px] bg-slate-200 px-1.5 rounded text-slate-600 font-mono ml-1 uppercase">{data.interfaceLanguage}</span>
                </button>

                {isLangMenuOpen && (
                    <div className="absolute top-full right-0 mt-2 w-48 bg-white rounded-xl shadow-xl border border-slate-100 max-h-80 overflow-y-auto z-50 animate-in fade-in zoom-in-95 duration-200">
                         {SUPPORTED_LANGUAGES.map(lang => (
                             <button
                                key={lang.code}
                                onClick={() => {
                                    updateData({ interfaceLanguage: lang.code, language: lang.name });
                                    setIsLangMenuOpen(false);
                                }}
                                className={`w-full text-left px-4 py-2.5 text-sm hover:bg-slate-50 transition-colors border-b border-slate-50 last:border-none ${data.interfaceLanguage === lang.code ? 'bg-blue-50 text-blue-700 font-bold' : 'text-slate-700'}`}
                             >
                                {lang.name}
                             </button>
                         ))}
                    </div>
                )}
             </div>

             {/* Tabs: High Contrast Style */}
             <nav className="flex bg-slate-100/80 p-1.5 rounded-xl shadow-inner border border-slate-200/50">
                <button 
                  onClick={() => switchMode(AppMode.VERSE)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.VERSE ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <BookOpen size={14}/> Verse
                </button>
                <button 
                  onClick={() => switchMode(AppMode.EVENT)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all duration-300 flex items-center gap-1.5 ${data.mode === AppMode.EVENT ? 'bg-white text-black shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:text-black hover:bg-white/50'}`}
                >
                  <Calendar size={14}/> Event
                </button>
             </nav>
          </div>
        </div>
      </header>

      {/* Main Content - Centered Single Column */}
      <main className="flex-1 w-full max-w-2xl mx-auto px-4 py-8 flex flex-col items-center gap-8">

        {!process.env.API_KEY && (
           <div className="w-full bg-amber-50 border-l-4 border-amber-500 p-4 rounded-xl flex items-start gap-3 shadow-sm">
              <AlertTriangle className="text-amber-500 mt-0.5" />
              <div>
                  <h3 className="font-bold text-amber-800">API Key Missing</h3>
                  <p className="text-amber-700 text-sm">Please set your <code className="bg-amber-100 px-1 rounded">process.env.API_KEY</code> to use the AI translation and background generation features.</p>
              </div>
           </div>
        )}

        {/* 1. Poster Preview with Side Arrow Navigation */}
        <div className="relative w-fit group select-none flex flex-col items-center gap-6">

            {/* Size Selector Toolbar */}
            <div className="bg-white/80 backdrop-blur-md px-3 py-2 rounded-full border border-slate-200 shadow-sm flex items-center gap-2">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-2">Size:</span>

                <button 
                   onClick={() => updateData({ posterAspect: PosterAspect.PORTRAIT })}
                   className={`p-2 rounded-full transition-all ${data.posterAspect === PosterAspect.PORTRAIT ? 'bg-blue-100 text-blue-600 ring-2 ring-blue-100' : 'text-slate-400 hover:bg-slate-100'}`}
                   title="Portrait (4:5)"
                >
                    <RectangleVertical size={18} />
                </button>

                <button 
                   onClick={() => updateData({ posterAspect: PosterAspect.SQUARE })}
                   className={`p-2 rounded-full transition-all ${data.posterAspect === PosterAspect.SQUARE ? 'bg-blue-100 text-blue-600 ring-2 ring-blue-100' : 'text-slate-400 hover:bg-slate-100'}`}
                   title="Square (1:1)"
                >
                    <Square size={18} />
                </button>

                <button 
                   onClick={() => updateData({ posterAspect: PosterAspect.LANDSCAPE })}
                   className={`p-2 rounded-full transition-all ${data.posterAspect === PosterAspect.LANDSCAPE ? 'bg-blue-100 text-blue-600 ring-2 ring-blue-100' : 'text-slate-400 hover:bg-slate-100'}`}
                   title="Desktop (16:9)"
                >
                    <Monitor size={18} />
                </button>
            </div>

            <div className="relative">
                {/* Left Arrow */}
                <button 
                    onClick={prevLayout}
                    className="absolute -left-4 md:-left-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                    title="Previous Layout"
                >
                    <ChevronLeft size={24} className="group-hover/btn:-translate-x-0.5 transition-transform" />
                </button>

                {/* Poster Container */}
                <div className="bg-white p-2 rounded-[2rem] shadow-2xl shadow-slate-200 border-4 border-white relative ring-1 ring-slate-100 transition-all duration-300 ease-out">
                    {/* Background Glow */}
                    <div className="absolute inset-0 bg-gradient-to-tr from-cyan-500/10 to-purple-500/10 blur-3xl rounded-full transform scale-110 z-0 pointer-events-none"></div>

                    <div className="relative z-10 rounded-3xl overflow-hidden">
                        <PosterPreview 
                            data={data} 
                            ref={posterRef} 
                            onTriggerUpload={triggerUpload} 
                            // We can pass a callback to update state from the preview
                            onUpdateData={updateData}
                        />
                    </div>
                </div>

                {/* Right Arrow */}
                <button 
                    onClick={nextLayout}
                    className="absolute -right-4 md:-right-16 top-1/2 -translate-y-1/2 z-20 bg-white hover:bg-slate-50 text-slate-800 p-4 rounded-full shadow-xl shadow-slate-200/50 border border-slate-100 transition-all hover:scale-110 active:scale-95 group/btn"
                    title="Next Layout"
                >
                    <ChevronRight size={24} className="group-hover/btn:translate-x-0.5 transition-transform" />
                </button>
            </div>

            {/* Layout Indicator */}
            <div className="flex justify-center items-center gap-3">
                 <div className="bg-slate-900/5 backdrop-blur-sm px-4 py-1.5 rounded-full border border-slate-200/50 flex items-center gap-2">
                    <span className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">Layout:</span>
                    <span className="text-xs font-bold text-slate-800">
                        {layouts[currentLayoutIndex].label}
                    </span>
                 </div>
                 <div className="flex gap-1.5">
                    {layouts.map((l, i) => (
                        <div key={l.id} className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${i === currentLayoutIndex ? 'bg-blue-600 w-4' : 'bg-slate-300'}`} />
                    ))}
                 </div>
            </div>
        </div>

        {/* Spacer for layout indicator */}
        <div className="h-2"></div>

        {/* 2. Action Buttons (New Layout) */}
        <div className="w-full flex flex-col gap-3">

            {/* Main Actions Row: Download | Background | Share */}
            <div className="flex gap-3 w-full">

                {/* Download Button - Dark */}
                <button 
                    onClick={handleDownload}
                    className="flex-1 bg-slate-900 text-white py-3.5 rounded-2xl font-bold shadow-lg shadow-slate-200 hover:bg-black hover:scale-[1.01] active:scale-[0.99] transition-all flex justify-center items-center gap-2"
                >
                    <Download size={20} /> Download
                </button>

                {/* Background Upload Button - Light Blue */}
                <button 
                    onClick={() => triggerUpload('backgroundImageUrl')}
                    className="flex-1 bg-indigo-50 text-indigo-600 border border-indigo-100 py-3.5 rounded-2xl font-bold hover:bg-indigo-100 transition-all flex justify-center items-center gap-2"
                >
                    <ImageIcon size={20} /> Background
                </button>

                {/* Share Button - White Outline */}
                <button 
                    onClick={handleShare}
                    className="flex-1 bg-white text-slate-700 border-2 border-slate-100 py-3.5 rounded-2xl font-bold hover:bg-slate-50 hover:border-slate-200 transition-all flex justify-center items-center gap-2"
                >
                    <Share2 size={20} /> Share
                </button>
            </div>

            {/* AI Generator Buttons Split */}
            <div className="grid grid-cols-2 gap-3">
                {/* Abstract Button */}
                <button 
                    onClick={() => handleAiBackgroundGen('abstract')}
                    disabled={isGeneratingBg}
                    className="w-full bg-gradient-to-r from-purple-500 to-pink-500 text-white py-4 rounded-2xl font-bold shadow-lg hover:scale-[1.01] active:scale-[0.99] transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-70 disabled:cursor-not-allowed relative overflow-hidden group"
                >
                     {/* Shimmer */}
                     <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:animate-shimmer skew-x-12"></div>
                     {isGeneratingBg ? (
                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                     ) : (
                        <>
                           <div className="flex items-center gap-2">
                             <Palette size={18} className="text-purple-100" />
                             <span>Abstract Art</span>
                           </div>
                           <span className="text-[10px] font-normal text-purple-100 opacity-80">
                             Generate: {getNextStyleName()}
                           </span>
                        </>
                     )}
                </button>

                {/* Realistic Button */}
                <button 
                    onClick={() => handleAiBackgroundGen('realistic')}
                    disabled={isGeneratingBg}
                    className="w-full bg-gradient-to-r from-blue-600 to-cyan-600 text-white py-4 rounded-2xl font-bold shadow-lg hover:scale-[1.01] active:scale-[0.99] transition-all flex flex-col items-center justify-center gap-1 disabled:opacity-70 disabled:cursor-not-allowed relative overflow-hidden group"
                >
                     {/* Shimmer */}
                     <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover:animate-shimmer skew-x-12"></div>
                     {isGeneratingBg ? (
                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                     ) : (
                        <>
                           <div className="flex items-center gap-2">
                             <Wand2 size={18} className="text-blue-100" />
                             <span>Smart Scene</span>
                           </div>
                           <span className="text-[10px] font-normal text-blue-100 opacity-80">Matches Verse Context</span>
                        </>
                     )}
                </button>
            </div>
        </div>

        {/* 5. Editor Panel */}
        <div className="w-full">
            <EditorPanel data={data} onUpdate={updateData} />
        </div>

      </main>

      <footer className="bg-white border-t border-slate-200 mt-12 py-8">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <p className="text-slate-400 text-sm font-medium">&copy; {new Date().getFullYear()} GraceLens. AI-Powered Christian Design.</p>
          <a 
            href="https://youtube.com/@parablooms?si=pWqDcQ9u8o0_pPtD" 
            target="_blank" 
            rel="noopener noreferrer" 
            className="inline-flex items-center gap-2 mt-3 text-sm font-semibold text-slate-500 hover:text-red-600 transition-colors"
          >
            <Youtube size={16} />
            Visit Parablooms on YouTube
          </a>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { AppMode, PosterData, TemplateStyle, LayoutType, TextEffect, PosterAspect } from './types';
import { DEFAULT_BACKGROUNDS, AVAILABLE_FONTS, SUPPORTED_LANGUAGES, UI_TRANSLATIONS } from './constants';
import { generateBackground } from './services/geminiService';
import PosterPreview from './components/PosterPreview';
import EditorPanel from './components/EditorPanel';
import { Download, Share2, BookOpen, Calendar, AlertTriangle, Image as ImageIcon, Upload, ChevronRight, ChevronLeft, Sparkles, Languages, Wand2, Cross, RectangleVertical, Square, Monitor, Youtube, Palette } from 'lucide-react';

const App: React.FC = () => {
  const posterRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadField, setActiveUploadField] = useState<keyof PosterData | null>(null);
  const [isGeneratingBg, setIsGeneratingBg] = useState(false);

  // Abstract Background Cycle State (0-8)
  const [abstractCycle, setAbstractCycle] = useState(0);

  // Language Menu State
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);
  const langMenuRef = useRef<HTMLDivElement>(null);

  // Initial State
  const [data, setData] = useState<PosterData>({
    mode: AppMode.VERSE,
    verseReference: "John 3:16",
    verseReferenceEnglish: "John 3:16", // Initialize English Reference
    verseText: "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.",
    eventTitle: "Sunday Service",
    eventDetails: "Sunday, 9:00 AM\nMain Sanctuary\nPastor John Doe",
    language: "English",
    interfaceLanguage: "en", // Default UI Language
    template: TemplateStyle.NATURE,
    layout: LayoutType.RIGHT_CORNER,
    posterAspect: PosterAspect.PORTRAIT, // Default aspect ratio
    backgroundImageUrl: DEFAULT_BACKGROUNDS[TemplateStyle.NATURE],
    uploadedPhotoUrl: null,
    logoUrl: null,
    customName: "",
    // New Customization fields
    fontFamily: AVAILABLE_FONTS[1].value, // Default to Playfair
    textColor: "#FFFFFF",
    textEffect: TextEffect.SHADOW_SOFT,

    // Flexible Layout Defaults (Centered, 80% width, 1.0 scale)
    textPosition: { x: 50, y: 50 },
    textWidth: 80,
    textScale: 1.0, 

    // Movable Assets Defaults
    logoPosition: { x: 10, y: 10 },
    logoWidth: 16,
    photoPosition: { x: 90, y: 10 },
    photoWidth: 24,
  });

  const updateData = (newData: Partial<PosterData>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const switchMode = (mode: AppMode) => {
    updateData({ mode });
  };

  // Close language menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (langMenuRef.current && !langMenuRef.current.contains(event.target as Node)) {
        setIsLangMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Translation Helper
  const t = (key: keyof typeof UI_TRANSLATIONS['en']) => {
    // @ts-ignore - dynamic key access
    return UI_TRANSLATIONS[data.interfaceLanguage]?.[key] || UI_TRANSLATIONS['en'][key] || key;
  };

  // Layout Cycling Logic - Now defines positions
  const layouts = [
    { 
        id: LayoutType.RIGHT_CORNER, 
        label: 'Corner R',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 85, y: 15 }, // Top Right
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.LEFT_CORNER, 
        label: 'Corner L',
        presets: {
            logoPosition: { x: 90, y: 10 },
            photoPosition: { x: 15, y: 15 }, // Top Left
            textPosition: { x: 50, y: 50 }
        }
    },
    { 
        id: LayoutType.BOTTOM_MIDDLE, 
        label: 'Bottom',
        presets: {
            logoPosition: { x: 10, y: 88 },
            photoPosition: { x: 50, y: 85 }, // Bottom Center
            textPosition: { x: 50, y: 40 } // Text pushed up slightly
        }
    },
    { 
        id: LayoutType.CINEMATIC, 
        label: 'Cinematic',
        presets: {
            logoPosition: { x: 10, y: 10 },
            photoPosition: { x: 90, y: 10 },
            textPosition: { x: 50, y: 70 } // Text lower
        }
    },
  ];

  const currentLayoutIndex = layouts.findIndex(l => l.id === data.layout);

  const applyLayout = (index: number) => {
    const layout = layouts[index];
    updateData({ 
        layout: layout.id,
        logoPosition: layout.presets.logoPosition,
        photoPosition: layout.presets.photoPosition,
        textPosition: layout.presets.textPosition,
    });
  };

  const nextLayout = () => {
    const nextIndex = (currentLayoutIndex + 1) % layouts.length;
    applyLayout(nextIndex);
  };

  const prevLayout = () => {
    const prevIndex = (currentLayoutIndex - 1 + layouts.length) % layouts.length;
    applyLayout(prevIndex);
  };

  // File Upload Logic
  const triggerUpload = (field: keyof PosterData) => {
    setActiveUploadField(field);
    if (fileInputRef.current) {
      fileInputRef.current.value = ""; // Reset
      fileInputRef.current.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUploadField) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          updateData({ [activeUploadField]: ev.target.result as string });
